 12→function computeLunarApogeePerigeeMeeus(date: Date): Map<Node, number> {
 13→	const jd = (date.getTime() / 86400000) + 2440587.5;
 14→	const t = (jd - 2451545.0) / 36525.0;
 15→	
 16→	// again Meeus Ch. 47
 17→	const omega = 83.3532465 + 4069.0137287 * t - 0.0103200 * t*t - (t*t*t)/80053;
 18→	const perigee = (omega % 360) * Math.PI / 180;
 19→	
 20→	return new Map<Node, number>([
 21→		[Node.LUNAR_PERIGEE, normalizeAngleRad(perigee)],
 22→		[Node.LUNAR_APOGEE, normalizeAngleRad(perigee + Math.PI)]
 23→	]);
 24→}
 25→
 26→function computeLunarApogeePerigeeExact(date: Date): Map<Node, number> {
 27→	const s = GeoMoonState(date);
 28→	
 29→	const GM = 8.887692587023177e-10;  // earth's gravitational parameter in AU^3 / day^2
 30→	const r = Math.sqrt(s.x*s.x + s.y*s.y + s.z*s.z);
 31→	
 32→	// angular momentum
 33→	const h = {
 34→		x: s.y * s.vz - s.z * s.vy,
 35→		y: s.z * s.vx - s.x * s.vz,
 36→		z: s.x * s.vy - s.y * s.vx
 37→	};
 38→	
 39→	// eccentricity vector points toward perigee
 40→	const rVec = {x: s.x, y: s.y, z: s.z};
 41→	const vVec = {x: s.vx, y: s.vy, z: s.vz};
 42→	
 43→	// e = (v x h)/GM - r/mod(r)
 44→	const vxh = {
 45→		x: vVec.y * h.z - vVec.z * h.y,
 46→		y: vVec.z * h.x - vVec.x * h.z,
 47→		z: vVec.x * h.y - vVec.y * h.x
 48→	};
 49→	const e = {
 50→		x: vxh.x/GM - rVec.x/r,
 51→		y: vxh.y/GM - rVec.y/r,
 52→		z: vxh.z/GM - rVec.z/r,
 53→		t: MakeTime(date)
 54→	};
 55→	
 56→	
 57→	const eEcl = Ecliptic(new Vector(e.x, e.y, e.z, e.t)).vec;
 58→	const omega = Math.atan2(eEcl.y, eEcl.x);
 59→	
 60→	return new Map<Node, number>([
 61→		[Node.LUNAR_PERIGEE, normalizeAngleRad(omega)],
 62→		[Node.LUNAR_APOGEE, normalizeAngleRad(omega + Math.PI)]
 63→	]);
 64→}
 65→
 66→function computeLunarApogeePerigee(date: Date, lunarNodeMode: LunarNodeMode): Map<Node, number>{
 67→	if (lunarNodeMode == LunarNodeMode.MEAN) {
 68→		return computeLunarApogeePerigeeMeeus(date);
 69→	} else {
 70→		return computeLunarApogeePerigeeExact(date);
 71→	}
 72→}
