 74→function computeLunarNodesMeeus(date: Date): Map<Node, number> {
 75→	const jd = (date.getTime() / 86400000) + 2440587.5; // Unix ms -> JD
 76→	const t = (jd - 2451545.0) / 36525.0;
 77→
 78→	// Meeus Ch. 47: mean longitude of ascending node of lunar orbit
 79→	const omega = 125.04452 - 1934.136261 * t + 0.0020708 * t*t + (t*t*t)/450000; // small correction
 80→
 81→	const ascending = (omega)/360*2*Math.PI;
 82→	
 83→	return new Map <Node, number>([
 84→		[Node.LUNAR_ASCENDING, normalizeAngleRad(ascending)],
 85→		[Node.LUNAR_DESCENDING, normalizeAngleRad(ascending + Math.PI)]
 86→	]);
 87→}
 88→
 89→function computeLunarNodesExact(date: Date): Map<Node, number>{
 90→	
 91→	const s = GeoMoonState(date);
 92→	
 93→	const r = { x: s.x, y: s.y, z: s.z };
 94→	const v = { x: s.vx, y: s.vy, z: s.vz };
 95→	const h = {
 96→		x: r.y * v.z - r.z * v.y,
 97→		y: r.z * v.x - r.x * v.z,
 98→		z: r.x * v.y - r.y * v.x,
 99→		t: new AstroTime(date)
100→	};
101→	
102→	const hEcl = Ecliptic(new Vector(h.x, h.y, h.z, h.t)).vec; // { x, y, z } in ecliptic frame
103→	const omega = Math.atan2(hEcl.x, -hEcl.y);
104→	return new Map <Node, number>([
105→		[Node.LUNAR_ASCENDING, normalizeAngleRad(omega)],
106→		[Node.LUNAR_DESCENDING, normalizeAngleRad(omega + Math.PI)]
107→	]);
108→	
109→}
110→
111→function computeLunarNodes(date: Date, lunarNodeMode: LunarNodeMode): Map<Node, number>{
112→	if (lunarNodeMode == LunarNodeMode.MEAN) {
113→		return computeLunarNodesMeeus(date);
114→	} else {
115→		return computeLunarNodesExact(date);
116→	}
117→}
