119→function getTodayEclipticLongitudeFromEQJ(date: Date, v: vec3): number {
120→	const astroTime = new AstroTime(date);
121→	const vECT = RotateVector(Rotation_EQJ_ECT(astroTime), toAstronomyVector(v));
122→	return Math.atan2(vECT.y, vECT.x);
123→}
