125→function computeAxisAngles(date: Date, surfacePos: SurfacePosition): Map<Node, number> {
126→	const { asc, mc, vx } = computeAllSignificantPoints(date, surfacePos);
127→	
128→	const ascLon = getTodayEclipticLongitudeFromEQJ(date, asc);
129→	const mcLon = getTodayEclipticLongitudeFromEQJ(date, mc);
130→	const vxLon = getTodayEclipticLongitudeFromEQJ(date, vx);
131→
132→	return new Map<Node, number>([
133→		[Node.ASCENDANT, normalizeAngleRad(ascLon)],
134→		[Node.DESCENDANT, normalizeAngleRad(ascLon + Math.PI)],
135→		[Node.MIDHEAVEN, normalizeAngleRad(mcLon)],
136→		[Node.IMUM_COELI, normalizeAngleRad(mcLon + Math.PI)],
137→		[Node.VERTEX, normalizeAngleRad(vxLon)],
138→		[Node.ANTIVERTEX, normalizeAngleRad(vxLon + Math.PI)],
139→	]);
140→}
