142→function computeEquinoxes(): Map<Node, number> {
143→	return new Map<Node, number>([
144→		[Node.VERNAL_EQUINOX, 0],
145→		[Node.AUTUMNAL_EQUINOX, Math.PI]
146→	]);
147→}
