149→function computePhysicalNodePositions(date: Date): Map<Node, number> {
150→	const nodeAngles = new Map<Node, number>();
151→	for ( const [node, body] of Object.entries(nodeToBody)) {
152→		const lon = bodyToGeocentricLongitude(body, date);
153→		nodeAngles.set(node as Node, lon);
154→	}
155→	return nodeAngles;
156→}
