159→function computeSmallObjectPositions(date: Date): Map<Node, number> {
160→	const nodeAngles = new Map<Node, number>();
161→
162→	for (const [node, params] of Object.entries(smallBodyParams)) {
163→		const lon = orbitalParamsToGeocentricLongitude(params, date);
164→		nodeAngles.set(node as Node, lon);
165→	}
166→
167→	return nodeAngles;
168→}
