170→function computeHamburgSchoolObjectPositions(date: Date, hamburgSchoolMode: HamburgSchoolMode): Map<Node, number> {
171→	const nodeAngles = new Map<Node, number>();
172→
173→	const hamburgSchoolParams = hamburgSchoolMode == HamburgSchoolMode.NEELY ? hamburgSchoolParamsNeely : hamburgSchoolParamsWitte;
174→	for (const [node, params] of Object.entries(hamburgSchoolParams)) {
175→		const lon = orbitalParamsToGeocentricLongitude(params, date);
176→		nodeAngles.set(node as Node, lon);
177→	}
178→
179→	return nodeAngles;
180→}
