182→function computeArabicPartPositions(nodePositions: Map<Node, number>): Map<Node, number> {
183→	const asc = nodePositions.get(Node.ASCENDANT)!;
184→	const sun = nodePositions.get(Node.SUN)!;
185→	const d = normalizeAngleRad(sun-asc);
186→	const dayBirth = d > Math.PI;
187→	const f = dayBirth ? 1 : -1;
188→	//source: https://horoscopes.astro-seek.com/astrology-arabic-lots-list
189→	// there's a bajillion of these. I see two ideas:
190→	// - just the part of fortune. that's basic.
191→	// - all of them, with some complicated filters to include them by source/category/etc.
192→	// I don't think there's a midpoint between the two. 
193→	// let's just leave the PoF for now and look into the other stuff later down the line.
194→	
195→	// oh, and this will depend on house cusps eventually, so we'll need to move things around a bit.
196→	// this will probably go in its own file, anyway.
197→	return new Map <Node, number>([
198→		[Node.PART_OF_FORTUNE, asc + f*(nodePositions.get(Node.MOON)! - nodePositions.get(Node.SUN)!)],
199→		//[Node.PART_OF_SPIRIT, asc + f*(nodePositions.get(Node.SUN) - nodePositions.get(Node.MOON))],
200→		//[Node.PART_OF_LOVE, asc + f*(nodePositions.get(Node.VENUS) - nodePositions.get(Node.SUN))],
201→		//[Node.PART_OF_MARRIAGE, asc + f*(nodePositions.get(Node.DESCENDANT) - nodePositions.get(Node.VENUS))],
202→		//[Node.PART_OF_NECESSITY, asc + f*(nodePositions.get(Node.SATURN) - nodePositions.get(Node.MOON))],
203→		
204→		//Dubious. Source notes same formula for parts of: commerce, communication, slaves 4b, vitality
205→		//[Node.PART_OF_CAREER, asc + f*(nodePositions.get(Node.MERCURY) - nodePositions.get(Node.SUN))],
206→		
207→		// first source said courage = mars - sun. not in main source, equals:
208→		// commerce (jacobson), conquest, deceit, destruction(jones), dignity B, enemies (olympiodorus B), fire, lost animal, passion, sowing, travel (firmicus), wheat
209→		// okay.
210→		// [Node.PART_OF_COURAGE, asc + f*(nodePositions.get(Node.MARS) - nodePositions.get(Node.SUN))],
211→		
212→		//[Node.PART_OF_LONGEVITY, asc + f*(nodePositions.get(Node.MOON) - nodePositions.get(Node.JUPITER))],
213→		//[Node.PART_OF_DEATH, asc + f*(houseCusps[7] - nodePositions.get(Node.MOON))], //8th cusp
214→	]);
215→}
