217→function computeAllNodePositionsWithoutSurfacePosition(
218→	date: Date,
219→	lunarNodeMode: LunarNodeMode,
220→	hamburgSchoolMode: HamburgSchoolMode
221→): Map<Node, number>{
222→	return new Map<Node, number>([
223→		...computePhysicalNodePositions(date),
224→		...computeSmallObjectPositions(date),
225→		...computeHamburgSchoolObjectPositions(date, hamburgSchoolMode),
226→		...computeLunarNodes(date, lunarNodeMode),
227→		...computeLunarApogeePerigee(date, lunarNodeMode),
228→		...computeEquinoxes(),
229→	]);
230→}
