232→function computeAllNodePositions(
233→	date: Date,
234→	surfacePosition: SurfacePosition,
235→	lunarNodeMode: LunarNodeMode,
236→	hamburgSchoolMode: HamburgSchoolMode
237→): Map<Node, number>{
238→	let nodePositions = new Map<Node, number>([
239→		...computeAllNodePositionsWithoutSurfacePosition(date, lunarNodeMode, hamburgSchoolMode),
240→		...computeAxisAngles(date, surfacePosition),
241→	]);
242→	nodePositions = new Map<Node, number>([
243→		...nodePositions,
244→		...computeArabicPartPositions(nodePositions),
245→	]);
246→	return nodePositions;
247→}
