249→function computeSiderealOffset(date: Date, astrologyMode: AstrologyMode): number {
250→	if (astrologyMode === AstrologyMode.TROPICAL) { return 0; }
251→	
252→	const ayanamsaJ2000 = ayanamsas[astrologyMode];
253→	if (ayanamsaJ2000 === undefined) {
254→		throw new Error("Irregular astrology mode passed to computeSiderealOffset");
255→	}
256→	
257→	return addPrecession(date, ayanamsaJ2000*Math.PI/180);
258→}
259→
260→function computeZodiacSymbolPositionsFromSiderealOffset(siderealOffset: number): number[] {
261→	return new Map(standardZodiac.map((zodiac, index) => 
262→		[zodiac, siderealOffset + index * Math.PI / 6]
263→	));
264→}
265→
266→function computeZodiacSymbolPositionsForIrregularMode(date: Date, astrologyMode: AstrologyMode): number[] {
267→	let zodiacLongitudes = null;
268→	
269→	if (astrologyMode === AstrologyMode.CONSTELLATIONS_CLOSEST) {
270→		zodiacLongitudes = zodiacLongitudeClosest;
271→	} else if (astrologyMode === AstrologyMode.CONSTELLATIONS_IAU) {
272→		zodiacLongitudes = zodiacLongitudeIAU;
273→	} else {
274→		throw new Error("Regular astrology mode passed to computeZodiacSymbolPositionsForIrregularMode");
275→	}
276→	
277→	return new Map(
278→		Object.entries(zodiacLongitudes).map(([zodiac, lon]) => 
279→			[zodiac, addPrecession(date, lon)]
280→		)
281→	);
282→}
283→
284→function computeFixedStarPositions(date: Date): Map<string, number> {
285→	const positions = new Map<string, number>();
286→	for (const [starName, j2000longitude] of Object.entries(fixedStars)){
287→		positions.set(starName, addPrecession(date, j2000longitude));
288→	}
289→	return positions;
290→}
