292→interface ZodiacPositionsConstructorArgs {
293→	date: Date;
294→	surfacePosition: SurfacePosition | null;
295→	lunarNodeMode: LunarNodeMode;
296→	houseSystem: HouseSystem;
297→	astrologyMode: AstrologyMode;
298→	hamburgSchoolMode: HamburgSchoolMode;
299→	housePresweep: boolean;
300→	nodePositions?: Map<Node, number>;
301→	houseCuspPositions?: number[] | null;
302→	siderealOffset?: number | null;
303→	zodiacSymbolPositions?: Map<Zodiac, number>;
304→	fixedStarPositions?: Map<string, number>;
