307→class ZodiacPositions {
308→	private readonly _nodePositions: Map<Node, number>;
309→	private readonly _houseCuspPositions: number[] | null;
310→	private readonly _zodiacSymbolPositions: Map<Zodiac, number>;
311→	private readonly _fixedStarPositions: Map<string, number>;
312→	
313→	public readonly date: Date;
314→	public readonly surfacePosition: SurfacePosition | null;
315→	public readonly lunarNodeMode: LunarNodeMode;
316→	public readonly houseSystem: HouseSystem;
317→	public readonly siderealOffset: number;
318→	public readonly astrologyMode: AstrologyMode;
319→	public readonly hamburgSchoolMode: HamburgSchoolMode;
320→	public readonly housePresweep: boolean;
321→	
322→	constructor( config: ZodiacPositionsConstructorArgs ){
323→		this.surfacePosition = config.surfacePosition;
324→		this.date = config.date;
325→		this.lunarNodeMode = config.lunarNodeMode;
326→		this.houseSystem = config.houseSystem;
327→		this.astrologyMode = config.astrologyMode;
328→		this.hamburgSchoolMode = config.hamburgSchoolMode;
329→		this.housePresweep = config.housePresweep;
330→		
331→		if (config.fixedStarPositions === undefined ){
332→			this._fixedStarPositions = computeFixedStarPositions(this.date);
333→		} else {
334→			this._fixedStarPositions = config.fixedStarPositions;
335→		}
336→		
337→		// best be explicit ab whether siderealOffset is undefined/null
338→		if (config.siderealOffset === undefined) {
339→			if (irregularAstrologyModes.includes(this.astrologyMode)){
340→				this.siderealOffset = null;
341→			} else {
342→				this.siderealOffset = computeSiderealOffset(this.date, this.astrologyMode);
343→			}
344→		} else {
345→			this.siderealOffset = config.siderealOffset;
346→		}
347→		if (config.zodiacSymbolPositions === undefined) {
348→			if (this.siderealOffset === null) {
349→				this._zodiacSymbolPositions = computeZodiacSymbolPositionsForIrregularMode(this.date, this.astrologyMode);
350→			} else {
351→				this._zodiacSymbolPositions = computeZodiacSymbolPositionsFromSiderealOffset(this.siderealOffset);
352→			}
353→		} else {
354→			this._zodiacSymbolPositions = config.zodiacSymbolPositions;
355→		}
356→		
357→		if (config.nodePositions) {
358→			this._nodePositions = config.nodePositions;
359→			this._houseCuspPositions = config.houseCuspPositions || null;
360→		} else if (this.surfacePosition !== null) {
361→			this._nodePositions = computeAllNodePositions(this.date, this.surfacePosition, this.lunarNodeMode, this.hamburgSchoolMode);
362→			this._houseCuspPositions = computeHouseCuspPositions(this.date, this.surfacePosition, this.houseSystem, this._nodePositions, this._zodiacSymbolPositions);
363→		} else {
364→			this._nodePositions = computeAllNodePositionsWithoutSurfacePosition(this.date, this.lunarNodeMode, this.hamburgSchoolMode);
365→			this._houseCuspPositions = null;
366→		}
367→	}
368→	
369→	static create(
370→		date: Date,
371→		surfacePosition: SurfacePosition | null,
372→		lunarNodeMode: LunarNodeMode,
373→		houseSystem: HouseSystem,
374→		astrologyMode: AstrologyMode,
375→		hamburgSchoolMode: HamburgSchoolMode,
376→		housePresweep: boolean,
377→	): ZodiacPositions {
378→		return new ZodiacPositions({
379→			date,
380→			surfacePosition,
381→			lunarNodeMode,
382→			houseSystem,
383→			astrologyMode,
384→			hamburgSchoolMode,
385→			housePresweep
386→		});
387→	}
388→	
389→	private copyWith( updates: Partial<ZodiacPositionsConstructorArgs> ): ZodiacPositions {
390→		return new ZodiacPositions({
391→			date: this.date,
392→			surfacePosition: this.surfacePosition,
393→			lunarNodeMode: this.lunarNodeMode,
394→			houseSystem: this.houseSystem,
395→			astrologyMode: this.astrologyMode,
396→			hamburgSchoolMode: this.hamburgSchoolMode,
397→			housePresweep: this.housePresweep,
398→			nodePositions: this._nodePositions,
399→			houseCuspPositions: this._houseCuspPositions,
400→			siderealOffset: this.siderealOffset,
401→			zodiacSymbolPositions: this._zodiacSymbolPositions,
402→			fixedStarPositions: this._fixedStarPositions,
403→			...updates
404→		});
405→	}
406→
407→	public changeLunarNodeMode(newMode: LunarNodeMode): ZodiacPositions {
408→		if (newMode == this.lunarNodeMode) {
409→			return this;
410→		}
411→		const newLunarNodePositions = computeLunarNodes(this.date, newMode);
412→		const newLilithSelenePositions = computeLunarApogeePerigee(this.date, newMode);
413→		const newNodePositions = new Map<Node, number>([ ...this._nodePositions, ...newLunarNodePositions, ...newLilithSelenePositions]);
414→		return this.copyWith({lunarNodeMode: newMode, nodePositions: newNodePositions});
415→	}
416→	
417→	public changeHouseSystem(newSystem: HouseSystem): ZodiacPositions {
418→		if (newSystem == this.houseSystem) {
419→			return this;
420→		}
421→		const newHouseCuspPositions = this.surfacePosition ? 
422→			computeHouseCuspPositions(this.date, this.surfacePosition, newSystem, this._nodePositions, this._zodiacSymbolPositions)
423→			: null;
424→		return this.copyWith({houseSystem: newSystem, houseCuspPositions: newHouseCuspPositions});
425→	}
426→	
427→	public changeHousePresweep(newHousePresweep: boolean): ZodiacPositions {
428→		return this.copyWith({housePresweep: newHousePresweep});
429→	}
430→	
431→	public changeAstrologyMode(newAstrologyMode: AstrologyMode): ZodiacPositions {
432→		if (newAstrologyMode == this.astrologyMode) {
433→			return this;
434→		}
435→		
436→		let newSiderealOffset: number;
437→		let newZodiacSymbolPositions: Map<Zodiac, number>;
438→		if (irregularAstrologyModes.includes(newAstrologyMode)){
439→			newSiderealOffset = null;
440→			newZodiacSymbolPositions = computeZodiacSymbolPositionsForIrregularMode(this.date, newAstrologyMode);
441→		} else {
442→			newSiderealOffset = computeSiderealOffset(this.date, newAstrologyMode);
443→			newZodiacSymbolPositions = computeZodiacSymbolPositionsFromSiderealOffset(newSiderealOffset);
444→		}
445→		
446→		if (AyanamsaDependantHouseSystems.includes(this.houseSystem) && this.surfacePosition !== null) {
447→			const newHouseCuspPositions = computeHouseCuspPositions(
448→				this.date,
449→				this.surfacePosition,
450→				this.houseSystem,
451→				this._nodePositions,
452→				newZodiacSymbolPositions
453→			);
454→			return this.copyWith({
455→				astrologyMode: newAstrologyMode,
456→				siderealOffset: newSiderealOffset,
457→				zodiacSymbolPositions: newZodiacSymbolPositions,
458→				houseCuspPositions: newHouseCuspPositions
459→			});
460→		} else {
461→			return this.copyWith({
462→				astrologyMode: newAstrologyMode,
463→				siderealOffset: newSiderealOffset,
464→				zodiacSymbolPositions: newZodiacSymbolPositions
465→			});
466→		}
467→	}
468→	
469→	public getZodiacSymbolPositions(): Map<Zodiac, number> {
470→		return this._zodiacSymbolPositions;
471→	}
472→	
473→	public isZodiacModeRegular(): boolean {
474→		return this.siderealOffset !== null;
475→	}
476→	
477→	public _getSymbolAtLongitude(lon: number): Zodiac {
478→		if (this.isZodiacModeRegular()){
479→			return standardZodiac[Math.floor((((lon-this.siderealOffset)*6/Math.PI)%12+12)%12)];
480→		} else {
481→			const entries = Array.from(this.getZodiacSymbolPositions().entries());
482→			const index = entries.findIndex(([_, zlon]) => zlon > lon);
483→			if (index === -1 || index === 0) { // first is already bigger or all are smaller: last sign (the one across the v.equinox)
484→				return entries[entries.length - 1][0];
485→			} else {
486→				return entries[index - 1][0];
487→			}
488→		}
489→	}
490→	
491→	public getSymbolOfNode(node: Node): Zodiac {
492→		// will error out if node is absent (intended)
493→		const lon = this.getNodePosition(node);
494→		return this._getSymbolAtLongitude(lon);
495→	}
496→	
497→	public getNodePositionWithinSign(node: Node): number {
498→		// this might error out if node is absent - intended behaviour
499→		const lon = this.getNodePosition(node);
