  6→export function getChartSect(zodiacPositions): Sect {
  7→	return zodiacPositions.isNodeAboveHorizon(Node.SUN) ? Sect.DIURNAL : Sect.NOCTURNAL;
  8→}
  9→
 10→export function isInSect(node: Node, zodiacPositions: ZodiacPositions): boolean | null{
 11→	const nodeSect = planetSects[node];
 12→	if (nodeSect === undefined) {
 13→		return null;
 14→	}
 15→	const chartSect = getChartSect(zodiacPositions);
 16→	if (nodeSect == Sect.VARIABLE){
 17→		const variableNodeSect = isTrailing(node, Node.SUN, zodiacPositions) ? Sect.NOCTURNAL : Sect.DIURNAL;
 18→		return chartSect == variableNodeSect;
 19→	} else {
 20→		return chartSect == nodeSect;
 21→	}
 22→}
 23→
 24→export function getChartRuler(zodiacPositions: ZodiacPositions, dignityMode: DignityMode): Node | null {
 25→	if (!zodiacPositions.hasSurfacePosition()) {
 26→		return null;
 27→	}
 28→	const ascendantSign = zodiacPositions.getSymbolOfNode(Node.ASCENDANT);
 29→	const rulerships = dignityMode === DignityMode.CLASSICAL ? classicalRulerships : modernRulerships;
 30→	return rulerships[ascendantSign];
