interface AxisAngles {
	asc: number;
	dsc: number;
	mc: number;
	ic: number
}

export const HouseSystem = {
	WHOLE_SIGN: "Whole Sign",
	EQUAL_HOUSES: "Equal Houses",
	PORPHYRY: "Porphyry",
	EQUAL_HOUSES_VEHLOW: "Equal Houses - Vehlow",
