117→function advanceAlongCircle(p: vec3, circle: vec3, angle: number): vec3 {
118→	const q = normalize(cross(circle, p));
119→	return normalize({
120→		x: p.x*Math.cos(angle) + q.x*Math.sin(angle),
121→		y: p.y*Math.cos(angle) + q.y*Math.sin(angle),
122→		z: p.z*Math.cos(angle) + q.z*Math.sin(angle)
123→	});
124→}
