130→function projectPoint(q: vec3, circle: vec3, center: vec3): vec3 {
131→	const qcCircle = normalize(cross(q, center));
132→	const intersection = normalize(cross(qcCircle, circle));
133→	return intersection;
134→}
135→
136→function projectPoints(qs: vec3[], circle: vec3, center: vec3): vec3[] {
137→	return qs.map(q => projectPoint(q, circle, center));
138→}
