140→function computeEclipticAngle(p: vec3): number {
141→	const rot = Rotation_EQJ_ECL();
142→	const v = RotateVector(rot, toAstronomyVector(p));
143→	const alpha = Math.atan2(v.y, v.x);
144→	return normalizeAngleRad(alpha);
145→}
