151→function cycleToStart(angles: number[], start: number): number[] {
152→	const sorted = [...angles].sort((a, b) => a - b);
153→	const i = sorted.findIndex((angle, idx) => angle < start && start < sorted[idx + 1]);
154→	return i === -1 ? sorted : [...sorted.slice(i), ...sorted.slice(0, i)];
155→}
