165→	const kpts = twelvePoints(startingCircle, startingPoint);
166→	const epts = projectPoints(kpts, ecliptic, projectionCenter);
167→	const angles = computeEclipticAngles(epts);
168→	return cycleToStart(angles, computeEclipticAngle(asc));
