470→		return this._zodiacSymbolPositions;
471→	}
472→	
473→	public isZodiacModeRegular(): boolean {
474→		return this.siderealOffset !== null;
475→	}
476→	
477→	public _getSymbolAtLongitude(lon: number): Zodiac {
478→		if (this.isZodiacModeRegular()){
479→			return standardZodiac[Math.floor((((lon-this.siderealOffset)*6/Math.PI)%12+12)%12)];
480→		} else {
481→			const entries = Array.from(this.getZodiacSymbolPositions().entries());
482→			const index = entries.findIndex(([_, zlon]) => zlon > lon);
483→			if (index === -1 || index === 0) { // first is already bigger or all are smaller: last sign (the one across the v.equinox)
484→				return entries[entries.length - 1][0];
485→			} else {
486→				return entries[index - 1][0];
487→			}
488→		}
489→	}
490→	
491→	public getSymbolOfNode(node: Node): Zodiac {
492→		// will error out if node is absent (intended)
493→		const lon = this.getNodePosition(node);
494→		return this._getSymbolAtLongitude(lon);
495→	}
496→	
497→	public getNodePositionWithinSign(node: Node): number {
498→		// this might error out if node is absent - intended behaviour
499→		const lon = this.getNodePosition(node);
500→		if (this.isZodiacModeRegular()){
501→			// this should give the same results as the next branch but something something faster/more readable
502→			return normalizeAngleRad(lon - this.siderealOffset)%(Math.PI/6);
503→		} else {
504→			const sign = this._getSymbolAtLongitude(lon);
505→			return lon - this._zodiacSymbolPositions.get(sign);
506→		}
507→		
508→	} 
509→	
510→	public changeHamburgSchoolMode(newMode: HamburgSchoolMode): ZodiacPositions{
511→		if (newMode == this.hamburgSchoolMode) {
512→			return this;
513→		}
514→		const newHamburgSchoolObjectPositions = computeHamburgSchoolObjectPositions(this.date, newMode);
515→		const newNodePositions = new Map<Node, number>([ ...this._nodePositions, ...newHamburgSchoolObjectPositions]);
516→		return this.copyWith({hamburgSchoolMode: newMode, nodePositions: newNodePositions});
517→	}
518→	
519→	public hasSurfacePosition(): boolean{
520→		return this.surfacePosition !== null;
521→	}
522→	
523→	public getNodePositions(): Map<Node, number>{
524→		return this._nodePositions;
525→	}
526→	
527→	public getNodePosition(node: Node): number{
528→		const a = this._nodePositions.get(node);
529→		if (a === undefined) {throw new Error("getNodePosition called for absent node:", node);}
530→		return a;
531→	}
532→	
533→	public getHouseCuspPositions(): number[] | null{
534→		return this._houseCuspPositions;
535→	}
536→	
537→	public getHouseCuspPosition(i: number): number | null{
538→		return this._houseCuspPositions?.[i] || null;
539→	}
540→	
541→	public houseSystemUndefinedForPosition(): boolean {
542→		// returns true iff a position is specified but the chosen house system is undefined for that date/time
543→		return this.surfacePosition !== null && this._houseCuspPositions === null
544→	}
545→	
546→	public houseCuspsAreDefined(): boolean {
547→		return this._houseCuspPositions !== null
548→	}
549→	
550→	public isNodeAboveHorizon(node: Node): boolean {
551→		if (!this.hasSurfacePosition()) {
552→			throw new Error("isNodeAboveHorizon called with no defined surface position");
553→		}
554→		// error if node is absent - intended
555→		const lon = this.getNodePosition(node);
556→		const asc = this.getNodePosition(Node.ASCENDANT);
557→		const dsc = this.getNodePosition(Node.DESCENDANT);
558→		if (asc<dsc){
559→			return !((asc < lon)&&(lon < dsc));
560→		} else {
561→			return ((dsc < lon)&&(lon < asc));
562→		}
563→	}
564→	
565→	public isNodeEastern(node: Node): boolean {
566→		if (!this.hasSurfacePosition()) {
567→			throw new Error("isNodeEastern called with no defined surface position");
568→		}
569→		// error if node is absent - intended
570→		const lon = this.getNodePosition(node);
571→		const mc = this.getNodePosition(Node.MIDHEAVEN);
572→		const ic = this.getNodePosition(Node.IMUM_COELI);
573→		if (mc<ic){
574→			return ((mc < lon)&&(lon < ic));
575→		} else {
576→			return !((ic < lon)&&(lon < mc));
577→		}
578→	}
579→	
580→	public getHouseOfNode(node: Node): number {
581→		// errors out if node is absent
582→		const lon = this.getNodePosition(node);
583→		const houseLimits = this._houseCuspPositions.map(cusp => {
584→			if (this.housePresweep){
585→				const limit = cusp - 5*Math.PI/180;
586→				return limit > 0 ? limit : limit + 2*Math.PI;
587→			} else {
588→				return cusp;
589→			}
590→		});
591→		// might be faster to sort them (1 single slice) and do a zodiac-like approach but seems like premature optimization
592→		for (let i = 0; i < houseLimits.length-1; i++){
593→			const houseStart = houseLimits[i];
594→			const houseEnd = houseLimits[i+1];
595→			if ( anglesLieInShortArc(houseStart, lon, houseEnd) ) {
596→				return i+1;
597→			}
598→		}
599→		return houseLimits.length;
600→	}
601→	
602→	public getFixedStarPositions(): Map<string, number> {
603→		return this._fixedStarPositions;
604→	}
605→}
