  1→import { classicalRulerships, modernRulerships, Node, traditionalHouseAngularities, HouseAngularity, Sect, planetSects } from './astroDefs.ts';
  2→import { DignityMode, HouseAngularityMode } from './settingsDefs.ts';
  3→import { angleShortDistance } from './util.ts';
