 33→interface AngleProximityInfo {
 34→	closestAngle: Node;
 35→	distance: number;
 36→	passed: boolean;
 37→}
 38→
 39→export function getAngleProximity(node: Node, zodiacPositions: ZodiacPositions): AngleProximityInfo {
 40→	//will throw error for absent node / surface position
 41→	const lon = zodiacPositions.getNodePosition(node);
 42→	
 43→	const asc = zodiacPositions.getNodePosition(Node.ASCENDANT);
 44→	const ic = zodiacPositions.getNodePosition(Node.IMUM_COELI);
 45→	const dsc = zodiacPositions.getNodePosition(Node.DESCENDANT);
 46→	const mc = zodiacPositions.getNodePosition(Node.MIDHEAVEN);
 47→	
 48→	const dAsc = angleShortDistance(lon, asc);
 49→	const dIc = angleShortDistance(lon, ic);
 50→	const dDsc = angleShortDistance(lon, dsc);
 51→	const dMc = angleShortDistance(lon, mc);
 52→	
 53→	const minD = Math.min(dAsc, dIc, dDsc, dMc);
 54→	if (minD == dAsc) {
 55→		return { closestAngle: Node.ASCENDANT, distance: minD, passed: isTrailing(Node.ASCENDANT, node, zodiacPositions)}
 56→	} else if (minD == dIc) {
 57→		return { closestAngle: Node.IMUM_COELI, distance: minD, passed: isTrailing(Node.IMUM_COELI, node, zodiacPositions)}
 58→	} else if (minD == dDsc) {
 59→		return { closestAngle: Node.DESCENDANT, distance: minD, passed: isTrailing(Node.DESCENDANT, node, zodiacPositions)}
 60→	} else {
 61→		return { closestAngle: Node.MIDHEAVEN, distance: minD, passed: isTrailing(Node.MIDHEAVEN, node, zodiacPositions)}
 62→	}
 63→}
 64→
 65→function isTrailing(trailingNode: Node, leadingNode: Node, zodiacPositions: ZodiacPositions): boolean {
 66→	// returns true if trailingNode is trailing leadingNode (up to 180º)
 67→	// errors out if either node is absent
 68→	const trailingLon = zodiacPositions.getNodePosition(trailingNode);
 69→	const leadingLon = zodiacPositions.getNodePosition(leadingNode);
 70→	if ( trailingLon > Math.PI ) {
 71→		return (trailingLon > leadingLon) && (leadingLon > trailingLon - Math.PI);
 72→	} else {
 73→		return (trailingLon > leadingLon) || (leadingLon > trailingLon + Math.PI);
 74→	}
 75→}
 76→
 77→export function getHouseAngularities(zodiacPositions: ZodiacPositions, houseAngularityMode: HouseAngularityMode): (number | null)[] {
 78→	// we could put a guard here that defaulted to the traditional angularities if the houseSystem was well-behaved (angles always @ 1-4-7-10)
 79→	// but in retrospect I don't know that there are that many like this? most respect asc-dsc 1-7 but mc-ic is unclear. Porphyry always,
 80→	// some time-based house systems also but i'm not too sure + may be undefined. So let's avoid hardcoding any of that, I suppose.
 81→	
 82→	// this (line) will error out if one tries to call it with a zodiacPositions with an undefined surfacepos
 83→	const nHouses = zodiacPositions.getHouseCuspPositions().length;
 84→	
 85→	if (houseAngularityMode === HouseAngularityMode.TRADITIONAL) {
 86→		return traditionalHouseAngularities.slice(0, nHouses); 
 87→	} else if (houseAngularityMode === HouseAngularityMode.VERIFIED) {
 88→		if (
 89→			zodiacPositions.getHouseOfNode(Node.ASCENDANT) == 1
 90→			&& zodiacPositions.getHouseOfNode(Node.IMUM_COELI) == 4
 91→			&& zodiacPositions.getHouseOfNode(Node.DESCENDANT) == 7
 92→			&& zodiacPositions.getHouseOfNode(Node.MIDHEAVEN) == 10
 93→		) {
 94→			return traditionalHouseAngularities.slice(0, nHouses); 
 95→		} else {
 96→			return new Array(nHouses).fill(null);
 97→		}
 98→	}
 99→	// else, we're in the dynamic case
100→	const isHouseAngular = new Array(nHouses).fill(false);
101→	const isHouseSuccedent = new Array(nHouses).fill(false);
102→	const isHouseCadent = new Array(nHouses).fill(false);
103→	const housesOfAngles = [
104→		zodiacPositions.getHouseOfNode(Node.ASCENDANT),
105→		zodiacPositions.getHouseOfNode(Node.IMUM_COELI),
106→		zodiacPositions.getHouseOfNode(Node.DESCENDANT),
107→		zodiacPositions.getHouseOfNode(Node.MIDHEAVEN)
108→	];
109→	for (const houseOfAngle of housesOfAngles) {
110→		isHouseAngular[houseOfAngle-1] = true;
111→		isHouseSuccedent[houseOfAngle == nHouses ? 0 : houseOfAngle] = true;
112→		isHouseCadent[houseOfAngle == 1 ? nHouses - 1 : houseOfAngle - 2] = true;
113→	}
114→	return Array.from({length: nHouses}, (_, i) => {
115→		if (isHouseAngular[i]) {
116→			return HouseAngularity.ANGULAR;
117→		} else if (isHouseSuccedent[i] && isHouseCadent[i]) {
118→			return null;
119→		} else if (isHouseSuccedent[i]) {
120→			return HouseAngularity.SUCCEDENT;
121→		} else if (isHouseCadent[i]) {
122→			return HouseAngularity.CADENT;
123→		} else {
124→			return null;
125→		}
126→	})
127→}
