129→export function getFixedStarsWithinLongitude(node: Node, zodiacPositions: ZodiacPositions, maximumDistance: number): Map<string, number> {
130→	const lon = zodiacPositions.getNodePosition(node);
131→	return new Map(Array.from( zodiacPositions.getFixedStarPositions() )
132→		.map(([starName, longitude]) => [ starName, angleShortDistance(lon, longitude)])
133→		.filter(([starName, distance]) => distance < maximumDistance)
134→	);
135→}

