 13→function capitalize(sentence: string): string {
 14→	return String(sentence).charAt(0).toUpperCase() + String(sentence).slice(1);
 15→}
 16→
 17→function createEmphasisString(verticalDiff: number, horizontalDiff: number, nNodes: number) {
 18→	// vertical diff is above - below, horizontal diff is east - west
 19→	
 20→	const verticalOrientation = verticalDiff === 0 ? 0 : verticalDiff > 0 ? 1 : -1;
 21→	const horizontalOrientation = horizontalDiff === 0 ? 0 : horizontalDiff > 0 ? 1 : -1;
 22→	const verticalDiffAbs = verticalOrientation > 0 ? verticalDiff : -verticalDiff;
 23→	const horizontalDiffAbs = horizontalOrientation > 0 ? horizontalDiff : -horizontalDiff;
 24→	
 25→	// translating the old parameters from 10 to n. in terms of diffAbs/total
 26→	// starts at nth. slight from 0.2. normal from 0.4. strong from 0.6
 27→	
 28→	// considering we're working with 10 standard planets. nth if equal, slight if 2 (4 vs 6), av if 4 (3 vs 7), strong if 6/8/10 (0,1,2 vs 8,9,10)
 29→	const strengthsPerDiff: (number|null)[] = [0, null, 1, null, 2, null, 3, null, 3, null, 3];
 30→	const strengthsPerRelDiff = (diffRel: number) => {
 31→		if (diffRel >= 0.6) { return 3; }
 32→		else if (diffRel >= 0.4) { return 2; }
 33→		else if (diffRel >= 0.2) { return 1; }
 34→		else { return 0; }
 35→	};
 36→	const verticalStrength = strengthsPerRelDiff(verticalDiffAbs/nNodes);
 37→	const horizontalStrength = strengthsPerRelDiff(horizontalDiffAbs/nNodes);
 38→	
 39→	const strengthModifiers: (string|null)[] = [null, "slight ", "", "strong "];
 40→	const strengthModifiersAdj: (string|null)[] = [null, "slighty ", "", "strongly "];
 41→	const verticalModifier = strengthModifiers[verticalStrength];
 42→	const horizontalModifier = strengthModifiers[horizontalStrength];
 43→	const horizontalModifierAdj = strengthModifiersAdj[horizontalStrength];
 44→	
 45→	//painful logic to try to make things stay within 1 lines
 46→	const horizontalStringUsesModifier = horizontalStrength === 1 || horizontalStrength === 3;
 47→	const verticalStringUsesModifier = verticalStrength === 1 || verticalStrength === 3;
 48→	const verticalStringLongish = verticalStrength !== 2;
 49→	const specialCaseTheElision = horizontalStrength === 0 && verticalStringUsesModifier;
 50→	
 51→	if (verticalStrength === horizontalStrength) {
 52→		if (verticalStrength === 0) { // null - null case
 53→			return "No east/west or above/below horizon emphasis.";
 54→		} else {
 55→			return capitalize(`${verticalModifier}emphasis ${horizontalOrientation === 1 ? 'west' : 'east'} & ${verticalOrientation === 1 ? 'above' : 'below'} the horizon.`);
 56→		}
 57→	} else {
 58→		const verticalString = verticalStrength === 0 ? (
 59→			horizontalStringUsesModifier ? (
 60→				'No emphasis above/below horizon'
 61→			) : (
 62→				'No emphasis above/below the horizon'
 63→			)
 64→		) : (
 65→			specialCaseTheElision ? (
 66→				`${verticalModifier}emphasis ${verticalOrientation === 1 ? 'above' : 'below'} horizon`
 67→			) : (
 68→				`${verticalModifier}emphasis ${verticalOrientation === 1 ? 'above' : 'below'} the horizon`
 69→			)
 70→		); 
 71→		const horizontalString = horizontalStrength === 0 ? (
 72→			'No east/west emphasis'
 73→		) : (
 74→			verticalStringLongish ? (
 75→				`${horizontalModifierAdj}${horizontalOrientation === 1? 'western' : 'eastern'}`
 76→			) : (
 77→				`${horizontalModifier}${horizontalOrientation === 1? 'western' : 'eastern'} emphasis`
 78→			)
 79→		);
 80→		if (verticalStrength>horizontalStrength) { // vertical goes first
 81→			return capitalize(`${verticalString}${horizontalStrength === 0 ? '.' : ','} ${horizontalString}.`);
 82→		} else { // horizontal goes first
 83→			return capitalize(`${horizontalString}${verticalStrength === 0 ? '.' : ','} ${verticalString}.`);
 84→		}
 85→	}
 86→}
