 88→function generateNodesPerRow(nNodes: number): number[]{
 89→	if (nNodes <= 12){
 90→		return [[], [1], [2], [3], [2, 2], [3, 2], [3, 3], [2, 3, 2], [3, 2, 3], [3, 3, 3], [3, 4, 3], [4, 3, 4], [4, 4, 4]][nNodes];
 91→	}
 92→	const numRows = Math.floor(nNodes/4)
 93→	const nodesPerRow = Array.from({length: numRows}, (_, i) => 4);
 94→	nodesPerRow.push(nNodes - 4*numRows);
 95→	return nodesPerRow;
 96→}
