 12→function aspectPathData(aspect: Aspect, nodeAngles: Map<Node, number>, aspectRadius: number){
 13→	const as: number[] = aspect.nodes
 14→	.map( (node) => nodeAngles.get(node)!)
 15→	.map( (a: number) => (normalizeAngleRad(a)))
 16→	.sort();
 17→	const xs: number[] = as.map( (a) => 50 + aspectRadius * Math.cos(a));
 18→	const ys: number[] = as.map( (a) => 50 - aspectRadius * Math.sin(a));
 19→	
 20→	if (aspect.nodes.length == 2) {
 21→		return [
 22→			`M ${xs[0]} ${ys[0]}`,
 23→			`L ${xs[1]} ${ys[1]}`
 24→		].join(" ");
 25→	} else if (aspect.nodes.length == 3) {
 26→		return [
 27→			`M ${xs[0]} ${ys[0]}`,
 28→			`L ${xs[1]} ${ys[1]}`,
 29→			`L ${xs[2]} ${ys[2]}`,
 30→			`Z`
 31→		].join(" ");
 32→	} else if (aspect.nodes.length == 4) {
 33→		return [
 34→			`M ${xs[0]} ${ys[0]}`,
 35→			`L ${xs[1]} ${ys[1]}`,
 36→			`L ${xs[2]} ${ys[2]}`,
 37→			`L ${xs[3]} ${ys[3]}`,
 38→			`Z`
 39→		].join(" ");
 40→	} else if (aspect.nodes.length == 6) {
 41→		return [
 42→			`M ${xs[0]} ${ys[0]}`,
 43→			`L ${xs[3]} ${ys[3]}`,
 44→			`M ${xs[1]} ${ys[1]}`,
 45→			`L ${xs[4]} ${ys[4]}`,
 46→			`M ${xs[2]} ${ys[2]}`,
 47→			`L ${xs[5]} ${ys[5]}`,
 48→		].join(" ");
 49→	} else {
 50→		throw new Error(`Unexpected number of nodes: ${aspect.nodes.length}`);
 51→	}
 52→}
