 54→function ZodiacWheel({ zodiacPositions, aspects, highlightedAspect, highlightedNode, setHighlightedNode }: {
 55→	zodiacPositions: ZodiacPositions,
 56→	aspects: Aspect[],
 57→	highlightedAspect: Aspect | null,
 58→	highlightedNode: Node | null,
 59→	setHighlightedNode: (node: Node) => void
 60→}) {
 61→	const showNodeLabels = useSettingsStore(s => s.showNodeLabels);
 62→	const showSymbolLabels = useSettingsStore(s => s.showSymbolLabels);
 63→	const flipText = useSettingsStore(s => s.flipText);
 64→	const housePresweep = useSettingsStore(s => s.housePresweep);
 65→	const rotateSymbols = useSettingsStore(s => s.rotateSymbols);
 66→	const aspectsColorcoded = useSettingsStore(s => s.aspectsColorcoded);
 67→	const selectedNodes = useSettingsStore(s => s.selectedNodes);
 68→	const theme = useSettingsStore(s => s.theme);
 69→	const isDarkTheme = theme === Theme.DARK;
 70→	
 71→	const sectorRadius = 48;
 72→	const symbolRadius = 43.5;
 73→	const radius = 39; // percent of viewport
 74→	const aspectRadius = showNodeLabels ? 23 : 28;
 75→	const planetRadius = showNodeLabels ? 35 : (radius+aspectRadius)/2;
 76→	
 77→	const minimumIconSpace = 0.12; // radial
 78→	
 79→	const symbolSize = 4;
 80→	const strokeWidthPrimary = 0.15;
 81→	const strokeWidthSecondary = 0.1;
 82→	const strokeWidthTertiary = 0.05;
 83→	const blurBaseWidth = 2;
 84→	
 85→	const { offset, nodeAngles, houseCuspAngles, siderealOffset } = useMemo(() => {
 86→		
 87→		const offset = zodiacPositions.hasSurfacePosition() ?
 88→			Math.PI - zodiacPositions.getNodePosition(Node.ASCENDANT)
 89→			: -Math.PI/12;
 90→		
 91→		// this is vestigial, but it will be useful in the future to implement anglo style
 92→		const nodeAngles = new Map<Node, number>();
 93→		zodiacPositions.getNodePositions().forEach((position, node) => {
 94→			if (selectedNodes.has(node)) {
 95→				nodeAngles.set(node, position + offset);
 96→			}
 97→		})
 98→		
 99→		return {
100→			offset: offset,
101→			nodeAngles: nodeAngles,
102→			houseCuspAngles: zodiacPositions.getHouseCuspPositions(),
103→			siderealOffset: zodiacPositions.siderealOffset,
104→		}
105→	}, [zodiacPositions, selectedNodes]);
106→	
107→	const adjustedNodeAngles = useMemo(() => {
108→		if ( nodeAngles === null ) return null;
109→		
110→		const adjustedPositions = spreadIcons(
111→			Array.from(nodeAngles.values()), minimumIconSpace
112→		);
113→		
