  1→import { FC, useMemo, useRef, useState, useLayoutEffect } from 'react';
  2→import { Node, Sect } from './astroDefs';
  3→import { getChartSect, getChartRuler } from './astrologyUtil';
  4→import { formatAngle } from './util';
  5→import { renderString, renderNode, renderSign } from './renderPrimitives';
  6→import { useSettingsStore } from './settingsStore';
  7→import ZodiacPositions from './zodiacPositions';
  8→
  9→type ChartSummaryProps = {
 10→	zodiacPositions: ZodiacPositions;
 11→	setHighlightedNode: (node: Node) => void;
 12→};
 13→
 14→const ChartSummary: FC<ChartSummaryProps> = ({
 15→	zodiacPositions,
 16→	setHighlightedNode,
 17→}) => {
 18→
 19→	const showNodeLabels = useSettingsStore(s => s.showNodeLabels);
 20→	const showSymbolLabels = useSettingsStore(s => s.showSymbolLabels);
 21→
 22→	const dignityMode = useSettingsStore(s => s.dignityMode);
 23→	const hasSurfacePosition = zodiacPositions.hasSurfacePosition();
 24→
 25→	const chartSect = useMemo(() => {
 26→		if (!hasSurfacePosition) return null;
 27→		return getChartSect(zodiacPositions);
 28→	}, [zodiacPositions, hasSurfacePosition]);
 29→
 30→	const chartRuler = useMemo(() => {
 31→		return getChartRuler(zodiacPositions, dignityMode);
 32→	}, [zodiacPositions, dignityMode]);
 33→
 34→	// Refs for measuring node row widths
 35→	const nodeRefs = useRef<Map<Node, HTMLDivElement | null>>(new Map());
 36→	const [sortedNodes, setSortedNodes] = useState<Node[]>([Node.SUN, Node.MOON, Node.ASCENDANT]);
 37→	const [measured, setMeasured] = useState(false);
 38→
 39→	// Measure actual widths and sort after render
 40→	useLayoutEffect(() => {
 41→		const widths = new Map<Node, number>();
 42→		const nodes = [Node.SUN, Node.MOON, Node.ASCENDANT];
 43→
 44→		for (const node of nodes) {
 45→			const el = nodeRefs.current.get(node);
 46→			if (el) {
 47→				widths.set(node, el.getBoundingClientRect().width);
 48→			}
 49→		}
 50→
 51→		// Sort by width descending (widest first)
 52→		const sorted = [...nodes].sort((a, b) => {
 53→			const widthA = widths.get(a) ?? 0;
 54→			const widthB = widths.get(b) ?? 0;
 55→			return widthB - widthA;
 56→		});
 57→
 58→		setSortedNodes(sorted);
 59→		setMeasured(true);
 60→	}, [zodiacPositions, showNodeLabels, showSymbolLabels]);
 61→
 62→	const renderClickableNode = (node: Node, showPosition: boolean = true, forceText: boolean = false) => {
 63→		const sign = zodiacPositions.getSymbolOfNode(node);
 64→		const positionInSign = zodiacPositions.getNodePositionWithinSign(node);
 65→		const formattedPosition = formatAngle(positionInSign);
 66→
 67→		return (
 68→			<span
 69→				className="cursor-pointer hover:opacity-70 whitespace-nowrap"
 70→				onClick={(e) => { e.stopPropagation(); setHighlightedNode(node); }}
 71→			>
 72→				{renderNode(node, {showLabel: forceText ? true : undefined, withArticle: forceText})}
 73→				{showPosition && (
 74→					<>
 75→						{renderString(" | ")}
 76→						{renderSign(sign)}
 77→						{renderString(" · ")}
 78→						{renderString(formattedPosition)}
 79→					</>
 80→				)}
 81→			</span>
 82→		);
 83→	};
 84→
 85→	// If no surface position, we can't show much
 86→	if (!hasSurfacePosition) {
 87→		return null;
 88→	}
 89→
 90→	const isDiurnal = chartSect === Sect.DIURNAL;
 91→
 92→	return (
 93→		<div
 94→			className="absolute top-4 left-4 text-theme-text text-sm z-[100] whitespace-nowrap"
 95→			style={{ visibility: measured ? 'visible' : 'hidden' }}
 96→		>
 97→			<div>
 98→				{renderString((isDiurnal ? "Diurnal" : "Nocturnal") + " Chart")}
 99→				{chartRuler && (
100→					<>
101→						{renderString(" · Ruled by ")}
102→						{renderClickableNode(chartRuler, false, true)}
103→					</>
104→				)}
105→			</div>
106→			{sortedNodes.map((node) => (
107→				<div
108→					key={node}
109→					ref={(el) => nodeRefs.current.set(node, el)}
110→					style={{ width: 'fit-content' }}
111→				>
112→					{renderClickableNode(node)}
113→				</div>
114→			))}
115→		</div>
116→	);
117→};
