 65→export const TriplicityRole = {
 66→	DIURNAL: "Diurnal",
 67→	NOCTURNAL: "Nocturnal",
 68→	PARTICIPATING: "Participating",
 69→} as const;
 70→export type TriplicityRole = typeof TriplicityRole[keyof typeof TriplicityRole];
 71→
 72→type TriplicityRulers = {
 73→	diurnal: Node;
 74→	nocturnal: Node;
 75→	participating: Node | null;
 76→};
 77→
 78→type TriplicityData = Record<Element, TriplicityRulers>;
 79→
 80→const dorotheanTriplicityData: TriplicityData = {
 81→	[Element.FIRE]: { diurnal: Node.SUN, nocturnal: Node.JUPITER, participating: Node.SATURN },
 82→	[Element.EARTH]: { diurnal: Node.VENUS, nocturnal: Node.MOON, participating: Node.MARS },
 83→	[Element.AIR]: { diurnal: Node.SATURN, nocturnal: Node.MERCURY, participating: Node.JUPITER },
 84→	[Element.WATER]: { diurnal: Node.VENUS, nocturnal: Node.MARS, participating: Node.MOON },
 85→};
 86→
 87→const ptolemaicLillyTriplicityData: TriplicityData = {
 88→	[Element.FIRE]: { diurnal: Node.SUN, nocturnal: Node.JUPITER, participating: null },
 89→	[Element.EARTH]: { diurnal: Node.VENUS, nocturnal: Node.MOON, participating: null },
 90→	[Element.AIR]: { diurnal: Node.SATURN, nocturnal: Node.MERCURY, participating: null },
 91→	[Element.WATER]: { diurnal: Node.MARS, nocturnal: Node.MARS, participating: null },
 92→};
 93→
 94→const triplicityDataByMode: Record<TriplicityMode, TriplicityData> = {
 95→	[TriplicityMode.DOROTHEAN]: dorotheanTriplicityData,
 96→	[TriplicityMode.PTOLEMAIC_LILLY]: ptolemaicLillyTriplicityData,
 97→};
 98→
 99→export function getTriplicityRole(node: Node, zodiacPositions: ZodiacPositions, triplicityMode: TriplicityMode): TriplicityRole | null {
100→	if (!standardNodes.includes(node)) {
101→		throw new Error(`getTriplicityRole is only valid for planets and luminaries, got: ${node}`);
102→	}
103→
104→	const sign = zodiacPositions.getSymbolOfNode(node);
105→	
106→	if (sign === Zodiac.OPHIUCHUS) {
107→		return null;
108→	}
109→	
110→	const elem = zodiacElement[sign];
111→	const triplicityData = triplicityDataByMode[triplicityMode];
112→	const rulers = triplicityData[elem];
113→
114→	if (getChartSect(zodiacPositions) === Sect.DIURNAL) {
115→		if (rulers.diurnal === node) {
116→			return TriplicityRole.DIURNAL;
117→		}
118→	} else {
119→		if (rulers.nocturnal === node) {
120→			return TriplicityRole.NOCTURNAL;
121→		}
122→	}
123→	if (rulers.participating === node) {
124→		return TriplicityRole.PARTICIPATING;
125→	}
126→
127→	return null;
128→}
