371→function generateChaldeanBoundsData(sect: Sect): BoundsData{
372→	if (sect === Sect.VARIABLE) {
373→		throw new Error(`generateChaldeanBoundsData does not support variable sect (not a valid chart sect)`);
374→	}
375→	const isDiurnalChart = sect === Sect.DIURNAL;
376→	// matching triplicity data, excl. luminaries/participants/venus in water
377→	const firstTriplicityRuler = Node.JUPITER;
378→	const secondTriplicityRuler = Node.VENUS;
379→	const thirdTriplicityRulerPrimary = isDiurnalChart ? Node.SATURN : Node.MERCURY;
380→	const thirdTriplicityRulerSecondary = isDiurnalChart ? Node.MERCURY : Node.SATURN;
381→	
382→	const fourthTriplicityRuler = Node.MARS;
383→	const triplicityLords = [
384→		[firstTriplicityRuler, secondTriplicityRuler, thirdTriplicityRulerPrimary, thirdTriplicityRulerSecondary, fourthTriplicityRuler],
385→		[secondTriplicityRuler, thirdTriplicityRulerPrimary, thirdTriplicityRulerSecondary, fourthTriplicityRuler, firstTriplicityRuler],
386→		[thirdTriplicityRulerPrimary, thirdTriplicityRulerSecondary, fourthTriplicityRuler, firstTriplicityRuler, secondTriplicityRuler],
387→		[fourthTriplicityRuler, firstTriplicityRuler, secondTriplicityRuler, thirdTriplicityRulerPrimary, thirdTriplicityRulerSecondary],
388→	];
389→	const boundsData: BoundsData = {};
390→	for (let i = 0; i < 12; i++){
391→		const sign = standardZodiac[i];
392→		const lords = triplicityLords[i%4];
393→		// 8, 7, 6, 5, 4
394→		boundsData[sign] = [
395→			{ upToDegree: 8, lord: lords[0] },
396→			{ upToDegree: 15, lord: lords[1] },
397→			{ upToDegree: 21, lord: lords[2] },
398→			{ upToDegree: 26, lord: lords[3] },
399→			{ upToDegree: 30, lord: lords[4] },
400→		];
401→	}
402→	return boundsData;
403→}
