408→function getBoundsData(boundsMode: BoundsMode, zodiacPositions: ZodiacPositions): BoundsData{
409→	if (boundsMode === BoundsMode.EGYPTIAN){
410→		return egyptianBoundsData;
411→	} else if (boundsMode === BoundsMode.PTOLEMAIC){
412→		return ptolemaicBoundsData;
413→	} else { //chaldean
414→		const sect = getChartSect(zodiacPositions); // will error if no surface pos
415→		if (sect === Sect.DIURNAL) {
416→			return diurnalChaldeanBoundsData;
417→		} else {
418→			return nocturnalChaldeanBoundsData;
419→		}
420→	}
421→}
