423→export function getBoundLord(node: Node, zodiacPositions: ZodiacPositions, boundsMode: BoundsMode): Node {
424→	if (irregularAstrologyModes.includes(zodiacPositions.astrologyMode)) {
425→		throw new Error(`getBoundsLord is not supported for irregular astrology mode: ${zodiacPositions.astrologyMode}`);
426→	}
427→
428→	const sign = zodiacPositions.getSymbolOfNode(node);
429→	const positionInSign = zodiacPositions.getNodePositionWithinSign(node);
430→	const degreeInSign = positionInSign * 180 / Math.PI;
431→
432→	const boundsData = getBoundsData(boundsMode, zodiacPositions)
433→	const bounds = boundsData[sign];
434→	for (const bound of bounds) {
