  1→import { Node, Zodiac, standardNodes, classicalRulerships, modernRulerships } from './astroDefs';
  2→import { DignityMode } from './settingsDefs.ts'
  3→import ZodiacPositions from './zodiacPositions.ts'
  4→
  5→// this approach (to get copyWith) is actually unnecessary since changing either main arg results in full recomputation
  6→// but might be useful to keep it like this for later
  7→// and it wouldn't be impossible to avoid recomputation, actually, at the very least ruledBy is very redundant. but...
  8→
  9→function constructRulershipGraphInternals(zodiacPositions: ZodiacPositions, dignityMode: DignityMode) {
 10→		
 11→	const rulerships = dignityMode === DignityMode.CLASSICAL ? classicalRulerships : modernRulerships;
 12→	
 13→	const rules: Map<Node, Node[]> = new Map(standardNodes.map(node => [node, []]));
 14→	const ruledBy = new Map<Node, Node>();
 15→	const sign = new Map<Node, Zodiac>();
 16→	for ( const node of standardNodes ){
 17→		const symbol = zodiacPositions.getSymbolOfNode(node);
 18→		const ruler = rulerships[symbol]
 19→		ruledBy.set(node, ruler);
 20→		rules.get(ruler).push(node);
 21→		sign.set(node, symbol);
 22→	}
 23→	
 24→	const leafNodes: Node[] = standardNodes.filter(node => rules.get(node).length == 0);
 25→	
 26→	const isFinalDispositor: Map<Node, boolean> = new Map(standardNodes.map(node => [node, false]));
 27→	const finalDispositors: Node[][] = [];
 28→	
 29→	const visited: Map<Node, boolean> = new Map(standardNodes.map(node => [node, false]));
 30→	for ( const node of standardNodes ){
 31→		const chain: Node[] = [];
 32→		var currentNode = node;
 33→		while (true) {
 34→			if (visited.get(currentNode)){
 35→				if (chain.includes(currentNode)){
 36→					//dispositor cycle!!
 37→					const idx = chain.findIndex(n => n == currentNode);
 38→					const finalDispositorGroup = chain.slice(idx, chain.length);
 39→					finalDispositors.push(finalDispositorGroup);
 40→					finalDispositorGroup.forEach(dispositor => isFinalDispositor.set(dispositor, true));
 41→				}
 42→				// if it's a dispositor cycle, we already added it: moving on...
 43→				// if it's not a dispositorship cycle, then this is already explored: moving on...
 44→				break;
 45→			}
 46→			visited.set(currentNode, true);
 47→			chain.push(currentNode);
 48→			currentNode = ruledBy.get(currentNode);
 49→		}
 50→	}
 51→	
 52→	const signedFinalDispositors = finalDispositors.map(nodes => {
 53→		return {
 54→			nodes: nodes,
 55→			signs: nodes.map(node => sign.get(node)),
 56→		}
 57→	})
 58→	
 59→	return { rulerships, sign, ruledBy, rules, leafNodes, finalDispositors: signedFinalDispositors, isFinalDispositor };
 60→}
 61→
 62→export interface FinalDispositors {
 63→	nodes: Node[];
 64→	signs: Zodiac[];
 65→}
 66→
 67→export interface DispositorChain {
 68→	nodes: Node[];
 69→	signs: Zodiac[];
 70→	cycleStartIndex: number;
 71→}
 72→
 73→export function getFinalDispositorsOfChain(dispositorChain: DispositorChain): FinalDispositors {
 74→	const idx = dispositorChain.cycleStartIndex;
 75→	const len = dispositorChain.nodes.length;
 76→	return {
 77→		nodes: dispositorChain.nodes.slice(idx, len),
 78→		signs: dispositorChain.signs.slice(idx, len),
 79→	}
 80→}
