 82→interface RulershipGraphConstructorArgs {
 83→	zodiacPositions: ZodiacPositions,
 84→	dignityMode: DignityMode,
 85→	// internal
 86→	_rulerships?: Map<Zodiac, Node>;
 87→	_sign?: Map<Node, Zodiac>;
 88→	_ruledBy?: Map<Node, Node>;
 89→	_rules?: Map<Node, Node[]>;
 90→	_leafNodes?: Node[];
 91→	_finalDispositors?: FinalDispositors[];
 92→	_isFinalDispositor?: Map<Node, boolean>;
 93→}
 94→
 95→export class RulershipGraph {
 96→	public readonly zodiacPositions: ZodiacPositions;
 97→	public readonly dignityMode: DignityMode;
 98→	
 99→	private readonly _rulerships: Map<Zodiac, Node>;
100→	private readonly _sign: Map<Node, Zodiac>;
101→	private readonly _ruledBy: Map<Node, Node>;
102→	private readonly _rules: Map<Node, Node[]>;
103→	private readonly _leafNodes: Node[];
104→	private readonly _finalDispositors: Node[][];
105→	private readonly _isFinalDispositor: Map<Node, boolean>;
106→	
107→	constructor( config: ZodiacPositionsConstructorArgs ){
108→		this.zodiacPositions = config.zodiacPositions;
109→		this.dignityMode = config.dignityMode;
110→		
111→		if (config._ruledBy) {
112→			this._rulerships = config._rulerships;
113→			this._sign = config._sign;
114→			this._ruledBy = config._ruledBy;
115→			this._rules = config._rules;
116→			this._leafNodes = config._leafNodes;
117→			this._finalDispositors = config._finalDispositors;
118→			this._isFinalDispositor = config._isFinalDispositor;
119→			return;
120→		} else {
121→			const { rulerships, sign, ruledBy, rules, leafNodes, finalDispositors, isFinalDispositor } = constructRulershipGraphInternals(this.zodiacPositions, this.dignityMode);
122→			this._rulerships = rulerships;
123→			this._sign = sign;
124→			this._ruledBy = ruledBy;
125→			this._rules = rules;
126→			this._leafNodes = leafNodes;
127→			this._finalDispositors = finalDispositors;
128→			this._isFinalDispositor = isFinalDispositor;	
129→		}
130→	}
131→	
132→	static create(
133→		zodiacPositions: ZodiacPositions,
134→		dignityMode: DignityMode,
135→	): RulershipGraph {
136→		return new RulershipGraph({
137→			zodiacPositions: zodiacPositions,
138→			dignityMode: dignityMode,
139→		});
140→	}
141→	
142→	private copyWith( updates: Partial<RulershipGraphConstructorArgs> ): RulershipGraph {
143→		return new RulershipGraph({
144→			zodiacPositions: this.zodiacPositions,
145→			dignityMode: this.dignityMode,
146→			//internal
147→			_rulerships: this._rulerships,
148→			_sign: this._sign,
149→			_ruledBy: this._ruledBy,
150→			_rules: this._rules,
151→			_leafNodes: this._leafNodes,
152→			_finalDispositors: this._finalDispositors,
153→			_isFinalDispositor: this._isFinalDispositor,
154→			...updates
155→		});
156→	}
157→	
158→	public getDispositorChain(node: Node): DispositorChain{
159→		const chain = [];
160→		var firstFinalDispositor: Node | null = null;
161→		var firstFinalDispositorIdx: number | null = null;
162→		var currentNode = node;
163→		var idx = 0;
164→		while (chain.length<10) {
165→			if ( firstFinalDispositor === null ){
166→				if (this._isFinalDispositor.get(currentNode)){
167→					firstFinalDispositor = currentNode;
168→					firstFinalDispositorIdx = idx;
169→				}
170→			} else if (currentNode == firstFinalDispositor){
171→				break;
172→			}
173→			idx++;
174→			chain.push(currentNode);
175→			currentNode = this._ruledBy.get(currentNode);
176→		}
177→		return {
178→			nodes: chain,
179→			signs: chain.map(node => this._sign.get(node)),
180→			cycleStartIndex: firstFinalDispositorIdx,
181→		}
182→	}
183→	
184→	public getDispositorChainForNonstandardNode(node: node, sign: Zodiac): DispositorChain {
185→		const chain = this.getDispositorChain(this._rulerships[sign]);
186→		return {
187→			nodes: [node, ...chain.nodes],
188→			signs: [sign, ...chain.signs],
189→			cycleStartIndex: chain.cycleStartIndex + 1,
190→		}
191→	}
192→	
193→	public getRuledNodes(node: Node, transitive: boolean): Node[]{
194→		if (!transitive){
195→			return this._rules.get(node).filter(n => n !== node);
196→		}
197→		// otherwise, some tree search
198→		const transitivelyRuledNodes: Node[] = [];
199→		const nodesToExpand: Node[] = [...this._rules.get(node)];
200→		const visited = [node];
201→		while (nodesToExpand.length > 0) {
202→			const currentNode = nodesToExpand.pop();
203→			if (this._isFinalDispositor.get(currentNode)){
204→				if (visited.includes(currentNode)){
205→					continue;
206→				} else {
207→					visited.push(currentNode);
208→				}
209→			}
210→			transitivelyRuledNodes.push(currentNode);
211→			// no satisfying way to do this in js
212→			for (const otherNode of this._rules.get(currentNode)){
213→				nodesToExpand.push(otherNode);
214→			}
215→		}
216→		return transitivelyRuledNodes;
217→	}
218→	
219→	public getLeafNodes(): Node[]{
220→		return this._leafNodes;
221→	}
222→	
223→	public getFinalDispositors(): Node[][]{
224→		return this._finalDispositors;
225→	}
226→	
227→	public isFinalDispositor(node: Node): boolean{
228→		return this._isFinalDispositor.get(node);
229→	}
230→}
