212→function eclipticLongitudeToRAAndDeclination(longitude: number, axialTilt: number){
213→	// formula transparent, makes sense
214→	const RA = Math.atan2(Math.sin(longitude)*Math.cos(axialTilt), Math.cos(longitude));
215→	const declination = Math.asin(Math.sin(axialTilt)*Math.sin(longitude));
216→	return {RA, declination}
217→}
218→
219→// returns radians as a unit of time (2pi = 24hr)
220→function timeToHorizon(pointRA: number, pointDeclination: number, RAMC: number, observerLatitude: number): number | null{
221→	
222→	const cosAD = -Math.tan(observerLatitude * Math.PI / 180)*Math.tan(pointDeclination);
223→	if ( Math.abs(cosAD) > 1 ) {
224→		return null;
225→	}
226→	const TAU = 2*Math.PI;
227→	const AD = Math.acos(cosAD); //hour angle btw observer (=MC=meridian) and (point-on-the-same-latitude-as-point)-on-the-horizon
228→	const H = RAMC - pointRA; // point H off the meridian (=observer)
229→	const adjH = ((H + AD)%TAU+TAU)%TAU - AD; // mod 2pi conjugated by -AD -> mod but maps to (-AD, TAU-AD)
230→	if (adjH <= AD) {
231→		return AD - adjH;
232→	} else {
233→		return TAU - AD - adjH;
234→	}
235→}
236→
237→// returns radians as a unit of time (2pi = 24hr)
238→function timeSinceHorizon(pointRA: number, pointDeclination: number, RAMC: number, observerLatitude: number): number | null{
239→	
240→	const cosAD = -Math.tan(observerLatitude * Math.PI / 180)*Math.tan(pointDeclination);
241→	if ( Math.abs(cosAD) > 1 ) {
242→		return null;
243→	}
244→	const TAU = 2*Math.PI;
245→	const AD = Math.acos(cosAD); //hour angle btw observer (=MC=meridian) and (point-on-the-same-latitude-as-point)-on-the-horizon
246→	const H = RAMC - pointRA; // point H off the meridian (=observer)
247→	const adjH = ((H + AD)%TAU+TAU)%TAU - AD; // mod 2pi conjugated by -AD -> mod but maps to (-AD, TAU-AD)
248→	if (adjH <= AD) {
249→		return AD + adjH;
250→	} else {
251→		return adjH - AD;
252→	}
253→}
254→
255→// returns radians as a unit of time (2pi = 24hr)
256→function timeToMeridian(pointRA: number, RAMC: number): number{
257→	const H = RAMC - pointRA;
258→	return Math.PI-((H)%Math.PI+Math.PI)%Math.PI // pi - (h mod pi)
259→}
260→
261→export const MainAxisArc = {
262→	ASC_TO_MC: "Asc to MC",
263→	DSC_TO_MC: "Dsc to MC",
264→	ASC_TO_IC: "Asc to IC",
265→	DSC_TO_IC: "Dsc to IC",
266→} as const;
267→export type MainAxisArc = typeof MainAxisArc[keyof typeof MainAxisArc];
268→
269→function placidusCuspSearch(obsLatitude: number, axialTilt: number, eps: number, angles: AxisAngles, mode: MainAxisArc, c: number): number | null { 
270→	const { asc, mc, dsc, ic } = angles;
271→	const { RA: RAMC } = eclipticLongitudeToRAAndDeclination(mc, axialTilt);
272→	const start = ([MainAxisArc.ASC_TO_IC, MainAxisArc.ASC_TO_MC] as MainAxisArc[]).includes(mode) ? asc : dsc;
273→	const end = ([MainAxisArc.ASC_TO_MC, MainAxisArc.DSC_TO_MC] as MainAxisArc[]).includes(mode) ? mc : ic;
274→	var x = interpolateShorterAngle(c, start, end);
275→	var y = x - 2*eps;
276→	function f(eclLon: number): number | null{
277→		const { RA, declination } = eclipticLongitudeToRAAndDeclination(eclLon, axialTilt);
278→		var tsh, tth, ttm, tsm;
279→		switch (mode){
280→			case MainAxisArc.ASC_TO_MC:	
281→				tsh = timeSinceHorizon(RA, declination, RAMC, obsLatitude);
282→				if ( tsh === null ) { return null; }
283→				ttm = timeToMeridian(RA, RAMC);
284→				return (1-c)*tsh - c*ttm;
285→			case MainAxisArc.DSC_TO_MC:
286→				tth = timeToHorizon(RA, declination, RAMC, obsLatitude);
287→				if ( tth === null ) { return null; }
288→				tsm = Math.PI-timeToMeridian(RA, RAMC);
289→				return (1-c)*tth - c*tsm;
290→			case MainAxisArc.ASC_TO_IC:	
291→				tth = timeToHorizon(RA, declination, RAMC, obsLatitude);
292→				if ( tth === null ) { return null; }
293→				tsm = Math.PI-timeToMeridian(RA, RAMC);
294→				return (1-c)*tth - c*tsm;
295→			case MainAxisArc.DSC_TO_IC:	
296→				tsh = timeSinceHorizon(RA, declination, RAMC, obsLatitude);
297→				if ( tsh === null ) { return null; }
298→				ttm = timeToMeridian(RA, RAMC);
299→				return (1-c)*tsh - c*ttm;
300→		}
301→	}
302→	var fx = f(x);
303→	var fy = f(y);
304→	if (fx === null || fy === null) { return null; }
305→	var z = 0;
306→	var fz: number | null = 0;
307→	var counter = 0;
308→	const max_iter = 100;
309→	while ( Math.abs(x - y) > 1e-10 ) {
310→		z = y - fy*(x-y)/(fx-fy); // secant
311→		fz = f(z);
312→		counter++;
313→		if ( fz === null || counter >= max_iter ) { return null; }
314→		if ( Math.abs(fz) < 1e-10 ) {
315→			x = y;//exit
316→		} else if ( Math.abs(fx) > Math.abs(fy) ) {
317→			x = z;
318→			fx = fz;
319→		} else {
320→			y = z;
321→			fy = fz;
322→		}
323→	}
324→	return z;
325→}
326→
327→function computeAxialTilt(date: Date): number {
328→	// in radians
329→	const vecPole = new Vector(0, 0, 1, new AstroTime(date));
330→	const eclPole = Ecliptic(vecPole);
331→	const obliquity = Math.acos(eclPole.vec.z);
332→	return obliquity;
333→}
334→
335→function computePlacidusCuspPositions(date: Date, surfacePosition: SurfacePosition, angles: AxisAngles): number[] | null {
336→	// 12th cusp is the point along the ecliptic which is 1/3rd of the way, time-wise, from the ascendant to the mc
337→	
338→	// note: some people claim asc is midpoint, timewise, btw asc-dsc. This would simplify calculations but it is false
339→	const axialTilt = computeAxialTilt(date);
340→	const eps = 0.01;
341→	
342→	const houseCusps = [
343→		angles.asc,
344→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.ASC_TO_IC, 1/3),
345→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.ASC_TO_IC, 2/3),
346→		angles.ic,
347→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.DSC_TO_IC, 2/3),
348→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.DSC_TO_IC, 1/3),
349→		angles.dsc,
350→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.DSC_TO_MC, 1/3),
351→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.DSC_TO_MC, 2/3),
352→		angles.mc,
353→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.ASC_TO_MC, 2/3),
354→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.ASC_TO_MC, 1/3)
355→	];
356→	
357→	const containsNull = houseCusps.some(cusp => cusp === null);
358→	return containsNull ? null : houseCusps as number[];
359→}
360→
361→function computeAscendantAndDescendant(date: Date, surfacePos: SurfacePosition): Map<Node, number> {
362→	const latitudeDeg = surfacePos.latitude;
363→	const longitudeDeg = surfacePos.longitude;
364→	const gstHours = SiderealTime(date);
365→	const lstHours = gstHours + longitudeDeg / 15.0;
366→	const lstHoursNorm = ((lstHours % 24) + 24) % 24;
367→	const theta = lstHoursNorm * Math.PI / 12
368→	
369→	const epsRad = computeAxialTilt(date);
370→		
371→	const phi = latitudeDeg * Math.PI/180;
372→	
373→	const x = Math.cos(theta);
374→	const y = - (Math.sin(theta) * Math.cos(epsRad) + Math.tan(phi) * Math.sin(epsRad));
375→	const lambda = Math.atan2(x,y);
376→	
377→	return new Map<Node, number>([
378→		[Node.ASCENDANT, normalizeAngleRad(lambda)],
379→		[Node.DESCENDANT, normalizeAngleRad(lambda + Math.PI)]
380→	]);
381→}
382→
383→function computeKochCuspPositions(date: Date, surfacePosition: SurfacePosition, angles: AxisAngles){
384→	//consider the time it took the current mc to arrive there from the horizon. 12th house is the 1/3rd point (time-wise)
385→	
386→	// setup
387→	const axialTilt = computeAxialTilt(date);	
388→	const { asc, mc, dsc, ic } = angles;
389→	
390→	// how long did the current mc take to arrive from the horizon?
391→	const { RA: RAMC, declination: declinationMC } = eclipticLongitudeToRAAndDeclination(mc, axialTilt);
392→	const tshRadMC = timeSinceHorizon(RAMC, declinationMC, RAMC, surfacePosition.latitude);
393→	// how long will the current mc take to get to the horizon again?
394→	const tthRadMC = timeToHorizon(RAMC, declinationMC, RAMC, surfacePosition.latitude);
395→	// how long did the current ic take to arrive from the horizon?
396→	const { RA: RAIC, declination: declinationIC } = eclipticLongitudeToRAAndDeclination(ic, axialTilt);
397→	const tshRadIC = timeSinceHorizon(RAIC, declinationIC, RAMC, surfacePosition.latitude);
398→	// how long will the current ic take to get to the horizon again?
399→	const tthRadIC = timeToHorizon(RAIC, declinationIC, RAMC, surfacePosition.latitude);
400→	
401→	if (
402→		tshRadMC === null ||
403→		tthRadMC === null ||
404→		tshRadIC === null ||
405→		tthRadIC === null
406→	){
407→		return null;
408→	}
409→	
410→	// first quadrant
411→	const tshHoursMC = tshRadMC * 12 / Math.PI;
412→	
413→	const date11th = new Date(date.getTime() - tshHoursMC*(2/3)*3600*1000)
414→	const date12th = new Date(date.getTime() - tshHoursMC*(1/3)*3600*1000)
415→	const cusp11 = computeAscendantAndDescendant(date11th, surfacePosition).get(Node.ASCENDANT)!;
416→	const cusp12 = computeAscendantAndDescendant(date12th, surfacePosition).get(Node.ASCENDANT)!;
417→	
418→	// second quadrant
419→	const tthHoursMC = tthRadMC* 12 / Math.PI;
420→	
421→	const date8th = new Date(date.getTime() + tthHoursMC*(1/3)*3600*1000)
422→	const date9th = new Date(date.getTime() + tthHoursMC*(2/3)*3600*1000)
423→	const cusp8 = computeAscendantAndDescendant(date8th, surfacePosition).get(Node.DESCENDANT)!;
424→	const cusp9 = computeAscendantAndDescendant(date9th, surfacePosition).get(Node.DESCENDANT)!;
425→	
426→	// third quadrant
427→	const tshHoursIC = tshRadIC* 12 / Math.PI;
428→	
429→	const date5th = new Date(date.getTime() - tshHoursIC*(2/3)*3600*1000)
430→	const date6th = new Date(date.getTime() - tshHoursIC*(1/3)*3600*1000)
431→	const cusp5 = computeAscendantAndDescendant(date5th, surfacePosition).get(Node.DESCENDANT)!;
432→	const cusp6 = computeAscendantAndDescendant(date6th, surfacePosition).get(Node.DESCENDANT)!;
433→	
434→	// fourth quadrant
435→	const tthHoursIC = tthRadIC * 12 / Math.PI;
436→	
437→	const date2nd = new Date(date.getTime() + tthHoursIC*(1/3)*3600*1000)
438→	const date3rd = new Date(date.getTime() + tthHoursIC*(2/3)*3600*1000)
439→	const cusp2 = computeAscendantAndDescendant(date2nd, surfacePosition).get(Node.ASCENDANT)!;
440→	const cusp3 = computeAscendantAndDescendant(date3rd, surfacePosition).get(Node.ASCENDANT)!;
441→				
442→	return [asc, cusp2, cusp3, ic, cusp5, cusp6, dsc, cusp8, cusp9, mc, cusp11, cusp12];
443→}
444→
445→function computePolichPageCusp(c: number, p1: number, p2: number, tp1: number, tp2: number, axialTilt: number): number {
446→	const cuspDecl = Math.atan(c * tp1 + (1-c) * tp2);
447→	const cuspLongOpt1 = Math.asin(Math.sin(cuspDecl)/Math.sin(axialTilt));
448→	const cuspLongOpt2 = (cuspLongOpt1 > 0 ? Math.PI : -Math.PI) - cuspLongOpt1;
449→	if ( anglesLieInShortArc(p1, cuspLongOpt1, p2) ) {
450→		return cuspLongOpt1;
451→	} else {
452→		return cuspLongOpt2;
453→	}
454→}
455→
456→// TODO works, but is not close to placidus. Are some of the calculations wrong?
457→// ugh... another serious release blocker
458→// tried three other ways, none worked. see scripts/discarded.ts
459→// we'll just remove this from the options for now.
460→function computeTopocentricCuspPositions(date: Date, angles: AxisAngles){
461→	// polich - page. Consider the "polar elevation" of the asc-mc, i.e. its geographic latitude
462→	// consider tangents, trisect interval, invert over the ecliptic.
463→	
464→	const axialTilt = computeAxialTilt(date);	
465→	const { asc, mc, dsc, ic } = angles;
466→	
467→	const { declination: declinationMC } = eclipticLongitudeToRAAndDeclination(mc, axialTilt);
468→	const { declination: declinationASC } = eclipticLongitudeToRAAndDeclination(asc, axialTilt);
469→	const { declination: declinationIC } = eclipticLongitudeToRAAndDeclination(ic, axialTilt);
470→	const { declination: declinationDSC } = eclipticLongitudeToRAAndDeclination(dsc, axialTilt);
471→	
472→	const tAsc = Math.tan(declinationASC);
473→	const tMc = Math.tan(declinationMC);
474→	const tDsc = Math.tan(declinationDSC);
475→	const tIc = Math.tan(declinationIC);
476→	
477→	return [
478→		asc,
479→		computePolichPageCusp(2/3, asc, ic, tAsc, tIc, axialTilt),
480→		computePolichPageCusp(1/3, asc, ic, tAsc, tIc, axialTilt),
481→		ic,
482→		computePolichPageCusp(2/3, ic, dsc, tIc, tDsc, axialTilt),
483→		computePolichPageCusp(1/3, ic, dsc, tIc, tDsc, axialTilt),
484→		dsc,
485→		computePolichPageCusp(2/3, dsc, mc, tDsc, tMc, axialTilt),
486→		computePolichPageCusp(1/3, dsc, mc, tDsc, tMc, axialTilt),
487→		mc,
488→		computePolichPageCusp(2/3, mc, asc, tMc, tAsc, axialTilt),
489→		computePolichPageCusp(1/3, mc, asc, tMc, tAsc, axialTilt)
490→	]
491→}
492→void computeTopocentricCuspPositions;
493→
494→export function computeHouseCuspPositions(
495→	date: Date,
496→	surfacePosition: SurfacePosition,
497→	houseSystem: HouseSystem,
498→	knownNodes: Map<Node, number>,
499→	zodiacSymbolPositions: Map<Zodiac, number>
500→): number[] | null {
501→	const angles = {
502→		asc: knownNodes.get(Node.ASCENDANT)!,
503→		dsc: knownNodes.get(Node.DESCENDANT)!,
504→		mc: knownNodes.get(Node.MIDHEAVEN)!,
505→		ic: knownNodes.get(Node.IMUM_COELI)!
506→	}
507→	switch (houseSystem) {
508→		case HouseSystem.WHOLE_SIGN:
509→			return computeWholeSignCuspPositions(angles, zodiacSymbolPositions);
510→		case HouseSystem.EQUAL_HOUSES:
511→			return computeEqualHousesCuspPositions(angles);
512→		case HouseSystem.PORPHYRY:
513→			return computePorphyryCuspPositions(angles);
514→		case HouseSystem.EQUAL_HOUSES_VEHLOW:
515→			return computeEqualHousesVehlowCuspPositions(angles);
516→		case HouseSystem.WHOLE_SIGN_ARIES:
517→			return computeWholeSignAriesCuspPositions(zodiacSymbolPositions);
518→		case HouseSystem.KRUSINSKY:
519→			return computeKrusinskyCuspPositions(date, surfacePosition);
520→		case HouseSystem.REGIOMONTANUS:
521→			return computeRegiomontanusCuspPositions(date, surfacePosition);
522→		case HouseSystem.MERIDIAN:
523→			return computeMeridianCuspPositions(date, surfacePosition);
524→		case HouseSystem.MORINUS:
525→			return computeMorinusCuspPositions(date, surfacePosition);
526→		case HouseSystem.CAMPANUS:
527→			return computeCampanusCuspPositions(date, surfacePosition);
528→		case HouseSystem.ZENITH_HORIZONTAL:
529→			return computeZenithHorizontalCuspPositions(date, surfacePosition);
530→		case HouseSystem.PLACIDUS:
531→			return computePlacidusCuspPositions(date, surfacePosition, angles);
532→		case HouseSystem.KOCH:
533→			return computeKochCuspPositions(date, surfacePosition, angles);
534→		default:
535→			throw new Error("something wrong with house computation dispatch:", houseSystem);
536→	}
537→}
