 15→function computeLunarApogeePerigee(date: Date, lunarNodeMode: LunarNodeMode): Map<Node, number>{
 16→	if (lunarNodeMode == LunarNodeMode.MEAN) {
 17→		return computeLunarApogeePerigeeMeeus(date);
 18→	} else {
 19→		return computeLunarApogeePerigeeExact(date);
 20→	}
