 23→function computeLunarNodes(date: Date, lunarNodeMode: LunarNodeMode): Map<Node, number>{
 24→	if (lunarNodeMode == LunarNodeMode.MEAN) {
 25→		return computeLunarNodesMeeus(date);
 26→	} else {
 27→		return computeLunarNodesExact(date);
 28→	}
