 31→function computeAxisAngles(date: Date, surfacePos: SurfacePosition): Map<Node, number> {
 32→	const { asc, mc, vx } = computeAllSignificantPoints(date, surfacePos);
 33→	
 34→	const ascLon = getTodayEclipticLongitudeFromEQJ(date, asc);
 35→	const mcLon = getTodayEclipticLongitudeFromEQJ(date, mc);
 36→	const vxLon = getTodayEclipticLongitudeFromEQJ(date, vx);
 37→
 38→	return new Map<Node, number>([
 39→		[Node.ASCENDANT, normalizeAngleRad(ascLon)],
 40→		[Node.DESCENDANT, normalizeAngleRad(ascLon + Math.PI)],
 41→		[Node.MIDHEAVEN, normalizeAngleRad(mcLon)],
 42→		[Node.IMUM_COELI, normalizeAngleRad(mcLon + Math.PI)],
 43→		[Node.VERTEX, normalizeAngleRad(vxLon)],
 44→		[Node.ANTIVERTEX, normalizeAngleRad(vxLon + Math.PI)],
 45→	]);
 46→}
