 48→function computeEquinoxes(): Map<Node, number> {
 49→	return new Map<Node, number>([
 50→		[Node.VERNAL_EQUINOX, 0],
 51→		[Node.AUTUMNAL_EQUINOX, Math.PI]
 52→	]);
 53→}
