 55→function computePhysicalNodePositions(date: Date): Map<Node, number> {
 56→	const nodeAngles = new Map<Node, number>();
 57→	for ( const [node, body] of Object.entries(nodeToBody)) {
 58→		const lon = bodyToGeocentricLongitude(body, date);
 59→		nodeAngles.set(node as Node, lon);
 60→	}
 61→	return nodeAngles;
 62→}
