 65→function computeSmallObjectPositions(date: Date): Map<Node, number> {
 66→	const nodeAngles = new Map<Node, number>();
 67→
 68→	for (const [node, params] of Object.entries(smallBodyParams)) {
 69→		const lon = orbitalParamsToGeocentricLongitude(params, date);
 70→		nodeAngles.set(node as Node, lon);
 71→	}
