 76→function computeHamburgSchoolObjectPositions(date: Date, hamburgSchoolMode: HamburgSchoolMode): Map<Node, number> {
 77→	const nodeAngles = new Map<Node, number>();
 78→
 79→	const hamburgSchoolParams = hamburgSchoolMode == HamburgSchoolMode.NEELY ? hamburgSchoolParamsNeely : hamburgSchoolParamsWitte;
 80→	for (const [node, params] of Object.entries(hamburgSchoolParams)) {
 81→		const lon = orbitalParamsToGeocentricLongitude(params, date);
 82→		nodeAngles.set(node as Node, lon);
 83→	}
 84→
 85→	return nodeAngles;
 86→}
