 88→function computeArabicPartPositions(nodePositions: Map<Node, number>): Map<Node, number> {
 89→	const asc = nodePositions.get(Node.ASCENDANT)!;
 90→	const sun = nodePositions.get(Node.SUN)!;
 91→	const d = normalizeAngleRad(sun-asc);
 92→	const dayBirth = d > Math.PI;
 93→	const f = dayBirth ? 1 : -1;
 94→	//source: https://horoscopes.astro-seek.com/astrology-arabic-lots-list
 95→	// there's a bajillion of these. I see two ideas:
 96→	// - just the part of fortune. that's basic.
 97→	// - all of them, with some complicated filters to include them by source/category/etc.
 98→	// I don't think there's a midpoint between the two. 
 99→	// let's just leave the PoF for now and look into the other stuff later down the line.
100→	
101→	// oh, and this will depend on house cusps eventually, so we'll need to move things around a bit.
102→	// this will probably go in its own file, anyway.
103→	return new Map <Node, number>([
104→		[Node.PART_OF_FORTUNE, asc + f*(nodePositions.get(Node.MOON)! - nodePositions.get(Node.SUN)!)],
105→		//[Node.PART_OF_SPIRIT, asc + f*(nodePositions.get(Node.SUN) - nodePositions.get(Node.MOON))],
106→		//[Node.PART_OF_LOVE, asc + f*(nodePositions.get(Node.VENUS) - nodePositions.get(Node.SUN))],
107→		//[Node.PART_OF_MARRIAGE, asc + f*(nodePositions.get(Node.DESCENDANT) - nodePositions.get(Node.VENUS))],
108→		//[Node.PART_OF_NECESSITY, asc + f*(nodePositions.get(Node.SATURN) - nodePositions.get(Node.MOON))],
109→		
110→		//Dubious. Source notes same formula for parts of: commerce, communication, slaves 4b, vitality
111→		//[Node.PART_OF_CAREER, asc + f*(nodePositions.get(Node.MERCURY) - nodePositions.get(Node.SUN))],
112→		
113→		// first source said courage = mars - sun. not in main source, equals:
114→		// commerce (jacobson), conquest, deceit, destruction(jones), dignity B, enemies (olympiodorus B), fire, lost animal, passion, sowing, travel (firmicus), wheat
115→		// okay.
116→		// [Node.PART_OF_COURAGE, asc + f*(nodePositions.get(Node.MARS) - nodePositions.get(Node.SUN))],
117→		
118→		//[Node.PART_OF_LONGEVITY, asc + f*(nodePositions.get(Node.MOON) - nodePositions.get(Node.JUPITER))],
119→		//[Node.PART_OF_DEATH, asc + f*(houseCusps[7] - nodePositions.get(Node.MOON))], //8th cusp
120→	]);
121→}
