155→function computeSiderealOffset(date: Date, astrologyMode: AstrologyMode): number {
156→	if (astrologyMode === AstrologyMode.TROPICAL) { return 0; }
157→	
158→	const ayanamsaJ2000 = ayanamsas[astrologyMode];
159→	if (ayanamsaJ2000 === undefined) {
160→		throw new Error("Irregular astrology mode passed to computeSiderealOffset");
161→	}
162→	
163→	return addPrecession(date, ayanamsaJ2000*Math.PI/180);
