313→	public changeLunarNodeMode(newMode: LunarNodeMode): ZodiacPositions {
314→		if (newMode == this.lunarNodeMode) {
315→			return this;
316→		}
317→		const newLunarNodePositions = computeLunarNodes(this.date, newMode);
318→		const newLilithSelenePositions = computeLunarApogeePerigee(this.date, newMode);
319→		const newNodePositions = new Map<Node, number>([ ...this._nodePositions, ...newLunarNodePositions, ...newLilithSelenePositions]);
320→		return this.copyWith({lunarNodeMode: newMode, nodePositions: newNodePositions});
