325→			return this;
326→		}
327→		const newHouseCuspPositions = this.surfacePosition ? 
328→			computeHouseCuspPositions(this.date, this.surfacePosition, newSystem, this._nodePositions, this._zodiacSymbolPositions)
329→			: null;
