333→	public changeHousePresweep(newHousePresweep: boolean): ZodiacPositions {
334→		return this.copyWith({housePresweep: newHousePresweep});
335→	}
336→	
337→	public changeAstrologyMode(newAstrologyMode: AstrologyMode): ZodiacPositions {
338→		if (newAstrologyMode == this.astrologyMode) {
339→			return this;
340→		}
341→		
342→		let newSiderealOffset: number;
343→		let newZodiacSymbolPositions: Map<Zodiac, number>;
344→		if (irregularAstrologyModes.includes(newAstrologyMode)){
345→			newSiderealOffset = null;
346→			newZodiacSymbolPositions = computeZodiacSymbolPositionsForIrregularMode(this.date, newAstrologyMode);
347→		} else {
348→			newSiderealOffset = computeSiderealOffset(this.date, newAstrologyMode);
349→			newZodiacSymbolPositions = computeZodiacSymbolPositionsFromSiderealOffset(newSiderealOffset);
350→		}
351→		
352→		if (ayanamsaDependantHouseSystems.includes(this.houseSystem) && this.surfacePosition !== null) {
353→			const newHouseCuspPositions = computeHouseCuspPositions(
354→				this.date,
355→				this.surfacePosition,
356→				this.houseSystem,
357→				this._nodePositions,
358→				newZodiacSymbolPositions
359→			);
360→			return this.copyWith({
361→				astrologyMode: newAstrologyMode,
362→				siderealOffset: newSiderealOffset,
363→				zodiacSymbolPositions: newZodiacSymbolPositions,
364→				houseCuspPositions: newHouseCuspPositions
365→			});
366→		} else {
