  1→import { useState, useEffect, useMemo, useRef } from 'react'
  2→
  3→import ZodiacWheel from './ZodiacWheel'
  4→import AspectMenu from './AspectMenu'
  5→import DominanceChart, { AbridgedDominanceChart } from './DominanceChart'
  6→import HemispheresChart from './HemispheresChart'
  7→import RulershipPanel from './RulershipPanel'
  8→import EsotericModePanel from './EsotericModePanel'
  9→import ChartSummary from './ChartSummary'
 10→import PlanetPanel from './PlanetPanel.tsx'
 11→import ZodiacPositions from './zodiacPositions.ts'
 12→import { RulershipGraph } from './rulershipGraph.ts'
 13→import Module from './Module'
 14→import { NodeSelector, AspectKindSelector } from './CategorySelector.tsx'
 15→import { Node } from './astroDefs.ts'
 16→import { toZonedTime, fromZonedTime, toISOLocal } from './util.ts'
 17→import { HouseSystem } from './houses.ts'
 18→import { findAspects, type Aspect, filterAspects, formatAspects, flattenSubaspectsToList, deleteAspectFromMap } from './aspects.ts'
 19→import { type CityData } from './CitySearchEngine'
 20→import { CitySelector } from './CitySelector'
 21→import { Sidebar } from './Sidebar'
 22→import { useSettingsStore } from './settingsStore.ts'
 23→import { Theme } from './settingsDefs.ts'
 24→import {
 25→	MainSettingsMenu,
 26→	DominanceSettingsMenu,
 27→	PlanetSettingsMenu,
 28→	RulershipSettingsMenu,
 29→	HemisphereSettingsMenu,
 30→	NodeSelectorSettingsMenu,
 31→	AspectSelectorSettingsMenu,
 32→	AspectMenuSettingsMenu
 33→} from './settingsMenus'
 34→import {
 35→	PlanetInfoHelp,
 36→	DominanceChartHelp,
 37→	OrientationHelp,
 38→	RulershipGraphHelp,
 39→	NodeSelectorHelp,
 40→	GeneralSettingsHelp,
 41→	AspectMenuHelp,
 42→} from './helpContent'
 43→import AboutThisWebsite from './AboutThisWebsite.tsx'
 44→
 45→function App() {
 46→
 47→	// Settings needed for computations in App
 48→	const houseSystem = useSettingsStore(s => s.houseSystem);
 49→	const setHouseSystem = useSettingsStore(s => s.setHouseSystem);
 50→	const housePresweep = useSettingsStore(s => s.housePresweep);
 51→	const aspectErrorMode = useSettingsStore(s => s.aspectErrorMode);
 52→	const maxConfigurationErrorDegrees = useSettingsStore(s => s.maxConfigurationErrorDegrees);
 53→	const maxMajorBAErrorDegrees = useSettingsStore(s => s.maxMajorBAErrorDegrees);
 54→	const maxMinorBAErrorDegrees = useSettingsStore(s => s.maxMinorBAErrorDegrees);
 55→	const maxConfigurationError = useMemo(() => maxConfigurationErrorDegrees*Math.PI/180, [maxConfigurationErrorDegrees]);
 56→	const maxMajorBAError = useMemo(() => maxMajorBAErrorDegrees*Math.PI/180, [maxMajorBAErrorDegrees]);
 57→	const maxMinorBAError = useMemo(() => maxMinorBAErrorDegrees*Math.PI/180, [maxMinorBAErrorDegrees]);
 58→
 59→	const aspectPhysicalityFilter = useSettingsStore(s => s.aspectPhysicalityFilter);
 60→	const hamburgPhysical = useSettingsStore(s => s.hamburgPhysical);
 61→	const aspectMenuMode = useSettingsStore(s => s.aspectMenuMode);
 62→
 63→	const lunarNodeMode = useSettingsStore(s => s.lunarNodeMode);
 64→	const hamburgSchoolMode = useSettingsStore(s => s.hamburgSchoolMode);
 65→	const zodiacMode = useSettingsStore(s => s.zodiacMode);
 66→	const dignityMode = useSettingsStore(s => s.dignityMode);
 67→
 68→	const selectedNodes = useSettingsStore(s => s.selectedNodes);
 69→	const setSelectedNodes = useSettingsStore(s => s.setSelectedNodes);
 70→	const selectedAspectKinds = useSettingsStore(s => s.selectedAspectKinds);
 71→	const setSelectedAspectKinds = useSettingsStore(s => s.setSelectedAspectKinds);
 72→
 73→	const theme = useSettingsStore(s => s.theme);
 74→
 75→	// Sync theme to document element
 76→	useEffect(() => {
 77→		document.documentElement.classList.remove('theme-parchment');
 78→		if (theme === Theme.PARCHMENT) {
 79→			document.documentElement.classList.add('theme-parchment');
 80→		}
 81→	}, [theme]);
 82→
 83→	// Local state (not settings)
 84→	const [selectedCity, setSelectedCity] = useState<CityData|null>(null);
 85→	const [selectedDate, setSelectedDate] = useState(new Date());
 86→	const [highlightedAspect, setHighlightedAspect] = useState<Aspect | null>(null);
 87→	const [menuOpen, setMenuOpen] = useState<boolean>(false);
 88→
 89→	// Node focus state
 90→	const [highlightedNode, setHighlightedNode] = useState<Node | null>(null);
 91→	const [selectedNode, setSelectedNode] = useState<Node>(Node.SUN);
 92→
 93→	// Sync selectedNode when highlightedNode becomes non-null
 94→	useEffect(() => {
 95→		if (highlightedNode !== null) {
 96→			setSelectedNode(highlightedNode);
 97→		}
 98→	}, [highlightedNode]);
 99→
100→	const [zodiacPositions, setZodiacPositions] = useState(ZodiacPositions.create(selectedDate, selectedCity, lunarNodeMode, houseSystem, zodiacMode, hamburgSchoolMode, housePresweep));
101→
102→	const rulershipGraph = useMemo<RulershipGraph>(() => {
103→		return RulershipGraph.create(zodiacPositions, dignityMode);
104→	}, [zodiacPositions, dignityMode])
105→
106→	// all aspects of all kinds from all nodes
107→	const fullAspects = useMemo(() => {
108→		return findAspects(zodiacPositions.getNodePositions(), aspectErrorMode, maxConfigurationError, maxMajorBAError, maxMinorBAError);
109→	}, [zodiacPositions, aspectErrorMode, maxConfigurationError, maxMajorBAError, maxMinorBAError]);
110→
111→	// aspects restricted to only selected kinds/nodes w/ sufficient physical nodes
112→	const filteredAspects = useMemo(() => {
113→		return filterAspects(
114→			fullAspects,
115→			zodiacPositions.getNodePositions(),
116→			selectedNodes,
117→			selectedAspectKinds,
118→			aspectPhysicalityFilter,
119→			hamburgPhysical,
120→			aspectErrorMode,
121→			maxConfigurationError,
122→			maxMajorBAError,
123→			maxMinorBAError
124→		);
125→		// note that errors or error mode are not in dependencies list
126→		// any change fullAspects recomputation which will force filteredAspects recomputation anyway
127→	}, [fullAspects, selectedNodes, selectedAspectKinds, aspectPhysicalityFilter, hamburgPhysical]);
128→
129→	// aspects, filtered, in the format imposed by the aspect menu mode
130→	const [aspects, setAspects] = useState<Map<Aspect, Aspect[]>>(formatAspects(filteredAspects, aspectMenuMode));
131→	useEffect(() => {
132→		setAspects(formatAspects(filteredAspects, aspectMenuMode));
133→	}, [filteredAspects, aspectMenuMode])
134→
135→	// aspects, flattened down to a single list for processing in UI components
136→	// (this might be possible to do w/ enforced redundancy but unnecessary and much too complicated, even considering the above)
137→	const flattenedAspects = useMemo(() => {
138→		return flattenSubaspectsToList(aspects)
139→	}, [aspects])
140→
141→	// recompute zodiac whenever date or time changes
142→	useEffect(() => {
143→		setZodiacPositions(ZodiacPositions.create(selectedDate, selectedCity, lunarNodeMode, houseSystem, zodiacMode, hamburgSchoolMode, housePresweep));
144→	}, [selectedCity, selectedDate])
145→
146→	// handlers for changing config details in the zodiac positions that only require partial recomputation
147→	useEffect(() => {
148→		setZodiacPositions(zodiacPositions.changeHouseSystem(houseSystem));
149→	}, [houseSystem])
150→	useEffect(() => {
151→		setZodiacPositions(zodiacPositions.changeLunarNodeMode(lunarNodeMode));
152→	}, [lunarNodeMode])
153→	useEffect(() => {
154→		setZodiacPositions(zodiacPositions.changeZodiacMode(zodiacMode));
155→	}, [zodiacMode])
156→	useEffect(() => {
157→		setZodiacPositions(zodiacPositions.changeHamburgSchoolMode(hamburgSchoolMode));
158→	}, [hamburgSchoolMode])
159→	useEffect(() => {
160→		setZodiacPositions(zodiacPositions.changeHousePresweep(housePresweep));
161→	}, [housePresweep])
162→	
163→	const currentTimezone = useMemo(() => {
164→		if (selectedCity === null) {
165→			return Intl.DateTimeFormat().resolvedOptions().timeZone;
166→		}
167→		return selectedCity.timezone;
168→	}, [selectedCity]);
169→
170→	// Debounced date input - local state updates immediately, actual state updates after delay
171→	const [dateInputValue, setDateInputValue] = useState<string>(
172→		toISOLocal(toZonedTime(selectedDate, currentTimezone)).slice(0, 16)
173→	);
174→	const dateDebounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
175→
176→	// Sync local input state when selectedDate or timezone changes externally
177→	useEffect(() => {
178→		setDateInputValue(toISOLocal(toZonedTime(selectedDate, currentTimezone)).slice(0, 16));
179→	}, [selectedDate, currentTimezone]);
180→
181→	function handleAspectDeletion(aspect: Aspect, parentAspect: Aspect | null){
182→		setAspects(deleteAspectFromMap(aspects, aspect, parentAspect));
183→	}
184→
185→	return (
186→		<div className="flex h-screen w-screen overflow-hidden bg-theme-bg">
187→			<Sidebar side="left">
188→				<div className="w-full bg-theme-bg border border-theme-border text-theme-text px-1">
189→					<CitySelector
190→						startingQueryText={selectedCity}
191→						onSelect={(city) => {
192→							setSelectedCity(city);
193→						}}
194→					/>
195→					<input
196→						aria-label="Date and time"
197→						type="datetime-local"
198→						className="text-sm"
199→						value={dateInputValue}
200→						onChange={(e) => {
201→							const newValue = e.target.value;
202→							setDateInputValue(newValue);
203→
204→							// Clear any pending debounce
205→							if (dateDebounceRef.current) {
206→								clearTimeout(dateDebounceRef.current);
207→							}
208→
209→							// Update actual state after 300ms of no typing
210→							dateDebounceRef.current = setTimeout(() => {
211→								const parsed = new Date(newValue);
212→								if (!isNaN(parsed.getTime())) {
213→									setSelectedDate(fromZonedTime(parsed, currentTimezone));
214→								}
215→							}, 300);
216→						}}
217→					/>
218→				</div>
219→				<Module
220→					title="Aspects"
221→					initialDisplayIndex={1}
222→					titlePosition={'right'}
223→					settingsMenu={AspectMenuSettingsMenu}
224→					helpContent={<AspectMenuHelp />}
225→				>
226→					<AspectMenu
227→						aspects={aspects}
228→						onHover={(aspect) => {setHighlightedAspect(aspect)}}
229→						onDelete={handleAspectDeletion}
