  1→import { Node, Zodiac, Element, zodiacElement, standardNodes, irregularZodiacModes, Sect, standardZodiac, classicalDignityData, modernDignityData, type DignityData } from './astroDefs.ts';
  2→import { DignityMode, TriplicityMode, FaceMode, BoundsMode } from './settingsDefs.ts';
  3→import { getChartSect } from './chartAnalysis.ts';
  4→import ZodiacPositions from './zodiacPositions.ts';
  5→
  6→export const Dignity = {
  7→	DOMICILE: "Domicile",
  8→	EXALTATION: "Exaltation",
  9→	DETRIMENT: "Detriment",
 10→	FALL: "Fall",
 11→	PEREGRINE: "Peregrine",
 12→} as const;
 13→export type Dignity = typeof Dignity[keyof typeof Dignity];
 14→
 15→export type DignityState = {
 16→	dignity: Dignity;
 17→	degreeOffset?: number;
 18→};
 19→
 20→export function getDignityState(node: Node, zodiacPositions: ZodiacPositions, dignityMode: DignityMode): DignityState | null {
 21→	const dignityData = dignityMode === DignityMode.CLASSICAL ? classicalDignityData : modernDignityData;
 22→
 23→	const data = dignityData[node];
 24→	if (!data) {
 25→		return null;
 26→	}
 27→
 28→	const sign = zodiacPositions.getSignOfNode(node);
 29→	const position = zodiacPositions.getNodePosition(node);
 30→	const signStartPositions = zodiacPositions.getSignPositions();
 31→	const signStart = signStartPositions.get(sign)!;
 32→	const degreeInSign = ((position - signStart) * 180 / Math.PI + 360) % 360;
 33→
 34→	if (data.domicile.includes(sign)) {
 35→		return { dignity: Dignity.DOMICILE };
 36→	}
 37→
 38→	if (data.exaltation && data.exaltation.sign === sign) {
 39→		if (data.exaltation.degree !== undefined && !irregularZodiacModes.includes(zodiacPositions.zodiacMode)) {
 40→			const offset = degreeInSign - data.exaltation.degree;
 41→			return { dignity: Dignity.EXALTATION, degreeOffset: offset };
 42→		}
 43→		return { dignity: Dignity.EXALTATION };
 44→	}
 45→
 46→	if (data.detriment.includes(sign)) {
 47→		return { dignity: Dignity.DETRIMENT };
 48→	}
 49→
 50→	if (data.fall && data.fall.sign === sign) {
 51→		if (data.fall.degree !== undefined && !irregularZodiacModes.includes(zodiacPositions.zodiacMode)) {
 52→			const offset = degreeInSign - data.fall.degree;
 53→			return { dignity: Dignity.FALL, degreeOffset: offset };
 54→		}
 55→		return { dignity: Dignity.FALL };
 56→	}
 57→
 58→	return { dignity: Dignity.PEREGRINE };
 59→}
 60→
 61→// ============================================================================
 62→// TRIPLICITIES
 63→// ============================================================================
 64→
 65→export const TriplicityRole = {
 66→	DIURNAL: "Diurnal",
 67→	NOCTURNAL: "Nocturnal",
 68→	PARTICIPATING: "Participating",
 69→} as const;
 70→export type TriplicityRole = typeof TriplicityRole[keyof typeof TriplicityRole];
 71→
 72→type TriplicityRulers = {
 73→	diurnal: Node;
 74→	nocturnal: Node;
 75→	participating: Node | null;
 76→};
 77→
 78→type TriplicityData = Record<Element, TriplicityRulers>;
 79→
 80→const dorotheanTriplicityData: TriplicityData = {
 81→	[Element.FIRE]: { diurnal: Node.SUN, nocturnal: Node.JUPITER, participating: Node.SATURN },
 82→	[Element.EARTH]: { diurnal: Node.VENUS, nocturnal: Node.MOON, participating: Node.MARS },
 83→	[Element.AIR]: { diurnal: Node.SATURN, nocturnal: Node.MERCURY, participating: Node.JUPITER },
 84→	[Element.WATER]: { diurnal: Node.VENUS, nocturnal: Node.MARS, participating: Node.MOON },
 85→};
 86→
 87→const ptolemaicLillyTriplicityData: TriplicityData = {
 88→	[Element.FIRE]: { diurnal: Node.SUN, nocturnal: Node.JUPITER, participating: null },
 89→	[Element.EARTH]: { diurnal: Node.VENUS, nocturnal: Node.MOON, participating: null },
 90→	[Element.AIR]: { diurnal: Node.SATURN, nocturnal: Node.MERCURY, participating: null },
