  1→import { useMemo, FC, ReactNode } from 'react';
  2→import { Node, Zodiac, Element, Mode, standardNodes, NodeType, nodeTypes, mainAngles } from './astroDefs';
  3→import { nodeSymbols, nodeShortName, nodePreferredName } from './astroGraphics.ts';
  4→import NodePositions from './nodePositions.ts'
  5→import { isNodeAboveHorizon, isNodeEastern } from './chartAnalysis.ts'
  6→import { useSettingsStore } from './settingsStore.ts'
  7→import { NodesToConsider } from './settingsDefs.ts'
  8→import { renderString } from './renderPrimitives.tsx'
  9→
 10→type HemispheresChartProps = {
 11→	zodiacPositions: ZodiacPositions,
 12→}
 13→
 14→function capitalize(sentence: string): string {
 15→	return String(sentence).charAt(0).toUpperCase() + String(sentence).slice(1);
 16→}
 17→
 18→function createEmphasisString(verticalDiff: number, horizontalDiff: number, nNodes: number) {
 19→	// vertical diff is above - below, horizontal diff is east - west
 20→	
 21→	const verticalOrientation = verticalDiff === 0 ? 0 : verticalDiff > 0 ? 1 : -1;
 22→	const horizontalOrientation = horizontalDiff === 0 ? 0 : horizontalDiff > 0 ? 1 : -1;
 23→	const verticalDiffAbs = verticalOrientation > 0 ? verticalDiff : -verticalDiff;
 24→	const horizontalDiffAbs = horizontalOrientation > 0 ? horizontalDiff : -horizontalDiff;
 25→	
 26→	// translating the old parameters from 10 to n. in terms of diffAbs/total
 27→	// starts at nth. slight from 0.2. normal from 0.4. strong from 0.6
 28→	
 29→	// considering we're working with 10 standard planets. nth if equal, slight if 2 (4 vs 6), av if 4 (3 vs 7), strong if 6/8/10 (0,1,2 vs 8,9,10)
 30→	const strengthsPerDiff: (number|null)[] = [0, null, 1, null, 2, null, 3, null, 3, null, 3];
 31→	const strengthsPerRelDiff = (diffRel: number) => {
 32→		if (diffRel >= 0.6) { return 3; }
 33→		else if (diffRel >= 0.4) { return 2; }
 34→		else if (diffRel >= 0.2) { return 1; }
 35→		else { return 0; }
 36→	};
 37→	const verticalStrength = strengthsPerRelDiff(verticalDiffAbs/nNodes);
 38→	const horizontalStrength = strengthsPerRelDiff(horizontalDiffAbs/nNodes);
 39→	
 40→	const strengthModifiers: (string|null)[] = [null, "slight ", "", "strong "];
 41→	const strengthModifiersAdj: (string|null)[] = [null, "slighty ", "", "strongly "];
 42→	const verticalModifier = strengthModifiers[verticalStrength];
 43→	const horizontalModifier = strengthModifiers[horizontalStrength];
 44→	const horizontalModifierAdj = strengthModifiersAdj[horizontalStrength];
 45→	
 46→	//painful logic to try to make things stay within 1 lines
 47→	const horizontalStringUsesModifier = horizontalStrength === 1 || horizontalStrength === 3;
 48→	const verticalStringUsesModifier = verticalStrength === 1 || verticalStrength === 3;
