101→		throw new Error(`getTriplicityRole is only valid for planets and luminaries, got: ${node}`);
102→	}
103→
104→	const sign = zodiacPositions.getSignOfNode(node);
105→	
106→	if (sign === Zodiac.OPHIUCHUS) {
107→		return null;
108→	}
109→	
110→	const elem = zodiacElement[sign];
111→	const triplicityData = triplicityDataByMode[triplicityMode];
112→	const rulers = triplicityData[elem];
113→
114→	if (getChartSect(zodiacPositions) === Sect.DIURNAL) {
115→		if (rulers.diurnal === node) {
116→			return TriplicityRole.DIURNAL;
117→		}
118→	} else {
119→		if (rulers.nocturnal === node) {
120→			return TriplicityRole.NOCTURNAL;
121→		}
122→	}
123→	if (rulers.participating === node) {
124→		return TriplicityRole.PARTICIPATING;
125→	}
126→
127→	return null;
128→}
