// FACES (DECANS)
// ============================================================================

// Each sign divided into three 10° faces; array is [0-10°, 10-20°, 20-30°]
type FaceData = Record<Zodiac, [Node, Node, Node]>;

const chaldeanPtolemaicFaceData: Partial<FaceData> = {
