	}

	const listNodes = (nodes: Node[], forceText: boolean): ReactNode => {
		return (
			<>
			{nodes.map((node, i) => {
				return <span key={node}>
					{forceText || showNodeLabels ? renderSmallcapsString(node) : renderNode(node)}
					{(forceText || showNodeLabels) && (i < nodes.length - 1)
					&& <span style={{fontSize: textSize}}>, </span>
					}
				</span>;
			})}
			</>
		);
	}

	return {
		showNodeLabels,
		textSize,
		nodeElements,
		nodeModes,
		nodesByElement,
		nodesByMode,
		validSocialPlanets,
		validMainAngles,
		validLuminaries,
		allPlanets,
		discardedNodes,
		elementBarChart,
		modeBarChart,
		dominanceString,
		smallNodeDisplay,
		listNodes,
		renderTitle,
		renderElement,
		renderMode,
		zodiacPositions,
	};
};

