					]
				))}
			</div>

			<hr className="opacity-50 my-2"/>

			<div className="grid overflow-hidden bg-theme-bg w-full my-4" style={{ gridTemplateColumns: 'auto 1fr' }}>
				{Array.from(nodesByMode.entries()).map(([elem, nodes], index) => (
					[
						<div
							key={`label-${index}`}
