						{renderString("No dominant element or mode.")}
					</div>
				);
			} else {
				return (
					<div>
						{renderSmallcapsString(dominantMode)}
						{renderString(" mode dominant. No dominant element.")}
					</div>
				);
			}
		} else {
			if ( dominantMode === null ){
				return (
					<div>
						{renderSmallcapsString(dominantElement)}
