	const listNodes = (nodes: Node[], forceText: boolean): ReactNode => {
		return (
			<>
			{nodes.map((node, i) => {
				return <span key={node}>
					{forceText || showNodeLabels ? renderSmallcapsString(node) : renderNode(node)}
					{(forceText || showNodeLabels) && (i < nodes.length - 1)
