  1→import { useMemo, FC } from 'react';
  2→import { Node, mainAngles, NodeType, nodeTypes, zodiacElement, zodiacMode, standardNodes, Sect, nodeDependsOnLocation, irregularZodiacModes } from './astroDefs';
  3→import { nodeAverageSpeed } from './astroData';
  4→import { DignityMode, HouseAngularityMode, HamburgSchoolMode, Theme } from './settingsDefs';
  5→import { RulershipGraph, getFinalDispositorsOfChain } from './rulershipGraph';
  6→import { Aspect, filterAspectsByNode, getAspectsSummaryData } from './aspects';
  7→import { getChartSect, getChartRuler, getHouseAngularities, getAngleProximity, isInSect, getFixedStarsWithinLongitude } from './chartAnalysis';
  8→import { getEclipticLongitudeSpeed } from './astronomyUtil';
  9→import { getDignityState, getBoundLord, getFaceLord, getTriplicityRole, type DignityState, Dignity } from './dignities';
 10→import { formatAngle } from './util';
 11→import {
 12→	renderTitle,
 13→	renderString,
 14→	renderSmallcapsString,
 15→	renderSign,
 16→	renderNode,
 17→	renderElement,
 18→	renderMode,
 19→	renderArrow,
 20→	NodeSelectorButton,
 21→	renderDispositorChain,
 22→	renderFinalDispositors,
 23→	renderCommaSeparatedNodeList
 24→} from './renderPrimitives';
 25→import { nodeImages, nodeSymbols } from './astroGraphics.ts'
 26→import { useSettingsStore } from './settingsStore.ts'
 27→import ZodiacPositions from './zodiacPositions';
 28→
 29→// Opinionated thresholds
 30→const ANGLE_PROXIMITY_THRESHOLD_DEG = 10; // degrees - show "near angle" info within this distance
 31→					
 32→type PlanetPanelProps = {
 33→	zodiacPositions: ZodiacPositions;
 34→	rulershipGraph: RulershipGraph;
 35→	aspects: Map<Aspect, Aspect[]>;
 36→	date: Date;
 37→	selectedNode: Node;
 38→	isHighlighted: boolean;
 39→	cycleToNode: (node: Node) => void;
 40→	highlightSelected: () => void;
 41→};
 42→
 43→const PlanetPanel: FC<PlanetPanelProps> = ({
 44→	zodiacPositions,
 45→	rulershipGraph,
 46→	aspects,
 47→	date,
 48→	selectedNode,
 49→	isHighlighted,
 50→	cycleToNode,
 51→	highlightSelected,
 52→}) => {
 53→	
 54→	const dignityMode = useSettingsStore(s => s.dignityMode);
 55→	const houseAngularityMode = useSettingsStore(s => s.houseAngularityMode);
 56→	const hamburgSchoolMode = useSettingsStore(s => s.hamburgSchoolMode);
 57→	
 58→	// locally unused, render dependency
 59→	// ( = these lines here to force rerender if these values change)
 60→	// ( this is an extremely normal react pattern, but I'll keep it here until I stop feeling uneasy about not mentioning it anywhere)
 61→	const showNodeLabels = useSettingsStore(s => s.showNodeLabels);
 62→	const showSymbolLabels = useSettingsStore(s => s.showSymbolLabels);
 63→	const showSignsInDispositorChains = useSettingsStore(s => s.showSignsInDispositorChains);
 64→	
 65→	const useFixedStars = useSettingsStore(s => s.useFixedStars);
 66→	const fixedStarMaximumDistance = useSettingsStore(s => s.fixedStarMaximumDistance);
 67→	
 68→	const useExtendedDignities = useSettingsStore(s => s.useExtendedDignities);
 69→	const triplicityMode = useSettingsStore(s => s.triplicityMode);
 70→	const faceMode = useSettingsStore(s => s.faceMode);
 71→	const boundsMode = useSettingsStore(s => s.boundsMode);
 72→	const stationarySpeedFractionThreshold = useSettingsStore(s => s.stationarySpeedPercentageThreshold)/100;
 73→	
 74→	const selectedNodes = useSettingsStore(s => s.selectedNodes);
 75→	
 76→	const theme = useSettingsStore(s => s.theme);
 77→	const isDarkTheme = theme === Theme.DARK;
 78→	
 79→	const hasSurfacePosition = zodiacPositions.hasSurfacePosition();
 80→	const chartRuler = useMemo(
 81→		() => getChartRuler(zodiacPositions, dignityMode),
 82→		[zodiacPositions, dignityMode]
 83→	);
 84→
 85→	const isStandardNode = standardNodes.includes(selectedNode);
 86→
 87→	// Build ordered list of nodes by longitude for arrow navigation
 88→	const orderedNodes = useMemo(() => {
 89→		const nodes = Array.from(selectedNodes).filter(node => {
 90→			// Exclude nodes that depend on location if no surface position
 91→			return hasSurfacePosition || !nodeDependsOnLocation[node];
 92→		});
 93→		return nodes.sort((a, b) => {
 94→			const lonA = zodiacPositions.getNodePosition(a);
 95→			const lonB = zodiacPositions.getNodePosition(b);
 96→			return lonB - lonA;
 97→		});
 98→	}, [selectedNodes, zodiacPositions, hasSurfacePosition]);
 99→
100→	const handlePrevNode = () => {
101→		const currentIndex = orderedNodes.indexOf(selectedNode);
102→		const prevIndex = (currentIndex - 1 + orderedNodes.length) % orderedNodes.length;
103→		cycleToNode(orderedNodes[prevIndex]);
104→	};
105→
106→	const handleNextNode = () => {
107→		const currentIndex = orderedNodes.indexOf(selectedNode);
108→		const nextIndex = (currentIndex + 1) % orderedNodes.length;
109→		cycleToNode(orderedNodes[nextIndex]);
110→	};
111→
112→	// Get sign and position for selected node
113→	const nodeSign = zodiacPositions.getSignOfNode(selectedNode);
114→	const positionInSign = zodiacPositions.getNodePositionWithinSign(selectedNode);
115→	const formattedPosition = formatAngle(positionInSign);
116→
117→	const faceLord = irregularZodiacModes.includes(zodiacPositions.zodiacMode) ? null : getFaceLord(selectedNode, zodiacPositions, faceMode);
118→	const boundLord = irregularZodiacModes.includes(zodiacPositions.zodiacMode) ? null : getBoundLord(selectedNode, zodiacPositions, boundsMode);
119→
120→	// Get house placement (if location defined)
121→	// TODO whether this is defined is a bit more complicated
122→	const houseNumber = hasSurfacePosition
123→		? zodiacPositions.getHouseOfNode(selectedNode)
124→		: null;
125→
126→	// Get house angularity
127→	const houseAngularities = hasSurfacePosition
128→		? getHouseAngularities(zodiacPositions, houseAngularityMode)
129→		: null;
130→	const angularity = houseNumber && houseAngularities
131→		? houseAngularities[houseNumber - 1]
132→		: null;
133→
134→	// 2.1 Dignity
135→	const dignityState = getDignityState(selectedNode, zodiacPositions, dignityMode);
136→	
137→	const triplicityRole = (hasSurfacePosition && standardNodes.includes(selectedNode)) ? getTriplicityRole(selectedNode, zodiacPositions, triplicityMode) : null;
138→
139→	// 2.2 Speed & Retrograde
140→	const { formattedSpeedDegPerDay, isStationary, isRetrograde } = useMemo(() => {
141→		if (nodeTypes[selectedNode] === NodeType.POINT) {
142→			return { formattedSpeedDegPerDay: null, isStationary: null, isRetrograde: null};
143→		}
144→		const speedRadPerDay = getEclipticLongitudeSpeed(selectedNode, date, hamburgSchoolMode);
145→		const isStationary = Math.abs(speedRadPerDay) < nodeAverageSpeed[selectedNode]*stationarySpeedFractionThreshold;
146→		const isRetrograde = !isStationary && speedRadPerDay < 0;
147→		const formattedSpeedDegPerDay = formatAngle(Math.abs(speedRadPerDay), Math.abs(speedRadPerDay)<Math.PI/180);
148→		return {formattedSpeedDegPerDay, isStationary, isRetrograde};
149→	}, [selectedNode, date, hamburgSchoolMode])
150→
151→	const nearbyFixedStars = useMemo(() => {
152→		return getFixedStarsWithinLongitude(selectedNode, zodiacPositions, fixedStarMaximumDistance*Math.PI/180);
153→	}, [selectedNode, fixedStarMaximumDistance, zodiacPositions])
154→
155→	// 2.3 Angle proximity
156→	const angleProximity = useMemo(() => {
157→		if (!hasSurfacePosition) return null;
158→		return getAngleProximity(selectedNode, zodiacPositions);
159→	}, [selectedNode, zodiacPositions, hasSurfacePosition]);
160→
161→	const angleProximityDeg = angleProximity ? (angleProximity.distance * 180 / Math.PI) : null;
162→	const showAngleProximity = angleProximityDeg !== null && angleProximityDeg <= ANGLE_PROXIMITY_THRESHOLD_DEG && !mainAngles.includes(selectedNode);
163→
164→	// 2.4 Rulership chain
165→	const { isFinalDispositor, dispositorChain } = useMemo(() => {
166→		if (isStandardNode) {
167→			const isFinalDispositor = rulershipGraph.isFinalDispositor(selectedNode);
168→			const chain = rulershipGraph.getDispositorChain(selectedNode);
169→			return {
170→				isFinalDispositor,
171→				dispositorChain: isFinalDispositor ? getFinalDispositorsOfChain(chain) : chain,
172→			};
173→		} else {
174→			return {
175→				isFinalDispositor: false,
176→				dispositorChain: rulershipGraph.getDispositorChainForNonstandardNode(selectedNode, nodeSign)
177→			};
178→		}
179→	}, [selectedNode, rulershipGraph]);
180→
181→	const ruledNodes = useMemo(() => {
182→		return isStandardNode ? rulershipGraph.getRuledNodes(selectedNode, false) : null;
183→	}, [selectedNode, rulershipGraph]);
184→
185→	const transitivelyRuledNodes = useMemo(() => {
186→		return isStandardNode ? rulershipGraph.getRuledNodes(selectedNode, true) : null;
187→	}, [selectedNode, rulershipGraph]);
188→
189→	// 2.5 Aspects summary
190→	const aspectsSummary = useMemo(() => {
191→		const filtered = filterAspectsByNode(aspects, selectedNode);
192→		const summary = getAspectsSummaryData(filtered);
193→		// Remove the selected node from the "in aspect with" list
194→		summary.nodes.delete(selectedNode);
195→		return summary;
196→	}, [aspects, selectedNode]);
197→
198→	// 2.6 Sect
199→	const { chartIsDiurnal, inSect } = useMemo(() => {
200→		if (!hasSurfacePosition) {return { chartIsDiurnal: null, inSect: null }};
201→		return {
202→			chartIsDiurnal: getChartSect(zodiacPositions) === Sect.DIURNAL,
203→			inSect: isInSect(selectedNode, zodiacPositions)
204→		};
205→	}, [selectedNode, zodiacPositions]);
206→
207→	const formatOrdinal = (n: number): string => {
208→		const suffixes = ["th", "st", "nd", "rd"];
209→		const v = n % 100;
210→		return n + (suffixes[(v - 20) % 10] || suffixes[v] || suffixes[0]);
211→	};
212→	
213→	const formatAngleProximity = (angleProximityInfo: AngleProximityInfo) => {
214→		const preposition = angleProximity.passed ? "past" : "before";
215→		const verbs: Partial<Record<Node, string[]>> = {
216→			[Node.ASCENDANT] : ["Rising", "Risen"],
217→			[Node.IMUM_COELI] : ["Anti-culminating", "Anti-culminated"],
218→			[Node.DESCENDANT] : ["Setting", "Set"],
219→			[Node.MIDHEAVEN] : ["Culminating", "Culminated"],
220→		}
221→		const verb = verbs[angleProximityInfo.closestAngle][angleProximityInfo.passed ? 1 : 0];
222→		return (
223→			<div>
224→				{renderString(verb)}
225→				{renderString(` (${angleProximityDeg!.toFixed(1)}° ${preposition} `)}
226→				{renderNode(angleProximity.closestAngle, { forceText: true })}
227→				{renderString(`).`)}
228→			</div>
229→		);
230→	};
231→	
232→	const renderFixedStarSummaryString = (nearbyFixedStars: Map<string, number>) => {
233→		const lastIdx = nearbyFixedStars.size-1;
234→		return (<span className="block pl-3 -indent-3 text-wrap">
235→			{renderString(lastIdx === 0 ? "Fixed star conjunction: " : "Fixed star conjunctions: ")}
236→			{Array.from(nearbyFixedStars.entries()).map(([starName, orb], index) => {
237→				return (<span key={index}>
238→					<span className="text-nowrap pl-1">
239→						{renderSmallcapsString(starName)}
240→						{renderString(` (Δ${formatAngle(orb)})`)}
241→					</span>
242→					{renderString(index === lastIdx ? "." : ", ")}
243→				</span>);
244→			})}
245→		</span>);
246→	};
247→	
248→	const nodeGraphicSVG = () => {
249→		const planetImageWidth = 115;
250→		const largeSymbolWidth = 60;
251→		const padding = 5;
252→		
253→		const sunScaling = 10/9; // measured from images to match outer edges
254→		const sunD = planetImageWidth*(1/2)*(1/sunScaling - 1);
255→		const saturnScaling = 2.43; // eyeballed
256→		const saturnD = planetImageWidth*(1/2)*(1/saturnScaling - 1);
257→		const imageTransform = selectedNode === Node.SUN ? (
258→				`scale(${sunScaling}, ${sunScaling}) translate(${sunD}, ${sunD})`
259→			) : selectedNode === Node.SATURN ? (
260→				`scale(${saturnScaling}, ${saturnScaling*1.05}) translate(${saturnD-4}, ${saturnD-4})` //very eyeballed!
261→			) : (
262→				""
263→			);
264→		return (
265→			<svg width={planetImageWidth+2*padding} height={planetImageWidth+2*padding} overflow={"visible"} className="">
266→				{(nodeImages[selectedNode] === undefined || standardNodes.includes(selectedNode)) &&
267→					<circle cx="50%" cy="50%" r={planetImageWidth/2+padding} fill="url(#outerShadow)" opacity="0.4"/>
268→				}
269→				<circle cx="50%" cy="50%" r={planetImageWidth*(0.5-0.01)} fill="var(--color-bg)"/>
270→				{nodeImages[selectedNode] !== undefined ? (<>
271→					<image
272→						key={0}
273→						x={padding}
274→						y={padding}
275→						href={nodeImages[selectedNode]}
276→						width={planetImageWidth}
277→						height={planetImageWidth}
278→						opacity={1}
279→						filter={isDarkTheme ? "" : "invert(1) var(--icon-filter)"}
280→						transform={imageTransform}
281→					/>
282→					<circle cx="50%" cy="50%" r={planetImageWidth/2} fill="url(#innerShadow)" filter="url(#boost-alpha)" opacity="1"/>
283→				</>) : (<>
284→					<circle cx="50%" cy="50%" r={planetImageWidth*0.50} stroke="var(--color-text)" opacity="0.5" fill="none"/>
285→					<circle cx="50%" cy="50%" r={planetImageWidth*0.45} stroke="var(--color-text)" opacity="0.5" fill="none"/>
286→					<circle cx="50%" cy="50%" r={planetImageWidth*0.40} stroke="var(--color-text)" opacity="0.5"
287→						fill={nodeTypes[selectedNode] === NodeType.POINT ? "none" : "var(--color-text)"}/>
288→				</>)}
289→				<image
290→					key={2}
291→					x={padding}
292→					y={padding}
293→					href={nodeSymbols[selectedNode]}
294→					width={largeSymbolWidth}
295→					height={largeSymbolWidth}
296→					filter={"var(--icon-filter) url(#glow)"}
297→					transform={`translate(${(planetImageWidth-largeSymbolWidth)/2},${(planetImageWidth-largeSymbolWidth)/2})`}
298→				/>
299→				<defs>
300→					<filter id="glow" x="-200%" y="-200%" width="400%" height="400%">
301→						<feDropShadow dx="0" dy="0" stdDeviation="2.5" floodColor="var(--color-text)"/>
302→						<feDropShadow dx="0" dy="0" stdDeviation="2.5" floodColor="var(--color-text)"/>
303→					</filter>
304→					<filter id="boost-alpha">
305→						<feComponentTransfer>
306→							<feFuncA type="table" tableValues="0 0.4 0.7 0.8 0.9"/>
307→						</feComponentTransfer>
308→					</filter>
309→					<radialGradient id="outerShadow" cx="50%" cy="50%" r="50%" fx="50%" fy="50%">
310→						<stop offset="89%" stopColor="var(--color-text)"/>
311→						<stop offset="100%" stopColor="var(--color-bg)"/>
312→					</radialGradient>
313→					<radialGradient id="innerShadow" cx="50%" cy="50%" r="50%" fx="50%" fy="50%">
314→						<stop offset="0%" stopColor="var(--color-bg)"/>
315→						<stop offset="100%" stopColor="var(--color-bg)" stopOpacity="0"/>
316→					</radialGradient>
317→				</defs>
318→			</svg>
319→		);
320→	}
321→	
322→	const renderRuledNodes = (ruledNodes: Node[], transitivelyRuledNodes: Node[]) => {
323→		if (ruledNodes.length === 0){
324→			return renderString("Not ruling any planet or luminary.");
325→		}
326→		
327→		const rulesAllNodes = ruledNodes.length === standardNodes.length - 1;
328→		const transitivelyRulesAllNodes = transitivelyRuledNodes.length === standardNodes.length - 1;
329→		const transitivelyRulesAnyNodes = transitivelyRuledNodes.length > ruledNodes.length ;
330→		const exclusivelyTransitivelyRuledNodes = transitivelyRulesAnyNodes ? transitivelyRuledNodes.filter(n => !ruledNodes.includes(n)) : [];
331→		return (
332→			<span>
333→				{renderString("Rules ")}
334→				{rulesAllNodes && renderString("all planets & luminaries")}
335→				{!rulesAllNodes && renderCommaSeparatedNodeList(ruledNodes)}
336→				{renderString(".")}
337→				{transitivelyRulesAnyNodes && (<>
338→					{renderString(" Transitively rules ")}
339→					{transitivelyRulesAllNodes && renderString("all planets & luminaries")}
340→					{!transitivelyRulesAllNodes && renderCommaSeparatedNodeList(exclusivelyTransitivelyRuledNodes)}
341→					{renderString(".")}
342→				</>)}
343→			</span>
344→		);
345→	}
346→	
347→	const renderDignity = (dignityState: DignityState) => {
348→		const descriptiveStr = {
349→			[Dignity.DOMICILE] : "In Domicile",
350→			[Dignity.EXALTATION] : "Exalted",
351→			[Dignity.DETRIMENT] : "In Detriment",
352→			[Dignity.FALL] : "In Fall",
353→			[Dignity.PEREGRINE] : "Peregrine",
354→		}[dignityState.dignity];
355→		return (
356→			<div>
357→				{renderString(descriptiveStr)}
358→				{dignityState.degreeOffset !== undefined ? (
359→					renderString(` (${dignityState.degreeOffset > 0 ? "+" : ""}${dignityState.degreeOffset.toFixed(0)}° from exact)`)
360→				) : (
361→					null
362→				)}
363→			</div>
364→		);
365→	}
366→
367→	return (
368→		<div className="text-theme-text p-4" style={{ width: 330 }}>
369→			{/* Planet Header with Navigation */}
370→			<div className="flex items-center justify-between mb-2">
371→				<button
372→					className="bg-transparent border-none text-theme-text cursor-pointer p-1 text-xl hover:opacity-70"
373→					onClick={handlePrevNode}
374→					title="Previous planet"
375→				>
376→					◀
377→				</button>
378→				<div className="text-center">
379→					{renderNode(selectedNode, { forceText: true })}
380→				</div>
381→				<button
382→					className="bg-transparent border-none text-theme-text cursor-pointer p-1 text-xl hover:opacity-70"
383→					onClick={handleNextNode}
384→					title="Next planet"
385→				>
386→					▶
387→				</button>
388→			</div>
389→
390→			<hr className="opacity-50 my-2" />
391→			
392→			<div className="flex gap-5">
393→				{nodeGraphicSVG()}
394→				{/* POSITION / SIGN, POSITION WITHIN SIGN */}
395→				<div className="text-right flex-grow">
396→					
397→					{/* Sign and Position */}
398→					<div className="mt-2">
399→						{renderSign(nodeSign)}
400→						{renderString(" · ")}
401→						{renderSmallcapsString(formattedPosition)}
402→					</div>
403→				
404→					{/* House, house angularity */}
405→					{houseNumber && (
406→						<div>
407→							{renderString(`${formatOrdinal(houseNumber)} House`)}
408→							{angularity && (
409→								<>
410→									{renderString(" · ")}
411→									{renderString(angularity)}
412→								</>
413→							)}
414→						</div>
415→					)}
416→					
417→					{/* Chart ruler */}
418→					{selectedNode === chartRuler && (<div className="underline">{renderString("Chart Ruler")}</div>)}
419→					
420→					{/* Dignity */}
421→					{dignityState && renderDignity(dignityState)}
422→					
423→					{useExtendedDignities && (triplicityRole !== null) && (
424→						<div>
425→							{renderString(`Triplicity Ruler (${triplicityRole})`)}
426→						</div>
427→					)}
428→
429→					{/* Speed / Retrograde */}
430→					{formattedSpeedDegPerDay !== null && (
431→						<div>
432→							{isStationary ? (
433→								renderString("Stationary")
434→							) : isRetrograde ? (
435→								renderString("Retrograde")
436→							) : (
437→								renderString("Direct")
438→							)}
439→							{renderString(` (${formattedSpeedDegPerDay} / day)`)}
440→						</div>
441→					)}
442→
443→					{/* Sect */}
444→					{inSect !== null && (
445→						<div>
446→							{renderString(inSect ? "In Sect" : "Out of Sect")}
447→							{false && renderString(chartIsDiurnal ? " (Diurnal Chart)" : " (Nocturnal Chart)")}
448→						</div>
449→					)}
450→				
451→				</div>
452→			</div>
453→					
454→			{/* Extended dignities (face and bound, not triplicity)*/}
455→			{useExtendedDignities && ( faceLord === boundLord ? (
456→				<div className="text-wrap">
457→					{renderString("In the face & bound of ")}
458→					{renderNode(faceLord, { withArticle: true })}
459→					{renderString(".")}
460→				</div>
461→			) : (
462→				<div>
463→					{renderString("In the face of ")}
464→					{renderNode(faceLord, { withArticle: true })}
465→					{renderString(" & the bound of ")}
466→					{renderNode(boundLord, { withArticle: true })}
467→					{renderString(".")}
468→				</div>
469→			))}
470→					
471→			{/* Angle Proximity */}
472→			{showAngleProximity && angleProximity && formatAngleProximity(angleProximity)}
473→
474→			{/* Aspects Summary */}
475→			{aspectsSummary.nAspects > 0 ? (
476→				<>
477→					{renderString(`In ${aspectsSummary.nAspects} aspect${aspectsSummary.nAspects !== 1 ? "s" : ""}`)}
478→					{aspectsSummary.nConfigurations > 0 && (
479→						renderString(` (${aspectsSummary.nConfigurations} configuration${aspectsSummary.nConfigurations !== 1 ? "s" : ""})`)
480→					)}
481→					{renderString(", with ")}
482→					{Array.from(aspectsSummary.nodes).map((node, i) => (
483→						<span key={i}>
484→							{i > 0 && renderString(", ")}
485→							{renderNode(node)}
486→						</span>
487→					))}
488→					{renderString(". ")}
489→					{!isHighlighted && (
490→						<button
491→							className="bg-transparent border-none text-theme-text underline cursor-pointer p-0 m-0 font-[inherit] inline hover:opacity-70"
492→							onClick={highlightSelected}
493→						>
494→							{renderString("Highlight aspects.")}
495→						</button>
496→					)}
497→				</>
498→			) : (
499→				renderString("Not in any aspects.")
500→			)}
501→			
502→			{useFixedStars && nearbyFixedStars.size > 0 && (
503→				<div>
504→					{renderFixedStarSummaryString(nearbyFixedStars)}
505→				</div>
506→			)}
507→
508→			{/* Rulership Chain */}
509→			{dispositorChain && (
510→				<>
511→					<hr className="opacity-50 mt-4" />
512→					<span className="absolute -translate-y-4 translate-x-2 bg-theme-bg px-1">
513→						{renderSmallcapsString("Dispositorship")}
514→					</span>
515→					<div>
516→						<div className="mt-2">
517→							{isFinalDispositor ? (
518→								renderFinalDispositors(dispositorChain, true)
519→							) : (
520→								renderDispositorChain(dispositorChain, true)
521→							)}
522→						</div>
523→						{isStandardNode && renderRuledNodes(ruledNodes, transitivelyRuledNodes)}
524→					</div>
525→				</>
526→			)}
527→		</div>
528→	);
529→};
530→
531→export default PlanetPanel;
