 28→function computeAxisAnglesFromSurface(date: Date, surfacePosition: SurfacePosition): AxisAngles {
 29→	const { asc, mc } = computeAllSignificantPoints(date, surfacePosition);
 30→	const ascLon = getTodayEclipticLongitudeFromEQJ(date, asc);
 31→	const mcLon = getTodayEclipticLongitudeFromEQJ(date, mc);
 32→	return {
 33→		asc: normalizeAngleRad(ascLon),
 34→		dsc: normalizeAngleRad(ascLon + Math.PI),
 35→		mc: normalizeAngleRad(mcLon),
 36→		ic: normalizeAngleRad(mcLon + Math.PI)
 37→	};
 38→}
 39→
 40→function computeWholeSignCuspPositions(
 41→	date: Date,
 42→	surfacePosition: SurfacePosition,
 43→	signPositions: Map<Zodiac, number>
 44→) {
 45→	const angles = computeAxisAnglesFromSurface(date, surfacePosition);
 46→	const longitudes = Array.from(signPositions.values());
 47→	let index = longitudes.findIndex((lon) => lon > angles.asc);
 48→	if (index === -1 || index === 0) {
 49→		index = longitudes.length - 1;
 50→	} else {
 51→		index = index - 1;
 52→	}
 53→
 54→	return Array.from({length: longitudes.length}).map((_,i) => longitudes[(index+i)%longitudes.length]);
 55→}
