 57→function computeEqualHousesCuspPositions(date: Date, surfacePosition: SurfacePosition){
 58→	const angles = computeAxisAnglesFromSurface(date, surfacePosition);
 59→	return [
 60→		angles.asc,
 61→		angles.asc + Math.PI/6,
 62→		angles.asc + 2*Math.PI/6,
 63→		angles.asc + 3*Math.PI/6,
 64→		angles.asc + 4*Math.PI/6,
 65→		angles.asc + 5*Math.PI/6,
 66→		angles.asc + 6*Math.PI/6, //dsc
 67→		angles.asc + 7*Math.PI/6,
 68→		angles.asc + 8*Math.PI/6,
 69→		angles.asc + 9*Math.PI/6,
 70→		angles.asc + 10*Math.PI/6,
 71→		angles.asc + 11*Math.PI/6,
 72→	];
 73→}
 74→
 75→function computePorphyryCuspPositions(date: Date, surfacePosition: SurfacePosition){
 76→	const angles = computeAxisAnglesFromSurface(date, surfacePosition);
 77→	return [
 78→		angles.asc,
 79→		interpolateAngles(1/3, angles.asc, angles.ic),
 80→		interpolateAngles(2/3, angles.asc, angles.ic),
 81→		angles.ic,
 82→		interpolateAngles(1/3, angles.ic, angles.dsc),
 83→		interpolateAngles(2/3, angles.ic, angles.dsc),
 84→		angles.dsc,
 85→		interpolateAngles(1/3, angles.dsc, angles.mc),
 86→		interpolateAngles(2/3, angles.dsc, angles.mc),
 87→		angles.mc,
 88→		interpolateAngles(1/3, angles.mc, angles.asc),
 89→		interpolateAngles(2/3, angles.mc, angles.asc),
 90→	];
 91→}
 92→
 93→function computeEqualHousesVehlowCuspPositions(date: Date, surfacePosition: SurfacePosition){
 94→	const angles = computeAxisAnglesFromSurface(date, surfacePosition);
 95→	return [
 96→		angles.asc + (-1)*Math.PI/12,
 97→		angles.asc + 1*Math.PI/12,
 98→		angles.asc + 3*Math.PI/12,
 99→		angles.asc + 5*Math.PI/12,
100→		angles.asc + 7*Math.PI/12,
101→		angles.asc + 9*Math.PI/12,
102→		angles.asc + 11*Math.PI/12,
103→		angles.asc + 13*Math.PI/12,
104→		angles.asc + 15*Math.PI/12,
105→		angles.asc + 17*Math.PI/12,
106→		angles.asc + 19*Math.PI/12,
