118→function advanceAlongCircle(p: vec3, circle: vec3, angle: number): vec3 {
119→	const q = normalize(cross(circle, p));
120→	return normalize({
121→		x: p.x*Math.cos(angle) + q.x*Math.sin(angle),
122→		y: p.y*Math.cos(angle) + q.y*Math.sin(angle),
123→		z: p.z*Math.cos(angle) + q.z*Math.sin(angle)
124→	});
125→}
126→
127→function twelvePoints(circle: vec3, p: vec3): vec3[] {
128→	return Array.from({length:12}, (_,i) => advanceAlongCircle(p, circle, i*Math.PI/6));
129→}
130→
131→function projectPoint(q: vec3, circle: vec3, center: vec3): vec3 {
132→	const qcCircle = normalize(cross(q, center));
133→	const intersection = normalize(cross(qcCircle, circle));
134→	return intersection;
135→}
136→
137→function projectPoints(qs: vec3[], circle: vec3, center: vec3): vec3[] {
138→	return qs.map(q => projectPoint(q, circle, center));
139→}
