141→function computeEclipticAngle(p: vec3): number {
142→	const rot = Rotation_EQJ_ECL();
143→	const v = RotateVector(rot, toAstronomyVector(p));
144→	const alpha = Math.atan2(v.y, v.x);
145→	return normalizeAngleRad(alpha);
146→}
