152→function cycleToStart(angles: number[], start: number): number[] {
153→	const sorted = [...angles].sort((a, b) => a - b);
154→	const i = sorted.findIndex((angle, idx) => angle < start && start < sorted[idx + 1]);
155→	return i === -1 ? sorted : [...sorted.slice(i), ...sorted.slice(0, i)];
156→}
