158→function computeSpaceBasedSystemCuspPositions(
159→	date: Date,
160→	surfacePosition: SurfacePosition,
161→	startingCircle: vec3,
162→	startingPoint: vec3,
163→	projectionCenter: vec3
164→): number[] {
165→	const {ecliptic, asc} = computeAllSignificantPoints(date, surfacePosition);
166→	const kpts = twelvePoints(startingCircle, startingPoint);
167→	const epts = projectPoints(kpts, ecliptic, projectionCenter);
168→	const angles = computeEclipticAngles(epts);
169→	return cycleToStart(angles, computeEclipticAngle(asc));
170→}
