212→// time-based
213→function eclipticLongitudeToRAAndDeclination(longitude: number, axialTilt: number){
214→	// formula transparent, makes sense
215→	const RA = Math.atan2(Math.sin(longitude)*Math.cos(axialTilt), Math.cos(longitude));
216→	const declination = Math.asin(Math.sin(axialTilt)*Math.sin(longitude));
217→	return {RA, declination}
218→}
219→
220→// returns radians as a unit of time (2pi = 24hr)
221→function timeToHorizon(pointRA: number, pointDeclination: number, RAMC: number, observerLatitude: number): number | null{
222→
223→	const cosAD = -Math.tan(observerLatitude * Math.PI / 180)*Math.tan(pointDeclination);
224→	if ( Math.abs(cosAD) > 1 ) {
225→		return null;
226→	}
227→	const TAU = 2*Math.PI;
228→	const AD = Math.acos(cosAD); //hour angle btw observer (=MC=meridian) and (point-on-the-same-latitude-as-point)-on-the-horizon
229→	const H = RAMC - pointRA; // point H off the meridian (=observer)
230→	const adjH = ((H + AD)%TAU+TAU)%TAU - AD; // mod 2pi conjugated by -AD -> mod but maps to (-AD, TAU-AD)
231→	if (adjH <= AD) {
232→		return AD - adjH;
233→	} else {
234→		return TAU - AD - adjH;
235→	}
236→}
237→
238→// returns radians as a unit of time (2pi = 24hr)
239→function timeSinceHorizon(pointRA: number, pointDeclination: number, RAMC: number, observerLatitude: number): number | null{
240→
241→	const cosAD = -Math.tan(observerLatitude * Math.PI / 180)*Math.tan(pointDeclination);
242→	if ( Math.abs(cosAD) > 1 ) {
243→		return null;
244→	}
245→	const TAU = 2*Math.PI;
246→	const AD = Math.acos(cosAD); //hour angle btw observer (=MC=meridian) and (point-on-the-same-latitude-as-point)-on-the-horizon
247→	const H = RAMC - pointRA; // point H off the meridian (=observer)
248→	const adjH = ((H + AD)%TAU+TAU)%TAU - AD; // mod 2pi conjugated by -AD -> mod but maps to (-AD, TAU-AD)
249→	if (adjH <= AD) {
250→		return AD + adjH;
251→	} else {
252→		return adjH - AD;
253→	}
254→}
255→
256→// returns radians as a unit of time (2pi = 24hr)
257→function timeToMeridian(pointRA: number, RAMC: number): number{
258→	const H = RAMC - pointRA;
259→	return Math.PI-((H)%Math.PI+Math.PI)%Math.PI // pi - (h mod pi)
260→}
