262→export const MainAxisArc = {
263→	ASC_TO_MC: "Asc to MC",
264→	DSC_TO_MC: "Dsc to MC",
265→	ASC_TO_IC: "Asc to IC",
266→	DSC_TO_IC: "Dsc to IC",
267→} as const;
268→export type MainAxisArc = typeof MainAxisArc[keyof typeof MainAxisArc];
269→
270→function placidusCuspSearch(obsLatitude: number, axialTilt: number, eps: number, angles: AxisAngles, mode: MainAxisArc, c: number): number | null {
271→	const { asc, mc, dsc, ic } = angles;
272→	const { RA: RAMC } = eclipticLongitudeToRAAndDeclination(mc, axialTilt);
273→	const start = ([MainAxisArc.ASC_TO_IC, MainAxisArc.ASC_TO_MC] as MainAxisArc[]).includes(mode) ? asc : dsc;
274→	const end = ([MainAxisArc.ASC_TO_MC, MainAxisArc.DSC_TO_MC] as MainAxisArc[]).includes(mode) ? mc : ic;
275→	var x = interpolateShorterAngle(c, start, end);
276→	var y = x - 2*eps;
277→	function f(eclLon: number): number | null{
278→		const { RA, declination } = eclipticLongitudeToRAAndDeclination(eclLon, axialTilt);
279→		var tsh, tth, ttm, tsm;
280→		switch (mode){
281→			case MainAxisArc.ASC_TO_MC:
282→				tsh = timeSinceHorizon(RA, declination, RAMC, obsLatitude);
283→				if ( tsh === null ) { return null; }
284→				ttm = timeToMeridian(RA, RAMC);
285→				return (1-c)*tsh - c*ttm;
286→			case MainAxisArc.DSC_TO_MC:
287→				tth = timeToHorizon(RA, declination, RAMC, obsLatitude);
288→				if ( tth === null ) { return null; }
289→				tsm = Math.PI-timeToMeridian(RA, RAMC);
290→				return (1-c)*tth - c*tsm;
291→			case MainAxisArc.ASC_TO_IC:
292→				tth = timeToHorizon(RA, declination, RAMC, obsLatitude);
293→				if ( tth === null ) { return null; }
294→				tsm = Math.PI-timeToMeridian(RA, RAMC);
295→				return (1-c)*tth - c*tsm;
296→			case MainAxisArc.DSC_TO_IC:
297→				tsh = timeSinceHorizon(RA, declination, RAMC, obsLatitude);
298→				if ( tsh === null ) { return null; }
299→				ttm = timeToMeridian(RA, RAMC);
300→				return (1-c)*tsh - c*ttm;
301→		}
302→	}
303→	var fx = f(x);
304→	var fy = f(y);
305→	if (fx === null || fy === null) { return null; }
306→	var z = 0;
307→	var fz: number | null = 0;
308→	var counter = 0;
309→	const max_iter = 100;
310→	while ( Math.abs(x - y) > 1e-10 ) {
311→		z = y - fy*(x-y)/(fx-fy); // secant
312→		fz = f(z);
313→		counter++;
314→		if ( fz === null || counter >= max_iter ) { return null; }
315→		if ( Math.abs(fz) < 1e-10 ) {
316→			x = y;//exit
317→		} else if ( Math.abs(fx) > Math.abs(fy) ) {
318→			x = z;
319→			fx = fz;
320→		} else {
321→			y = z;
322→			fy = fz;
323→		}
324→	}
325→	return z;
326→}
