328→function computeAxialTilt(date: Date): number {
329→	// in radians
330→	const vecPole = new Vector(0, 0, 1, new AstroTime(date));
331→	const eclPole = Ecliptic(vecPole);
332→	const obliquity = Math.acos(eclPole.vec.z);
333→	return obliquity;
334→}
