336→function computePlacidusCuspPositions(date: Date, surfacePosition: SurfacePosition): number[] | null {
337→	const angles = computeAxisAnglesFromSurface(date, surfacePosition);
338→	// 12th cusp is the point along the ecliptic which is 1/3rd of the way, time-wise, from the ascendant to the mc
339→
340→	// note: some people claim asc is midpoint, timewise, btw asc-dsc. This would simplify calculations but it is false
341→	const axialTilt = computeAxialTilt(date);
342→	const eps = 0.01;
343→
344→	const houseCusps = [
345→		angles.asc,
346→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.ASC_TO_IC, 1/3),
347→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.ASC_TO_IC, 2/3),
348→		angles.ic,
349→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.DSC_TO_IC, 2/3),
350→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.DSC_TO_IC, 1/3),
351→		angles.dsc,
352→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.DSC_TO_MC, 1/3),
353→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.DSC_TO_MC, 2/3),
354→		angles.mc,
355→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.ASC_TO_MC, 2/3),
356→		placidusCuspSearch(surfacePosition.latitude, axialTilt, eps, angles, MainAxisArc.ASC_TO_MC, 1/3)
357→	];
358→
359→	const containsNull = houseCusps.some(cusp => cusp === null);
360→	return containsNull ? null : houseCusps as number[];
361→}
