363→function computeAscendantAndDescendant(date: Date, surfacePos: SurfacePosition): Map<Node, number> {
364→	const latitudeDeg = surfacePos.latitude;
365→	const longitudeDeg = surfacePos.longitude;
366→	const gstHours = SiderealTime(date);
367→	const lstHours = gstHours + longitudeDeg / 15.0;
368→	const lstHoursNorm = ((lstHours % 24) + 24) % 24;
369→	const theta = lstHoursNorm * Math.PI / 12
370→
371→	const epsRad = computeAxialTilt(date);
372→
373→	const phi = latitudeDeg * Math.PI/180;
374→
375→	const x = Math.cos(theta);
376→	const y = - (Math.sin(theta) * Math.cos(epsRad) + Math.tan(phi) * Math.sin(epsRad));
377→	const lambda = Math.atan2(x,y);
378→
379→	return new Map<Node, number>([
380→		[Node.ASCENDANT, normalizeAngleRad(lambda)],
381→		[Node.DESCENDANT, normalizeAngleRad(lambda + Math.PI)]
382→	]);
383→}
