385→function computeKochCuspPositions(date: Date, surfacePosition: SurfacePosition){
386→	const angles = computeAxisAnglesFromSurface(date, surfacePosition);
387→	//consider the time it took the current mc to arrive there from the horizon. 12th house is the 1/3rd point (time-wise)
388→
389→	// setup
390→	const axialTilt = computeAxialTilt(date);
391→	const { asc, mc, dsc, ic } = angles;
392→
393→	// how long did the current mc take to arrive from the horizon?
394→	const { RA: RAMC, declination: declinationMC } = eclipticLongitudeToRAAndDeclination(mc, axialTilt);
395→	const tshRadMC = timeSinceHorizon(RAMC, declinationMC, RAMC, surfacePosition.latitude);
396→	// how long will the current mc take to get to the horizon again?
397→	const tthRadMC = timeToHorizon(RAMC, declinationMC, RAMC, surfacePosition.latitude);
398→	// how long did the current ic take to arrive from the horizon?
399→	const { RA: RAIC, declination: declinationIC } = eclipticLongitudeToRAAndDeclination(ic, axialTilt);
400→	const tshRadIC = timeSinceHorizon(RAIC, declinationIC, RAMC, surfacePosition.latitude);
401→	// how long will the current ic take to get to the horizon again?
402→	const tthRadIC = timeToHorizon(RAIC, declinationIC, RAMC, surfacePosition.latitude);
403→
404→	if (
405→		tshRadMC === null ||
406→		tthRadMC === null ||
407→		tshRadIC === null ||
408→		tthRadIC === null
409→	){
410→		return null;
411→	}
412→
413→	// first quadrant
414→	const tshHoursMC = tshRadMC * 12 / Math.PI;
415→
416→	const date11th = new Date(date.getTime() - tshHoursMC*(2/3)*3600*1000)
417→	const date12th = new Date(date.getTime() - tshHoursMC*(1/3)*3600*1000)
418→	const cusp11 = computeAscendantAndDescendant(date11th, surfacePosition).get(Node.ASCENDANT)!;
419→	const cusp12 = computeAscendantAndDescendant(date12th, surfacePosition).get(Node.ASCENDANT)!;
420→
421→	// second quadrant
422→	const tthHoursMC = tthRadMC* 12 / Math.PI;
423→
424→	const date8th = new Date(date.getTime() + tthHoursMC*(1/3)*3600*1000)
425→	const date9th = new Date(date.getTime() + tthHoursMC*(2/3)*3600*1000)
426→	const cusp8 = computeAscendantAndDescendant(date8th, surfacePosition).get(Node.DESCENDANT)!;
427→	const cusp9 = computeAscendantAndDescendant(date9th, surfacePosition).get(Node.DESCENDANT)!;
428→
429→	// third quadrant
430→	const tshHoursIC = tshRadIC* 12 / Math.PI;
431→
432→	const date5th = new Date(date.getTime() - tshHoursIC*(2/3)*3600*1000)
433→	const date6th = new Date(date.getTime() - tshHoursIC*(1/3)*3600*1000)
434→	const cusp5 = computeAscendantAndDescendant(date5th, surfacePosition).get(Node.DESCENDANT)!;
435→	const cusp6 = computeAscendantAndDescendant(date6th, surfacePosition).get(Node.DESCENDANT)!;
436→
437→	// fourth quadrant
438→	const tthHoursIC = tthRadIC * 12 / Math.PI;
439→
440→	const date2nd = new Date(date.getTime() + tthHoursIC*(1/3)*3600*1000)
441→	const date3rd = new Date(date.getTime() + tthHoursIC*(2/3)*3600*1000)
442→	const cusp2 = computeAscendantAndDescendant(date2nd, surfacePosition).get(Node.ASCENDANT)!;
443→	const cusp3 = computeAscendantAndDescendant(date3rd, surfacePosition).get(Node.ASCENDANT)!;
444→
445→	return [asc, cusp2, cusp3, ic, cusp5, cusp6, dsc, cusp8, cusp9, mc, cusp11, cusp12];
446→}
