448→function computePolichPageCusp(c: number, p1: number, p2: number, tp1: number, tp2: number, axialTilt: number): number {
449→	const cuspDecl = Math.atan(c * tp1 + (1-c) * tp2);
450→	const cuspLongOpt1 = Math.asin(Math.sin(cuspDecl)/Math.sin(axialTilt));
451→	const cuspLongOpt2 = (cuspLongOpt1 > 0 ? Math.PI : -Math.PI) - cuspLongOpt1;
452→	if ( anglesLieInShortArc(p1, cuspLongOpt1, p2) ) {
453→		return cuspLongOpt1;
454→	} else {
455→		return cuspLongOpt2;
456→	}
457→}
