463→function computeTopocentricCuspPositions(date: Date, surfacePosition: SurfacePosition){
464→	const angles = computeAxisAnglesFromSurface(date, surfacePosition);
465→	// polich - page. Consider the "polar elevation" of the asc-mc, i.e. its geographic latitude
466→	// consider tangents, trisect interval, invert over the ecliptic.
467→
468→	const axialTilt = computeAxialTilt(date);
469→	const { asc, mc, dsc, ic } = angles;
470→
471→	const { declination: declinationMC } = eclipticLongitudeToRAAndDeclination(mc, axialTilt);
472→	const { declination: declinationASC } = eclipticLongitudeToRAAndDeclination(asc, axialTilt);
473→	const { declination: declinationIC } = eclipticLongitudeToRAAndDeclination(ic, axialTilt);
474→	const { declination: declinationDSC } = eclipticLongitudeToRAAndDeclination(dsc, axialTilt);
475→
476→	const tAsc = Math.tan(declinationASC);
477→	const tMc = Math.tan(declinationMC);
478→	const tDsc = Math.tan(declinationDSC);
479→	const tIc = Math.tan(declinationIC);
480→
481→	return [
482→		asc,
483→		computePolichPageCusp(2/3, asc, ic, tAsc, tIc, axialTilt),
484→		computePolichPageCusp(1/3, asc, ic, tAsc, tIc, axialTilt),
485→		ic,
486→		computePolichPageCusp(2/3, ic, dsc, tIc, tDsc, axialTilt),
487→		computePolichPageCusp(1/3, ic, dsc, tIc, tDsc, axialTilt),
488→		dsc,
489→		computePolichPageCusp(2/3, dsc, mc, tDsc, tMc, axialTilt),
490→		computePolichPageCusp(1/3, dsc, mc, tDsc, tMc, axialTilt),
491→		mc,
492→		computePolichPageCusp(2/3, mc, asc, tMc, tAsc, axialTilt),
493→		computePolichPageCusp(1/3, mc, asc, tMc, tAsc, axialTilt)
494→	]
495→}
