498→function computeHouseCuspPositions(
499→	date: Date,
500→	surfacePosition: SurfacePosition,
501→	houseSystem: HouseSystem,
502→	signPositions: Map<Zodiac, number>
503→): number[] | null {
504→	switch (houseSystem) {
505→		case HouseSystem.NO_HOUSES:
506→			return null;
507→		case HouseSystem.WHOLE_SIGN:
508→			return computeWholeSignCuspPositions(date, surfacePosition, signPositions);
509→		case HouseSystem.EQUAL_HOUSES:
510→			return computeEqualHousesCuspPositions(date, surfacePosition);
511→		case HouseSystem.PORPHYRY:
512→			return computePorphyryCuspPositions(date, surfacePosition);
513→		case HouseSystem.EQUAL_HOUSES_VEHLOW:
514→			return computeEqualHousesVehlowCuspPositions(date, surfacePosition);
515→		case HouseSystem.WHOLE_SIGN_ARIES:
516→			return computeWholeSignAriesCuspPositions(signPositions);
517→		case HouseSystem.KRUSINSKY:
518→			return computeKrusinskyCuspPositions(date, surfacePosition);
519→		case HouseSystem.REGIOMONTANUS:
520→			return computeRegiomontanusCuspPositions(date, surfacePosition);
521→		case HouseSystem.MERIDIAN:
522→			return computeMeridianCuspPositions(date, surfacePosition);
523→		case HouseSystem.MORINUS:
524→			return computeMorinusCuspPositions(date, surfacePosition);
525→		case HouseSystem.CAMPANUS:
526→			return computeCampanusCuspPositions(date, surfacePosition);
527→		case HouseSystem.ZENITH_HORIZONTAL:
528→			return computeZenithHorizontalCuspPositions(date, surfacePosition);
529→		case HouseSystem.PLACIDUS:
530→			return computePlacidusCuspPositions(date, surfacePosition);
531→		case HouseSystem.KOCH:
532→			return computeKochCuspPositions(date, surfacePosition);
533→		default:
534→			throw new Error("something wrong with house computation dispatch:", houseSystem);
535→	}
