620→	public getCuspPosition(i: number): number {
621→		if (i >= this._cuspPositions!.length || i < 0) {
622→			throw new Error("getCuspPosition called for invalid index");
623→		}
624→		return this._cuspPositions![i];
625→	}
626→
627→	public getHouseAtLongitude(lon: number): number {
628→		if (this._cuspPositions === null) {
629→			throw new Error("getHouseAtLongitude called but house cusps are undefined");
630→		}
631→		const houseLimits = this._cuspPositions.map(cusp => {
632→			if (this._housePresweep) {
633→				const limit = cusp - 5*Math.PI/180;
634→				return limit > 0 ? limit : limit + 2*Math.PI;
635→			} else {
636→				return cusp;
637→			}
638→		});
639→		for (let i = 0; i < houseLimits.length-1; i++){
640→			const houseStart = houseLimits[i];
641→			const houseEnd = houseLimits[i+1];
642→			if ( anglesLieInShortArc(houseStart, lon, houseEnd) ) {
643→				return i+1;
644→			}
645→		}
646→		return houseLimits.length;
647→	}
648→
649→	public areHouseCuspsWithinHouse(): boolean {
650→		if (!this._housePresweep || this._cuspPositions === null) {
651→			return true;
652→		}
653→		const cusps = this._cuspPositions;
654→		for (let i = 0; i < cusps.length; i++) {
655→			const next = cusps[(i + 1) % cusps.length];
656→			const current = cusps[i];
657→			let width = next - current;
658→			if (width < 0) { width += 2 * Math.PI; }
659→			if (width < 5 * Math.PI / 180) {
660→				return false;
661→			}
662→		}
663→		return true;
664→	}
665→}
666→
667→export default HouseCuspPositions;
