  1→import { useMemo, type FC } from 'react';
  2→import { Node, mainAngles, NodeType, nodeTypes, standardNodes, Sect, nodeDependsOnLocation } from './astroDefs';
  3→import { getNodeAverageSpeed } from './astroData';
  4→import { Theme } from './settingsDefs';
  5→import { RulershipGraph, getFinalDispositorsOfChain } from './rulershipGraph';
  6→import { Aspect, filterAspectsByNode, getAspectsSummaryData } from './aspects';
  7→import { getChartSect, getChartRuler, getHouseAngularities, getAngleProximity, isInSect, getFixedStarsWithinLongitude, getSignOfNode, getNodePositionWithinSign, getHouseOfNode, type AngleProximityInfo } from './chartAnalysis';
  8→import { getDignityState, getBoundLord, getFaceLord, getTriplicityRole, type DignityState, Dignity } from './dignities';
  9→import { formatAngle } from './util';
