 19→import { nodeImages, nodeSymbols } from './astroGraphics.ts'
 20→import { useSettingsStore } from './settingsStore.ts'
 21→import NodePositions from './nodePositions';
 22→import NodeVelocities from './nodeVelocities';
 23→import ZodiacSignPositions from './zodiacSignPositions';
 24→import FixedStarPositions from './fixedStarPositions';
 25→import HouseCuspPositions from './houseCuspPositions';
 26→
 27→// Opinionated thresholds
 28→const ANGLE_PROXIMITY_THRESHOLD_DEG = 10; // degrees - show "near angle" info within this distance
 29→					
 30→type PlanetPanelProps = {
 31→	nodePositions: NodePositions;
 32→	nodeVelocities: NodeVelocities;
 33→	zodiacSignPositions: ZodiacSignPositions;
 34→	fixedStarPositions: FixedStarPositions;
 35→	houseCuspPositions: HouseCuspPositions | null;
 36→	rulershipGraph: RulershipGraph;
 37→	aspects: Map<Aspect, Aspect[]>;
 38→	date: Date;
 39→	selectedNode: Node;
 40→	isHighlighted: boolean;
 41→	cycleToNode: (node: Node) => void;
 42→	highlightSelected: () => void;
 43→};
 44→
 45→const PlanetPanel: FC<PlanetPanelProps> = ({
 46→	nodePositions,
 47→	nodeVelocities,
 48→	zodiacSignPositions,
 49→	fixedStarPositions,
 50→	houseCuspPositions,
 51→	rulershipGraph,
 52→	aspects,
 53→	date,
 54→	selectedNode,
 55→	isHighlighted,
 56→	cycleToNode,
 57→	highlightSelected,
 58→}) => {
 59→	
 60→	const dignityMode = useSettingsStore(s => s.dignityMode);
 61→	const houseAngularityMode = useSettingsStore(s => s.houseAngularityMode);
 62→	const hamburgSchoolMode = useSettingsStore(s => s.hamburgSchoolMode);
 63→	
 64→	// locally unused, render dependency
 65→	// ( = these lines here to force rerender if these values change)
 66→	// ( this is an extremely normal react pattern, but I'll keep it here until I stop feeling uneasy about not mentioning it anywhere)
 67→	useSettingsStore(s => s.showNodeLabels);
 68→	useSettingsStore(s => s.showSymbolLabels);
 69→	useSettingsStore(s => s.showSignsInDispositorChains);
 70→	
 71→	const useFixedStars = useSettingsStore(s => s.useFixedStars);
 72→	const fixedStarMaximumDistance = useSettingsStore(s => s.fixedStarMaximumDistance);
 73→	
 74→	const useExtendedDignities = useSettingsStore(s => s.useExtendedDignities);
 75→	const triplicityMode = useSettingsStore(s => s.triplicityMode);
 76→	const faceMode = useSettingsStore(s => s.faceMode);
 77→	const boundsMode = useSettingsStore(s => s.boundsMode);
 78→	const lunarNodeMode = useSettingsStore(s => s.lunarNodeMode);
 79→	const stationarySpeedFractionThreshold = useSettingsStore(s => s.stationarySpeedPercentageThreshold)/100;
 80→	
 81→	const selectedNodes = useSettingsStore(s => s.selectedNodes);
 82→	
 83→	const theme = useSettingsStore(s => s.theme);
 84→	const isDarkTheme = theme === Theme.DARK;
 85→	
 86→	const hasSurfacePosition = nodePositions.hasSurfacePosition();
 87→	const chartRuler = useMemo(
 88→		() => hasSurfacePosition ? getChartRuler(nodePositions, zodiacSignPositions, dignityMode) : null,
 89→		[nodePositions, zodiacSignPositions, dignityMode]
 90→	);
 91→
 92→	const isStandardNode = standardNodes.includes(selectedNode);
 93→
 94→	// Build ordered list of nodes by longitude for arrow navigation
 95→	const orderedNodes = useMemo(() => {
 96→		const nodes = Array.from(selectedNodes).filter(node => {
 97→			// Exclude nodes that depend on location if no surface position
 98→			return hasSurfacePosition || !nodeDependsOnLocation[node];
 99→		});
100→		return nodes.sort((a, b) => {
101→			const lonA = nodePositions.get(a);
102→			const lonB = nodePositions.get(b);
103→			return lonB - lonA;
104→		});
105→	}, [selectedNodes, nodePositions, hasSurfacePosition]);
106→
107→	const handlePrevNode = () => {
108→		const currentIndex = orderedNodes.indexOf(selectedNode);
109→		const prevIndex = (currentIndex - 1 + orderedNodes.length) % orderedNodes.length;
110→		cycleToNode(orderedNodes[prevIndex]);
111→	};
112→
113→	const handleNextNode = () => {
114→		const currentIndex = orderedNodes.indexOf(selectedNode);
115→		const nextIndex = (currentIndex + 1) % orderedNodes.length;
116→		cycleToNode(orderedNodes[nextIndex]);
117→	};
118→
119→	// Get sign and position for selected node
120→	const nodeSign = getSignOfNode(selectedNode, nodePositions, zodiacSignPositions);
121→	const positionInSign = getNodePositionWithinSign(selectedNode, nodePositions, zodiacSignPositions);
122→	const formattedPosition = formatAngle(positionInSign);
123→
124→	const faceLord = zodiacSignPositions.isRegular() ? getFaceLord(selectedNode, nodePositions, zodiacSignPositions, faceMode) : null;
125→	const boundLord = zodiacSignPositions.isRegular() ? getBoundLord(selectedNode, nodePositions, zodiacSignPositions, boundsMode) : null;
126→
127→	// Get house placement (if location defined)
128→	const houseNumber = houseCuspPositions !== null
129→		? getHouseOfNode(selectedNode, nodePositions, houseCuspPositions)
130→		: null;
131→
132→	// Get house angularity
133→	const houseAngularities = houseCuspPositions !== null
134→		? getHouseAngularities(nodePositions, houseCuspPositions, houseAngularityMode)
135→		: null;
136→	const angularity = houseNumber && houseAngularities
137→		? houseAngularities[houseNumber - 1]
138→		: null;
139→
140→	// 2.1 Dignity
141→	const dignityState = getDignityState(selectedNode, nodePositions, zodiacSignPositions, dignityMode);
142→
143→	const triplicityRole = (hasSurfacePosition && standardNodes.includes(selectedNode)) ? getTriplicityRole(selectedNode, nodePositions, zodiacSignPositions, triplicityMode) : null;
144→
145→	// 2.2 Speed & Retrograde
146→	const { formattedSpeedDegPerTimeUnit, isStationary, isRetrograde, timeUnit } = useMemo(() => {
147→		const speedRadPerDay = nodeVelocities.get(selectedNode);
148→		const isStationary = Math.abs(speedRadPerDay) < getNodeAverageSpeed(selectedNode, lunarNodeMode)!*stationarySpeedFractionThreshold;
149→		const isRetrograde = !isStationary && speedRadPerDay < 0;
150→		
151→		if (speedRadPerDay > Math.PI) { // no particular reason for this threshold. Only main angles are gonna hit it anyway
152→			const speedRadPerHr = speedRadPerDay/24;
153→			const formattedSpeedDegPerTimeUnit = formatAngle(Math.abs(speedRadPerHr));
154→			return {
155→				formattedSpeedDegPerTimeUnit,
156→				isStationary,
157→				isRetrograde,
158→				timeUnit: "hr",
159→			};
160→		} else {
161→			const formattedSpeedDegPerTimeUnit = formatAngle(Math.abs(speedRadPerDay), Math.abs(speedRadPerDay)<Math.PI/180, true);
162→			return {
163→				formattedSpeedDegPerTimeUnit,
164→				isStationary,
165→				isRetrograde,
166→				timeUnit: "day",
167→			};
168→		}
169→		return {formattedSpeedDegPerTimeUnit, isStationary, isRetrograde};
170→	}, [selectedNode, date, hamburgSchoolMode, lunarNodeMode])
171→
172→	const nearbyFixedStars = useMemo(() => {
173→		return getFixedStarsWithinLongitude(selectedNode, nodePositions, fixedStarPositions, fixedStarMaximumDistance*Math.PI/180);
174→	}, [selectedNode, fixedStarMaximumDistance, nodePositions, fixedStarPositions])
175→
176→	// 2.3 Angle proximity
177→	const angleProximity = useMemo(() => {
178→		if (!hasSurfacePosition) return null;
179→		return getAngleProximity(selectedNode, nodePositions);
180→	}, [selectedNode, nodePositions, hasSurfacePosition]);
181→
182→	const angleProximityDeg = angleProximity ? (angleProximity.distance * 180 / Math.PI) : null;
183→	const showAngleProximity = angleProximityDeg !== null && angleProximityDeg <= ANGLE_PROXIMITY_THRESHOLD_DEG && !mainAngles.includes(selectedNode);
184→
185→	// 2.4 Rulership chain
186→	const { isFinalDispositor, dispositorChain, finalDispositors } = useMemo(() => {
187→		if (isStandardNode) {
188→			const isFinalDispositor = rulershipGraph.isFinalDispositor(selectedNode);
189→			const chain = rulershipGraph.getDispositorChain(selectedNode);
190→			return {
191→				isFinalDispositor,
