228→	}, [selectedNode, nodePositions]);
229→
230→	const formatOrdinal = (n: number): string => {
231→		const suffixes = ["th", "st", "nd", "rd"];
232→		const v = n % 100;
233→		return n + (suffixes[(v - 20) % 10] || suffixes[v] || suffixes[0]);
234→	};
