240→			[Node.IMUM_COELI] : ["Anti-culminating", "Anti-culminated"],
241→			[Node.DESCENDANT] : ["Setting", "Set"],
242→			[Node.MIDHEAVEN] : ["Culminating", "Culminated"],
243→		}
244→		const verb = verbs[angleProximityInfo.closestAngle]![angleProximityInfo.passed ? 1 : 0];
245→		return (
246→			<div>
247→				{renderString(verb)}
248→				{renderString(` (${angleProximityDeg!.toFixed(1)}° ${preposition} `)}
249→				{renderNode(angleProximityInfo.closestAngle, { forceText: true })}
250→				{renderString(`).`)}
251→			</div>
252→		);
253→	};
254→	
255→	const renderFixedStarSummaryString = (nearbyFixedStars: Map<string, number>) => {
256→		const lastIdx = nearbyFixedStars.size-1;
257→		return (<span className="block pl-3 -indent-3 text-wrap">
258→			{renderString(lastIdx === 0 ? "Fixed star conjunction: " : "Fixed star conjunctions: ")}
259→			{Array.from(nearbyFixedStars.entries()).map(([starName, orb], index) => {
260→				return (<span key={index}>
261→					<span className="text-nowrap pl-1">
262→						{renderSmallcapsString(starName)}
263→						{renderString(` (Δ${formatAngle(orb)})`)}
264→					</span>
265→					{renderString(index === lastIdx ? "." : ", ")}
266→				</span>);
267→			})}
268→		</span>);
269→	};
270→	
271→	const nodeGraphicSVG = () => {
272→		const planetImageWidth = 115;
273→		const largeSymbolWidth = 60;
274→		const padding = 5;
275→		
276→		const sunScaling = 10/9; // measured from images to match outer edges
277→		const sunD = planetImageWidth*(1/2)*(1/sunScaling - 1);
278→		const saturnScaling = 2.43; // eyeballed
279→		const saturnD = planetImageWidth*(1/2)*(1/saturnScaling - 1);
280→		const imageTransform = selectedNode === Node.SUN ? (
281→				`scale(${sunScaling}, ${sunScaling}) translate(${sunD}, ${sunD})`
282→			) : selectedNode === Node.SATURN ? (
283→				`scale(${saturnScaling}, ${saturnScaling*1.05}) translate(${saturnD-4}, ${saturnD-4})` //very eyeballed!
284→			) : (
285→				""
286→			);
287→		return (
288→			<svg width={planetImageWidth+2*padding} height={planetImageWidth+2*padding} overflow={"visible"} className="">
289→				{(nodeImages[selectedNode] === undefined || standardNodes.includes(selectedNode)) &&
290→					<circle cx="50%" cy="50%" r={planetImageWidth/2+padding} fill="url(#outerShadow)" opacity="0.4"/>
291→				}
292→				<circle cx="50%" cy="50%" r={planetImageWidth*(0.5-0.01)} fill="var(--color-bg)"/>
293→				{nodeImages[selectedNode] !== undefined ? (<>
294→					<image
295→						key={0}
296→						x={padding}
297→						y={padding}
298→						href={nodeImages[selectedNode]}
299→						width={planetImageWidth}
300→						height={planetImageWidth}
301→						opacity={1}
302→						filter={isDarkTheme ? "" : "invert(1) var(--icon-filter)"}
303→						transform={imageTransform}
304→					/>
305→					<circle cx="50%" cy="50%" r={planetImageWidth/2} fill="url(#innerShadow)" filter="url(#boost-alpha)" opacity="1"/>
306→				</>) : (<>
307→					<circle cx="50%" cy="50%" r={planetImageWidth*0.50} stroke="var(--color-text)" opacity="0.5" fill="none"/>
308→					<circle cx="50%" cy="50%" r={planetImageWidth*0.45} stroke="var(--color-text)" opacity="0.5" fill="none"/>
309→					<circle cx="50%" cy="50%" r={planetImageWidth*0.40} stroke="var(--color-text)" opacity="0.5"
310→						fill={nodeTypes[selectedNode] === NodeType.POINT ? "none" : "var(--color-text)"}/>
311→				</>)}
312→				<image
313→					key={2}
314→					x={padding}
315→					y={padding}
316→					href={nodeSymbols[selectedNode]}
317→					width={largeSymbolWidth}
318→					height={largeSymbolWidth}
319→					filter={"var(--icon-filter) url(#glow)"}
320→					transform={`translate(${(planetImageWidth-largeSymbolWidth)/2},${(planetImageWidth-largeSymbolWidth)/2})`}
321→				/>
322→				<defs>
323→					<filter id="glow" x="-200%" y="-200%" width="400%" height="400%">
324→						<feDropShadow dx="0" dy="0" stdDeviation="2.5" floodColor="var(--color-text)"/>
325→						<feDropShadow dx="0" dy="0" stdDeviation="2.5" floodColor="var(--color-text)"/>
326→					</filter>
327→					<filter id="boost-alpha">
328→						<feComponentTransfer>
329→							<feFuncA type="table" tableValues="0 0.4 0.7 0.8 0.9"/>
330→						</feComponentTransfer>
331→					</filter>
332→					<radialGradient id="outerShadow" cx="50%" cy="50%" r="50%" fx="50%" fy="50%">
333→						<stop offset="89%" stopColor="var(--color-text)"/>
334→						<stop offset="100%" stopColor="var(--color-bg)"/>
335→					</radialGradient>
336→					<radialGradient id="innerShadow" cx="50%" cy="50%" r="50%" fx="50%" fy="50%">
337→						<stop offset="0%" stopColor="var(--color-bg)"/>
338→						<stop offset="100%" stopColor="var(--color-bg)" stopOpacity="0"/>
339→					</radialGradient>
340→				</defs>
341→			</svg>
342→		);
343→	}
344→	
345→	const renderRuledNodes = (ruledNodes: Node[], transitivelyRuledNodes: Node[]) => {
346→		if (ruledNodes.length === 0){
347→			return renderString("Not ruling any planet or luminary.");
348→		}
349→		
350→		const rulesAllNodes = ruledNodes.length === standardNodes.length - 1;
351→		const transitivelyRulesAllNodes = transitivelyRuledNodes.length === standardNodes.length - 1;
352→		const transitivelyRulesAnyNodes = transitivelyRuledNodes.length > ruledNodes.length ;
353→		const exclusivelyTransitivelyRuledNodes = transitivelyRulesAnyNodes ? transitivelyRuledNodes.filter(n => !ruledNodes.includes(n)) : [];
354→		return (
355→			<span>
356→				{renderString("Rules ")}
357→				{rulesAllNodes && renderString("all planets & luminaries")}
358→				{!rulesAllNodes && renderCommaSeparatedNodeList(ruledNodes)}
359→				{renderString(".")}
360→				{transitivelyRulesAnyNodes && (<>
361→					{renderString(" Transitively rules ")}
362→					{transitivelyRulesAllNodes && renderString("all planets & luminaries")}
363→					{!transitivelyRulesAllNodes && renderCommaSeparatedNodeList(exclusivelyTransitivelyRuledNodes)}
364→					{renderString(".")}
365→				</>)}
366→			</span>
367→		);
368→	}
369→	
370→	const renderDignity = (dignityState: DignityState) => {
371→		const descriptiveStr = {
372→			[Dignity.DOMICILE] : "In Domicile",
373→			[Dignity.EXALTATION] : "Exalted",
374→			[Dignity.DETRIMENT] : "In Detriment",
375→			[Dignity.FALL] : "In Fall",
376→			[Dignity.PEREGRINE] : "Peregrine",
377→		}[dignityState.dignity];
378→		return (
379→			<div>
380→				{renderString(descriptiveStr)}
381→				{dignityState.degreeOffset !== undefined ? (
382→					renderString(` (${dignityState.degreeOffset > 0 ? "+" : ""}${dignityState.degreeOffset.toFixed(0)}° from exact)`)
383→				) : (
384→					null
385→				)}
386→			</div>
387→		);
388→	}
389→
390→	return (
391→		<div className="text-theme-text p-4" style={{ width: 330 }}>
392→			{/* Planet Header with Navigation */}
393→			<div className="flex items-center justify-between mb-2">
394→				<button
395→					className="bg-transparent border-none text-theme-text cursor-pointer p-1 text-xl hover:opacity-70"
396→					onClick={handlePrevNode}
397→					title="Previous planet"
398→				>
399→					◀
400→				</button>
401→				<div className="text-center">
402→					{renderNode(selectedNode, { forceText: true })}
403→				</div>
404→				<button
405→					className="bg-transparent border-none text-theme-text cursor-pointer p-1 text-xl hover:opacity-70"
406→					onClick={handleNextNode}
407→					title="Next planet"
408→				>
409→					▶
410→				</button>
411→			</div>
412→
413→			<hr className="opacity-50 my-2" />
414→			
415→			<div className="flex gap-5">
416→				{nodeGraphicSVG()}
417→				{/* POSITION / SIGN, POSITION WITHIN SIGN */}
418→				<div className="text-right flex-grow">
419→					
420→					{/* Sign and Position */}
421→					<div className="mt-2">
422→						{renderSign(nodeSign)}
423→						{renderString(" · ")}
424→						{renderSmallcapsString(formattedPosition)}
425→					</div>
426→				
427→					{/* House, house angularity */}
428→					{houseNumber && (
429→						<div>
430→							{renderString(`${formatOrdinal(houseNumber)} House`)}
431→							{angularity && (
432→								<>
433→									{renderString(" · ")}
434→									{renderString(angularity)}
435→								</>
436→							)}
437→						</div>
438→					)}
439→					
440→					{/* Chart ruler */}
441→					{selectedNode === chartRuler && (<div className="underline">{renderString("Chart Ruler")}</div>)}
442→					
443→					{/* Dignity */}
444→					{dignityState && renderDignity(dignityState)}
445→					
446→					{useExtendedDignities && (triplicityRole !== null) && (
447→						<div>
448→							{renderString(`Triplicity Ruler (${triplicityRole})`)}
449→						</div>
450→					)}
451→
452→					{/* Speed / Retrograde */}
453→					{formattedSpeedDegPerTimeUnit !== null && (
454→						<div>
455→							{isStationary ? (
456→								renderString("Stationary")
457→							) : isRetrograde ? (
458→								renderString("Retrograde")
459→							) : (
460→								renderString("Direct")
461→							)}
462→							{renderString(` (${formattedSpeedDegPerTimeUnit} / ${timeUnit})`)}
463→						</div>
464→					)}
465→
466→					{/* Sect */}
467→					{inSect !== null && (
468→						<div>
469→							{renderString(inSect ? "In Sect" : "Out of Sect")}
470→							{false && renderString(chartIsDiurnal ? " (Diurnal Chart)" : " (Nocturnal Chart)")}
471→						</div>
472→					)}
473→				
474→				</div>
475→			</div>
476→					
477→			{/* Extended dignities (face and bound, not triplicity)*/}
478→			{useExtendedDignities && zodiacSignPositions.isRegular() && ( faceLord === boundLord ? (
479→				<div className="text-wrap">
480→					{renderString("In the face & bound of ")}
481→					{renderNode(faceLord!, { withArticle: true })}
482→					{renderString(".")}
483→				</div>
484→			) : (
485→				<div>
486→					{renderString("In the face of ")}
487→					{renderNode(faceLord!, { withArticle: true })}
488→					{renderString(" & the bound of ")}
489→					{renderNode(boundLord!, { withArticle: true })}
490→					{renderString(".")}
491→				</div>
492→			))}
493→					
494→			{/* Angle Proximity */}
495→			{showAngleProximity && angleProximity && formatAngleProximity(angleProximity)}
496→
497→			{/* Aspects Summary */}
498→			{aspectsSummary.nAspects > 0 ? (
499→				<>
500→					{renderString(`In ${aspectsSummary.nAspects} aspect${aspectsSummary.nAspects !== 1 ? "s" : ""}`)}
501→					{aspectsSummary.nConfigurations > 0 && (
502→						renderString(` (${aspectsSummary.nConfigurations} configuration${aspectsSummary.nConfigurations !== 1 ? "s" : ""})`)
503→					)}
504→					{renderString(", with ")}
505→					{Array.from(aspectsSummary.nodes).map((node, i) => (
506→						<span key={i}>
507→							{i > 0 && renderString(", ")}
508→							{renderNode(node)}
509→						</span>
510→					))}
511→					{renderString(". ")}
512→					{!isHighlighted && (
513→						<button
514→							className="bg-transparent border-none text-theme-text underline cursor-pointer p-0 m-0 font-[inherit] inline hover:opacity-70"
515→							onClick={highlightSelected}
516→						>
517→							{renderString("Highlight aspects.")}
518→						</button>
519→					)}
520→				</>
521→			) : (
522→				renderString("Not in any aspects.")
523→			)}
524→			
525→			{useFixedStars && nearbyFixedStars.size > 0 && (
526→				<div>
527→					{renderFixedStarSummaryString(nearbyFixedStars)}
528→				</div>
529→			)}
530→
531→			{/* Rulership Chain */}
532→			{(dispositorChain || finalDispositors) && (
533→				<>
534→					<hr className="opacity-50 mt-4" />
535→					<span className="absolute -translate-y-4 translate-x-2 bg-theme-bg px-1">
536→						{renderSmallcapsString("Dispositorship")}
537→					</span>
538→					<div>
539→						<div className="mt-2">
540→							{isFinalDispositor ? (
541→								renderFinalDispositors(finalDispositors!, true)
542→							) : (
543→								renderDispositorChain(dispositorChain!, true)
544→							)}
545→						</div>
546→						{isStandardNode && renderRuledNodes(ruledNodes!, transitivelyRuledNodes!)}
547→					</div>
548→				</>
549→			)}
550→		</div>
551→	);
552→};
553→
554→export default PlanetPanel;
555→

