  1→import { type ReactNode } from 'react';
  2→import { Node, Zodiac, Mode, Element, mainAngles } from './astroDefs';
  3→import { AspectKind } from './aspectDefs';
  4→import { type DispositorChain, type FinalDispositors, getFinalDispositorsOfChain } from './rulershipGraph.ts'
  5→import {
  6→	zodiacSymbols,
  7→	nodeSymbols,
  8→	nodePreferredName,
  9→	elementSymbols,
 10→	modeSymbols,
 11→	nodesWithRedundantSymbols,
 12→	nodesAdmittingArticle,
 13→	aspectKindColors,
 14→	aspectSymbols
 15→} from './astroGraphics';
 16→import { useSettingsStore } from './settingsStore';
 17→
 18→// Default sizes - can be overridden via optional params
 19→const DEFAULT_TEXT_SIZE = 12;
 20→const DEFAULT_TITLE_SIZE = 14;
 21→const DEFAULT_SYMBOL_SIZE = 20;
 22→
 23→interface TextRenderOptions {
 24→	fontSize?: number;
 25→	fontStyle?: string;
 26→}
 27→
 28→interface SymbolRenderOptions {
 29→	size?: number;
 30→}
 31→
 32→export const renderSmallcapsString = (
 33→	str: string,
 34→	options: TextRenderOptions = {}
 35→): ReactNode => {
 36→	const { fontSize = DEFAULT_TEXT_SIZE } = options;
 37→	return (
 38→		<span className="small-caps font-bold" style={{ fontSize }}>
 39→			{str}
 40→		</span>
 41→	);
 42→};
 43→
 44→export const renderString = (
 45→	str: string,
 46→	options: TextRenderOptions = {}
 47→): ReactNode => {
 48→	const { fontSize = DEFAULT_TEXT_SIZE, fontStyle = "normal" } = options;
 49→	return (
 50→		<span style={{ fontSize, fontStyle }}>
 51→			{str}
 52→		</span>
 53→	);
 54→};
 55→
 56→export const renderTitle = (
 57→	str: string,
 58→	options: TextRenderOptions = {}
 59→): ReactNode => {
 60→	const { fontSize = DEFAULT_TITLE_SIZE } = options;
 61→	return (
 62→		<span className="small-caps font-bold tracking-wide" style={{ fontSize }}>
 63→			{str}
 64→		</span>
 65→	);
 66→};
 67→
 68→interface RenderNodeOptions {
 69→	showLabel?: boolean;
 70→	withArticle?: boolean;
 71→	forceText?: boolean; // force text for special nodes like Asc, etc.
 72→	size?: number;
 73→	fontSize?: number;
 74→}
 75→
 76→// Helper to determine if "the" should be prepended to a node name
 77→const shouldUseArticle = (node: Node, withArticle: boolean): boolean => {
 78→	if (!withArticle || !nodesAdmittingArticle.includes(node)) {
 79→		return false;
 80→	}
 81→	if (mainAngles.includes(node)) {
 82→		return useSettingsStore.getState().useArticleForMainAngles;
 83→	}
 84→	return true;
 85→};
 86→
 87→export const renderNode = (
 88→	node: Node,
 89→	options: RenderNodeOptions = {}
 90→): ReactNode => {
 91→	const {
 92→		showLabel,
 93→		withArticle = false,
 94→		forceText = false,
 95→		size = DEFAULT_SYMBOL_SIZE,
 96→		fontSize = DEFAULT_TEXT_SIZE
 97→	} = options;
 98→	const resolvedShowLabel = showLabel ?? useSettingsStore.getState().showNodeLabels;
 99→	if (resolvedShowLabel || (forceText && nodesWithRedundantSymbols.includes(node))) {
100→		const label = nodePreferredName[node] || node;
101→		if (shouldUseArticle(node, withArticle)) {
102→			return <>{renderString("the ", { fontSize })}{renderSmallcapsString(String(label), { fontSize })}</>;
103→		}
104→		return renderSmallcapsString(String(label), { fontSize });
105→	}
106→	return (
107→		<img
108→			src={nodeSymbols[node]}
109→			alt={node}
110→			width={size}
111→			height={size}
112→			className="icon-filter align-middle inline"
113→		/>
114→	);
115→};
116→
117→interface RenderAspectKindOptions {
118→	showLabel?: boolean;
119→	withArticle?: boolean; //"a conjunction / an opposition"
120→	colorcode?: boolean;
121→	size?: number;
122→	fontSize?: number;
123→}
124→
125→export const renderAspectKind = (
126→	aspectKind: AspectKind,
127→	options: RenderAspectKindOptions = {}
128→): ReactNode => {
129→	const {
130→		showLabel,
131→		withArticle = false,
132→		colorcode,
133→		size = DEFAULT_SYMBOL_SIZE,
134→		fontSize = DEFAULT_TEXT_SIZE,
135→	} = options;
136→	
137→	if (withArticle) {
138→		throw new Error("Articles in renderAspectKind are not yet implemented");
139→	}
140→	
141→	const resolvedShowLabel = showLabel ?? useSettingsStore.getState().showAspectLabels;
142→	const resolvedColorcode = colorcode ?? useSettingsStore.getState().aspectsColorcoded;
143→	
144→	const aspectColorcoded = resolvedColorcode && (aspectKind in aspectKindColors);
145→	const [r,g,b] = aspectColorcoded ? aspectKindColors[aspectKind]! : [-1,-1,-1];
146→	
147→	return resolvedShowLabel ? (
148→		<label
149→			className="text-xs whitespace-nowrap font-bold small-caps"
150→			style={{fontSize, color: aspectColorcoded ? `rgb(${r}, ${g}, ${b})` : "var(--color-text)"}}
151→		>
152→			{aspectKind}
153→		</label>
154→	) : (
155→		aspectColorcoded ? (
156→			<div
157→				style={{
158→					WebkitMaskImage: `url(${aspectSymbols[aspectKind]})`,
159→					maskImage: `url(${aspectSymbols[aspectKind]})`,
160→					WebkitMaskRepeat: "no-repeat",
161→					maskRepeat: "no-repeat",
162→					WebkitMaskSize: "contain",
163→					maskSize: "contain",
164→					width: size,
165→					height: size,
166→					backgroundColor: `rgb(${r}, ${g}, ${b})`,
167→				}}
168→			/>
169→		) : (
170→			<img
171→				className="icon-filter"
172→				src={aspectSymbols[aspectKind]}
173→				alt={aspectKind}
174→				width={size}
175→				height={size}
176→			/>
177→		)
178→	);
179→};
180→	
181→export const renderCommaSeparatedNodeList = (
182→	nodes: Node[],
183→	showLabels?: boolean,
184→	options: SymbolRenderOptions & TextRenderOptions = {}
185→): ReactNode => {
186→	const resolvedShowLabels = showLabels ?? useSettingsStore.getState().showNodeLabels;
187→	const { size = DEFAULT_SYMBOL_SIZE, fontSize = DEFAULT_TEXT_SIZE } = options;
188→	return (
189→		<>
190→			{nodes.map((node, i) => (
191→				<span key={i}>
192→					{i > 0 && renderString(", ")}
193→					{renderNode(node, { showLabel: resolvedShowLabels, size, fontSize })}
194→				</span>
195→			))}
196→		</>
197→	);
198→}
199→
200→export const renderSign = (
201→	sign: Zodiac,
202→	showLabel?: boolean,
203→	options: SymbolRenderOptions & TextRenderOptions = {}
204→): ReactNode => {
205→	const resolvedShowLabel = showLabel ?? useSettingsStore.getState().showSymbolLabels;
206→	const { size = DEFAULT_SYMBOL_SIZE, fontSize = DEFAULT_TEXT_SIZE } = options;
207→	if (resolvedShowLabel) {
208→		return renderSmallcapsString(sign, { fontSize });
209→	}
210→	return (
211→		<img
212→			src={zodiacSymbols[sign]}
213→			alt={sign}
214→			width={size}
215→			height={size}
216→			className="icon-filter align-middle inline"
217→		/>
218→	);
219→};
220→
221→export const renderElement = (
222→	elem: Element,
223→	showLabel?: boolean,
224→	options: SymbolRenderOptions & TextRenderOptions = {}
225→): ReactNode => {
226→	const resolvedShowLabel = showLabel ?? useSettingsStore.getState().showElementLabels;
227→	const { size = DEFAULT_SYMBOL_SIZE, fontSize = DEFAULT_TEXT_SIZE } = options;
228→	if (resolvedShowLabel) {
229→		return renderSmallcapsString(elem, { fontSize });
230→	}
231→	return (
232→		<img
233→			src={elementSymbols[elem]}
234→			alt={elem}
235→			width={size}
236→			height={size}
237→			className="icon-filter align-middle inline"
238→		/>
239→	);
240→};
241→
242→export const renderMode = (
243→	mode: Mode,
244→	showLabel?: boolean,
245→	options: SymbolRenderOptions & TextRenderOptions = {}
246→): ReactNode => {
247→	const resolvedShowLabel = showLabel ?? useSettingsStore.getState().showModeLabels;
248→	const { size = DEFAULT_SYMBOL_SIZE, fontSize = DEFAULT_TEXT_SIZE } = options;
249→	if (resolvedShowLabel) {
250→		return renderSmallcapsString(mode, { fontSize });
251→	}
252→	return (
253→		<img
254→			src={modeSymbols[mode]}
255→			alt={mode}
256→			width={size}
257→			height={size}
258→			className="icon-filter align-middle inline"
259→		/>
260→	);
261→};
262→
263→export const renderArrow = (options: TextRenderOptions = {}): ReactNode => {
264→	const { fontSize = DEFAULT_TEXT_SIZE } = options;
265→	return <span className="mx-1" style={{ fontSize }}>{" \u2192 "}</span>;
266→};
267→
268→export const renderMutualArrow = (options: TextRenderOptions = {}): ReactNode => {
