@import "tailwindcss";

@theme {
	/* Theme color utilities: bg-theme-bg, text-theme-text, border-theme-border */
	--color-theme-text: var(--color-text);
	--color-theme-bg: var(--color-bg);
	--color-theme-border: var(--color-border);
	--color-theme-border-light: var(--color-border-light);
}

* {
	box-sizing: border-box;
}

:root {
	/* Theme CSS variables - default (dark) theme */
	--color-text: #ffffff;
	--color-bg: #000000;
	--color-border: #555;
	--color-border-light: #aaa;
	--border-radius: 0px;
	--icon-filter: invert(1);

	font-family: system-ui, Avenir, Helvetica, Arial, sans-serif;
	line-height: 1.5;
	font-weight: 400;

	color: var(--color-text);
	background-color: var(--color-bg);

	font-synthesis: none;
	text-rendering: optimizeLegibility;
	-webkit-font-smoothing: antialiased;
	-moz-osx-font-smoothing: grayscale;
}

/* Parchment theme */
:root.theme-parchment {
	font-family: ui-serif, Georgia, serif;
	--color-text: #3d2914;
	--color-bg: #f5e6d3;
	--color-border: #B9A895;
	--color-border-light: #7A6853;
	--border-radius: 4px;
	/* from https://codepen.io/sosuke/pen/Pjoqqp, to match color-text */
	--icon-filter: invert(12%) sepia(60%) saturate(629%) hue-rotate(350deg) brightness(91%) contrast(88%);
}

body {
	margin: 0;

