	return (
		<SelectorButton
			selected={selected}
			disabled={disabled}
			highlighted={highlighted}
			onClick={onClick}
			title={item}
		>
			<span className={`flex flex-col items-center ${disabled ? "cursor-not-allowed" : ""}`}>
				{renderNode(item, options)}
			</span>
		</SelectorButton>
	);
};

export const AspectKindSelectorButton = ({
	item,
	selected,
	disabled = false,
	highlighted = false,
	onClick,
	options = {},
}: {
	item: AspectKind;
	selected: boolean;
	disabled?: boolean;
	highlighted?: boolean;
	onClick: () => void;
	options?: RenderAspectKindOptions;
}): ReactNode => {
	return (
		<SelectorButton
			selected={selected}
			disabled={disabled}
			highlighted={highlighted}
			onClick={onClick}
			title={item}
		>
			<span className={`flex flex-col items-center ${disabled ? "cursor-not-allowed" : ""}`}>
				{renderAspectKind(item, options)}
			</span>
		</SelectorButton>
	);
};

