	const nearbyFixedStars = useFixedStars
		? getFixedStarsWithinLongitude(node, nodePositions, fixedStarPositions, fixedStarMaxDistance * Math.PI / 180)
		: new Map<string, number>();

	// Angle proximity
	let angleProximityLabel: string | null = null;
	if (hasSurfacePosition && !mainAngles.includes(node)) {
		const prox = getAngleProximity(node, nodePositions);
		const deg = prox.distance * 180 / Math.PI;
		if (deg <= 10) {
			const angleNames: Partial<Record<Node, string>> = {
				[Node.ASCENDANT]: "Asc",
				[Node.DESCENDANT]: "Dsc",
				[Node.MIDHEAVEN]: "MC",
				[Node.IMUM_COELI]: "IC",
			};
			angleProximityLabel = `${deg.toFixed(1)}° ${angleNames[prox.closestAngle] ?? ""}`;
		}
	}

	return {
		node, sign, positionInSign, houseNumber, angularity,
		dignityLabel, isRetrograde, isStationary, speedLabel,
		nAspects: summary.nAspects, nConfigurations: summary.nConfigurations,
		inSect, isChartRuler: node === chartRuler,
		faceLord, boundLord, triplicityRole: triplicityRole,
		nearbyFixedStars, angleProximityLabel,
	};
}


