}


// ============================================================================
// PlanetTable component
// ============================================================================

type PlanetTableProps = {
	nodePositions: NodePositions;
	nodeVelocities: NodeVelocities;
	zodiacSignPositions: ZodiacSignPositions;
	fixedStarPositions: FixedStarPositions;
	houseCuspPositions: HouseCuspPositions | null;
	rulershipGraph: RulershipGraph;
	aspects: Map<Aspect, Aspect[]>;
	nodesToConsider: NodesToConsider;
	setHighlightedNode: (node: Node) => void;
};

// Column widths (px) — easy to tweak
const COL = {
	node: 36,
	sign: 60,
	position: 30,
	house: 30,
	angularity: 40,
	dignity: 40,
	speed: 50,
	aspects: 30,
	configs: 30,
	sect: 40,
	face: 36,
	bound: 36,
	triplicity: 56,
	stars: 100,
	angleProx: 64,
};

const ROW_H = 28;

const PlanetTable: FC<PlanetTableProps> = ({
	nodePositions,
	nodeVelocities,
	zodiacSignPositions,
	fixedStarPositions,
	houseCuspPositions,
	// rulershipGraph — available via props but not currently used
	aspects,
	nodesToConsider,
	setHighlightedNode,
}) => {
	const dignityMode = useSettingsStore(s => s.dignityMode);
	const houseAngularityMode = useSettingsStore(s => s.houseAngularityMode);
	const lunarNodeMode = useSettingsStore(s => s.lunarNodeMode);
	const stationaryThreshold = useSettingsStore(s => s.stationarySpeedPercentageThreshold) / 100;
	const useFixedStars = useSettingsStore(s => s.useFixedStars);
	const fixedStarMaxDistance = useSettingsStore(s => s.fixedStarMaximumDistance);
	const useExtendedDignities = useSettingsStore(s => s.useExtendedDignities);
	const triplicityMode = useSettingsStore(s => s.triplicityMode);
	const faceMode = useSettingsStore(s => s.faceMode);
	const boundsMode = useSettingsStore(s => s.boundsMode);
	const selectedNodes = useSettingsStore(s => s.selectedNodes);

	// render deps
	useSettingsStore(s => s.showNodeLabels);
	useSettingsStore(s => s.showSymbolLabels);

	const hasSurfacePosition = nodePositions.hasSurfacePosition();

	const chartRuler = useMemo(
		() => hasSurfacePosition ? getChartRuler(nodePositions, zodiacSignPositions, dignityMode) : null,
		[nodePositions, zodiacSignPositions, dignityMode, hasSurfacePosition]
	);

	const houseAngularities = useMemo(
		() => houseCuspPositions !== null
			? getHouseAngularities(nodePositions, houseCuspPositions, houseAngularityMode)
			: null,
		[nodePositions, houseCuspPositions, houseAngularityMode]
	);

	const nodes = useMemo(
		() => getNodesForMode(nodesToConsider, selectedNodes, hasSurfacePosition),
		[nodesToConsider, selectedNodes, hasSurfacePosition]
	);

	const rows: NodeRowData[] = useMemo(() => {
		return nodes.map(node => computeRowData(
			node, nodePositions, nodeVelocities, zodiacSignPositions,
			fixedStarPositions, houseCuspPositions, houseAngularities, aspects,
			chartRuler, dignityMode, lunarNodeMode, stationaryThreshold,
			useFixedStars, fixedStarMaxDistance, useExtendedDignities,
			triplicityMode, faceMode, boundsMode, hasSurfacePosition,
		));
	}, [
		nodes, nodePositions, nodeVelocities, zodiacSignPositions,
		fixedStarPositions, houseCuspPositions, houseAngularities, aspects,
		chartRuler, dignityMode, lunarNodeMode, stationaryThreshold,
		useFixedStars, fixedStarMaxDistance, useExtendedDignities,
		triplicityMode, faceMode, boundsMode, hasSurfacePosition,
	]);

	// ── Rendering helpers ──

	const cellClass = "flex items-center justify-center overflow-hidden";

	const renderInapplicableCell = (width: number) => (
		<div className={cellClass} style={{ width, height: ROW_H }}>
			<span className="text-theme-text opacity-20 text-xs">—</span>
		</div>
	);

	const renderCell = (
		content: React.ReactNode,
		width: number,
		applicability: CellApplicability = 'applicable',
		extraClass: string = '',
	) => {
		if (applicability === 'not-applicable' || applicability === 'no-data') {
			return renderInapplicableCell(width);
		}
		return (
			<div
				className={`${cellClass} ${extraClass}`}
				style={{ width, height: ROW_H }}
			>
				{content}
			</div>
		);
	};

	const HEADER_H = 48;
	const HEADER_ANGLE = -35; // degrees

	const headerCell = (label: string, width: number) => (
		<div
			className="flex items-end justify-center overflow-visible"
			style={{ width, height: HEADER_H }}
		>
			<span
				className="text-theme-text opacity-50 text-[10px] uppercase tracking-wider whitespace-nowrap origin-bottom-center"
				style={{ transform: `rotate(${HEADER_ANGLE}deg)`, display: 'inline-block' }}
			>
				{label}
			</span>
		</div>
	);

	// ── Determine visible columns ──

	const showHouse = hasSurfacePosition;
	const showAngularity = hasSurfacePosition;
	const showFace = useExtendedDignities && zodiacSignPositions.isRegular();
	const showBound = useExtendedDignities && zodiacSignPositions.isRegular();
	const showSect = hasSurfacePosition;

	// these always hidden - too wide for low info
	const showTriplicity = false && useExtendedDignities && hasSurfacePosition;
	const showStars = false && useFixedStars;
	const showAngleProx = false && hasSurfacePosition;

	return (
		<div className="text-theme-text text-xs select-none">
			{/* Header */}
			<div className="flex border-b border-theme-border">
				{headerCell("", COL.node)}
				{headerCell("Sign", COL.sign)}
				{headerCell("Pos", COL.position)}
				{showHouse && headerCell("H", COL.house)}
				{showAngularity && headerCell("Ang", COL.angularity)}
				{headerCell("Dig", COL.dignity)}
				{headerCell("Speed", COL.speed)}
				{headerCell("#Asp", COL.aspects)}
				{headerCell("#Cfg", COL.configs)}
				{showSect && headerCell("Sect", COL.sect)}
				{showFace && headerCell("Face", COL.face)}
				{showBound && headerCell("Bnd", COL.bound)}
				{showTriplicity && headerCell("Trip", COL.triplicity)}
				{showStars && headerCell("Stars", COL.stars)}
				{showAngleProx && headerCell("Angle", COL.angleProx)}
			</div>

			{/* Rows */}
			{rows.map((row) => {
				const app = (col: string) => getCellApplicability(row.node, col, hasSurfacePosition);

				// Speed styling: highlight retrograde with emphasis color, stationary with underline
				const speedClass = row.isRetrograde
					? "text-emphasis"
					: row.isStationary
						? "underline"
						: "";

				const speedPrefix = row.isRetrograde ? "R " : row.isStationary ? "S " : "";

				return (
					<div
						key={row.node}
						className={`flex border-b border-theme-border/30 hover:bg-theme-text/5 cursor-pointer ${row.isChartRuler ? "bg-theme-text/[0.04]" : ""}`}
						onClick={() => setHighlightedNode(row.node)}
					>
						{/* Node icon */}
						{renderCell(
							renderNode(row.node, { size: 16, fontSize: 10 }),
							COL.node,
						)}

						{/* Sign - pos 
						{renderCell(
							(<>
								{renderSign(row.sign, undefined, { size: 16, fontSize: 10 })}
								{renderString(formatAngle(row.positionInSign), { fontSize: 10 })}
							</>),
							COL.sign,
						)}*/}

						{/* Sign */}
						{renderCell(
							renderSign(row.sign, undefined, { size: 16, fontSize: 10 }),
							COL.sign,
						)}

						{/* Position in sign */}
						{renderCell(
							renderString(formatAngle(row.positionInSign), { fontSize: 10 }),
							COL.position,
						)}

						{/* House */}
						{showHouse && renderCell(
							row.houseNumber !== null ? renderString(String(row.houseNumber), { fontSize: 10 }) : null,
							COL.house,
							app('house'),
						)}

						{/* Angularity */}
						{showAngularity && renderCell(
							row.angularity ? renderString(
								row.angularity === HouseAngularity.ANGULAR ? "Ang"
									: row.angularity === HouseAngularity.SUCCEDENT ? "Suc"
										: "Cad",
								{ fontSize: 10 }
							) : null,
							COL.angularity,
							app('angularity'),
						)}

						{/* Dignity */}
						{renderCell(
							row.dignityLabel ? renderString(row.dignityLabel, { fontSize: 10 }) : null,
							COL.dignity,
							app('dignity'),
						)}

						{/* Speed */}
						{renderCell(
							<span className={speedClass}>
								{renderString(`${speedPrefix}${row.speedLabel}`, { fontSize: 10 })}
							</span>,
							COL.speed,
						)}

						{/* Aspects count */}
						{renderCell(
							renderString(String(row.nAspects), { fontSize: 10 }),
							COL.aspects,
						)}

						{/* Configurations count */}
						{renderCell(
							row.nConfigurations > 0
								? renderString(String(row.nConfigurations), { fontSize: 10 })
								: <span className="opacity-30">{renderString("0", { fontSize: 10 })}</span>,
							COL.configs,
						)}

						{/* Sect */}
						{showSect && renderCell(
							row.inSect !== null
								? renderString(row.inSect ? "In" : "Out", { fontSize: 10 })
								: null,
							COL.sect,
							app('sect'),
						)}

						{/* Face lord */}
						{showFace && renderCell(
							row.faceLord ? renderNode(row.faceLord, { size: 14, fontSize: 9 }) : null,
							COL.face,
							app('face'),
						)}

						{/* Bound lord */}
						{showBound && renderCell(
							row.boundLord ? renderNode(row.boundLord, { size: 14, fontSize: 9 }) : null,
							COL.bound,
							app('bound'),
						)}

						{/* Triplicity */}
						{showTriplicity && renderCell(
							row.triplicityRole
								? renderString(row.triplicityRole, { fontSize: 9 })
								: null,
							COL.triplicity,
							app('triplicity'),
						)}

						{/* Fixed stars */}
						{showStars && renderCell(
							row.nearbyFixedStars.size > 0
								? renderString(
									Array.from(row.nearbyFixedStars.keys()).join(", "),
									{ fontSize: 9 }
								)
								: null,
							COL.stars,
						)}

						{/* Angle proximity */}
						{showAngleProx && renderCell(
							row.angleProximityLabel
								? renderString(row.angleProximityLabel, { fontSize: 9 })
								: null,
							COL.angleProx,
							app('angleProximity'),
						)}
					</div>
				);
			})}
		</div>
	);
};

export default PlanetTable;

