	position: 30,
	house: 30,
	angularity: 40,
	dignity: 40,
	speed: 50,
	aspects: 30,
	configs: 30,
	sect: 40,
	face: 36,
	bound: 36,
	triplicity: 56,
	stars: 100,
	angleProx: 64,
