  1→import { useMemo, type FC } from 'react';
  2→import { Node, NodeType, nodeTypes, standardNodes, mainAngles, nodeDependsOnLocation, HouseAngularity } from './astroDefs';
  3→import { NodesToConsider } from './settingsDefs';
  4→import { getNodeAverageSpeed } from './astroData';
  5→import { RulershipGraph } from './rulershipGraph';
  6→import { Aspect, filterAspectsByNode, getAspectsSummaryData } from './aspects';
  7→import {
  8→	getChartRuler, getHouseAngularities, getAngleProximity,
  9→	isInSect, getFixedStarsWithinLongitude, getSignOfNode,
 10→	getNodePositionWithinSign, getHouseOfNode
 11→} from './chartAnalysis';
 12→import { getDignityState, getBoundLord, getFaceLord, getTriplicityRole, Dignity } from './dignities';
 13→import { formatAngle } from './util';
 14→import { renderString, renderSign, renderNode } from './renderPrimitives';
 15→import { useSettingsStore } from './settingsStore';
 16→import NodePositions from './nodePositions';
 17→import NodeVelocities from './nodeVelocities';
 18→import ZodiacSignPositions from './zodiacSignPositions';
 19→import FixedStarPositions from './fixedStarPositions';
 20→import HouseCuspPositions from './houseCuspPositions';
 21→
 22→// ============================================================================
 23→// Data computation (all per-node, computed up front)
 24→// ============================================================================
 25→
 26→interface NodeRowData {
 27→	node: Node;
 28→	sign: ReturnType<typeof getSignOfNode>;
 29→	positionInSign: number;
 30→	houseNumber: number | null;
 31→	angularity: string | null;
 32→	dignityLabel: string | null;
 33→	isRetrograde: boolean;
 34→	isStationary: boolean;
 35→	speedLabel: string;
 36→	nAspects: number;
 37→	nConfigurations: number;
 38→	inSect: boolean | null;
 39→	isChartRuler: boolean;
 40→	faceLord: Node | null;
 41→	boundLord: Node | null;
 42→	triplicityRole: string | null;
 43→	nearbyFixedStars: Map<string, number>;
 44→	angleProximityLabel: string | null;
 45→}
 46→
 47→function computeRowData(
 48→	node: Node,
 49→	nodePositions: NodePositions,
 50→	nodeVelocities: NodeVelocities,
 51→	zodiacSignPositions: ZodiacSignPositions,
 52→	fixedStarPositions: FixedStarPositions,
 53→	houseCuspPositions: HouseCuspPositions | null,
 54→	houseAngularities: (string | null)[] | null,
 55→	aspects: Map<Aspect, Aspect[]>,
 56→	chartRuler: Node | null,
 57→	dignityMode: string,
 58→	lunarNodeMode: string,
 59→	stationaryThreshold: number,
 60→	useFixedStars: boolean,
 61→	fixedStarMaxDistance: number,
 62→	useExtendedDignities: boolean,
 63→	triplicityMode: string,
 64→	faceMode: string,
 65→	boundsMode: string,
 66→	hasSurfacePosition: boolean,
 67→): NodeRowData {
 68→	const sign = getSignOfNode(node, nodePositions, zodiacSignPositions);
 69→	const positionInSign = getNodePositionWithinSign(node, nodePositions, zodiacSignPositions);
 70→
 71→	const houseNumber = houseCuspPositions !== null
 72→		? getHouseOfNode(node, nodePositions, houseCuspPositions)
 73→		: null;
 74→
 75→	const angularity = houseNumber && houseAngularities
 76→		? houseAngularities[houseNumber - 1]
 77→		: null;
 78→
 79→	// Dignity
 80→	const dignityState = getDignityState(node, nodePositions, zodiacSignPositions, dignityMode as any);
 81→	const dignityLabel = dignityState ? ({
 82→		[Dignity.DOMICILE]: "Dom",
 83→		[Dignity.EXALTATION]: "Exl",
 84→		[Dignity.DETRIMENT]: "Det",
 85→		[Dignity.FALL]: "Fall",
 86→		[Dignity.PEREGRINE]: "Per",
 87→	})[dignityState.dignity] : null;
 88→
 89→	// Speed
 90→	const speedRadPerDay = nodeVelocities.get(node);
 91→	const avgSpeed = getNodeAverageSpeed(node, lunarNodeMode as any);
 92→	const isStationary = avgSpeed !== undefined && Math.abs(speedRadPerDay) < avgSpeed * stationaryThreshold;
 93→	const isRetrograde = !isStationary && speedRadPerDay < 0;
 94→	const speedLabel = formatAngle(Math.abs(speedRadPerDay), Math.abs(speedRadPerDay) < Math.PI / 180, true);
 95→
 96→	// Aspects
 97→	const filtered = filterAspectsByNode(aspects, node);
 98→	const summary = getAspectsSummaryData(filtered);
 99→	summary.nodes.delete(node);
100→
101→	// Sect
102→	const inSect = hasSurfacePosition ? isInSect(node, nodePositions) : null;
103→
104→	// Extended dignities
105→	const isRegular = zodiacSignPositions.isRegular();
106→	const faceLord = (useExtendedDignities && isRegular)
107→		? getFaceLord(node, nodePositions, zodiacSignPositions, faceMode as any) : null;
108→	const boundLord = (useExtendedDignities && isRegular)
109→		? getBoundLord(node, nodePositions, zodiacSignPositions, boundsMode as any) : null;
110→	const triplicityRole = (useExtendedDignities && hasSurfacePosition && standardNodes.includes(node))
111→		? getTriplicityRole(node, nodePositions, zodiacSignPositions, triplicityMode as any) : null;
112→
113→	// Fixed stars
114→	const nearbyFixedStars = useFixedStars
115→		? getFixedStarsWithinLongitude(node, nodePositions, fixedStarPositions, fixedStarMaxDistance * Math.PI / 180)
116→		: new Map<string, number>();
117→
118→	// Angle proximity
119→	let angleProximityLabel: string | null = null;
120→	if (hasSurfacePosition && !mainAngles.includes(node)) {
121→		const prox = getAngleProximity(node, nodePositions);
122→		const deg = prox.distance * 180 / Math.PI;
123→		if (deg <= 10) {
124→			const angleNames: Partial<Record<Node, string>> = {
125→				[Node.ASCENDANT]: "Asc",
126→				[Node.DESCENDANT]: "Dsc",
127→				[Node.MIDHEAVEN]: "MC",
128→				[Node.IMUM_COELI]: "IC",
129→			};
130→			angleProximityLabel = `${deg.toFixed(1)}° ${angleNames[prox.closestAngle] ?? ""}`;
131→		}
132→	}
133→
134→	return {
135→		node, sign, positionInSign, houseNumber, angularity,
136→		dignityLabel, isRetrograde, isStationary, speedLabel,
137→		nAspects: summary.nAspects, nConfigurations: summary.nConfigurations,
138→		inSect, isChartRuler: node === chartRuler,
139→		faceLord, boundLord, triplicityRole: triplicityRole,
140→		nearbyFixedStars, angleProximityLabel,
141→	};
142→}
143→
144→
145→// ============================================================================
146→// Helpers for determining which nodes to show
147→// ============================================================================
148→
149→function getNodesForMode(
150→	mode: NodesToConsider,
151→	selectedNodes: Set<Node>,
152→	hasSurfacePosition: boolean,
153→): Node[] {
154→	let nodes: Node[];
155→	switch (mode) {
156→		case NodesToConsider.STANDARD:
157→			nodes = [...standardNodes];
158→			break;
159→		case NodesToConsider.PHYSICAL:
160→			nodes = Object.entries(nodeTypes)
161→				.filter(([, type]) => type === NodeType.BODY)
162→				.map(([node]) => node as Node);
163→			break;
164→		case NodesToConsider.ALL:
165→			nodes = Array.from(selectedNodes);
166→			break;
167→	}
168→
169→	// Always include ASC and MC if we have a surface position
170→	if (hasSurfacePosition) {
171→		if (!nodes.includes(Node.ASCENDANT)) nodes.push(Node.ASCENDANT);
172→		if (!nodes.includes(Node.MIDHEAVEN)) nodes.push(Node.MIDHEAVEN);
173→	}
174→
175→	// Filter out location-dependent nodes if no surface position
176→	if (!hasSurfacePosition) {
177→		nodes = nodes.filter(n => !nodeDependsOnLocation[n]);
178→	}
179→
180→	return nodes;
181→}
182→
183→// ============================================================================
184→// Cell helper: checks if a cell is applicable for a given node
185→// ============================================================================
186→
187→type CellApplicability = 'applicable' | 'not-applicable' | 'no-data';
188→
189→function getCellApplicability(node: Node, column: string, hasSurfacePosition: boolean): CellApplicability {
190→	const isStandard = standardNodes.includes(node);
191→	const isAngle = mainAngles.includes(node);
192→
193→	switch (column) {
194→		case 'dignity':
195→		case 'face':
196→		case 'bound':
197→		case 'triplicity':
198→		case 'sect':
199→		case 'dispositorship':
200→			return isStandard ? 'applicable' : 'not-applicable';
201→		case 'house':
202→		case 'angularity':
203→			return hasSurfacePosition ? 'applicable' : 'no-data';
204→		case 'angleProximity':
205→			return (hasSurfacePosition && !isAngle) ? 'applicable' : 'not-applicable';
206→		default:
207→			return 'applicable';
208→	}
209→}
210→
211→
212→// ============================================================================
213→// PlanetTable component
214→// ============================================================================
215→
216→type PlanetTableProps = {
217→	nodePositions: NodePositions;
218→	nodeVelocities: NodeVelocities;
219→	zodiacSignPositions: ZodiacSignPositions;
220→	fixedStarPositions: FixedStarPositions;
221→	houseCuspPositions: HouseCuspPositions | null;
222→	rulershipGraph: RulershipGraph;
223→	aspects: Map<Aspect, Aspect[]>;
224→	nodesToConsider: NodesToConsider;
225→	setHighlightedNode: (node: Node) => void;
226→};
227→
228→// Column widths (px) — easy to tweak
229→const COL = {
230→	node: 70, // TODO this will not be wide enough for more general nodes. need shortnames or something
231→	sign: 40,
232→	position: 40,
233→	house: 50,
234→	angularity: 40,
235→	dignity: 40,
236→	speed: 50,
237→	aspects: 30,
238→	configs: 30,
239→	sect: 40,
240→	face: 36,
241→	bound: 36,
242→	triplicity: 56,
243→	stars: 100,
244→	angleProx: 64,
245→};
246→
247→const ROW_H = 28;
248→
249→const PlanetTable: FC<PlanetTableProps> = ({
250→	nodePositions,
251→	nodeVelocities,
252→	zodiacSignPositions,
253→	fixedStarPositions,
254→	houseCuspPositions,
255→	// rulershipGraph — available via props but not currently used
256→	aspects,
257→	nodesToConsider,
258→	setHighlightedNode,
259→}) => {
260→	const dignityMode = useSettingsStore(s => s.dignityMode);
261→	const houseAngularityMode = useSettingsStore(s => s.houseAngularityMode);
262→	const lunarNodeMode = useSettingsStore(s => s.lunarNodeMode);
263→	const stationaryThreshold = useSettingsStore(s => s.stationarySpeedPercentageThreshold) / 100;
264→	const useFixedStars = useSettingsStore(s => s.useFixedStars);
265→	const fixedStarMaxDistance = useSettingsStore(s => s.fixedStarMaximumDistance);
266→	const useExtendedDignities = useSettingsStore(s => s.useExtendedDignities);
267→	const triplicityMode = useSettingsStore(s => s.triplicityMode);
268→	const faceMode = useSettingsStore(s => s.faceMode);
269→	const boundsMode = useSettingsStore(s => s.boundsMode);
270→	const selectedNodes = useSettingsStore(s => s.selectedNodes);
271→
272→	// render deps
273→	useSettingsStore(s => s.showNodeLabels);
274→	useSettingsStore(s => s.showSymbolLabels);
275→
276→	const hasSurfacePosition = nodePositions.hasSurfacePosition();
277→
278→	const chartRuler = useMemo(
279→		() => hasSurfacePosition ? getChartRuler(nodePositions, zodiacSignPositions, dignityMode) : null,
280→		[nodePositions, zodiacSignPositions, dignityMode, hasSurfacePosition]
281→	);
282→
283→	const houseAngularities = useMemo(
284→		() => houseCuspPositions !== null
285→			? getHouseAngularities(nodePositions, houseCuspPositions, houseAngularityMode)
286→			: null,
287→		[nodePositions, houseCuspPositions, houseAngularityMode]
288→	);
289→
290→	const nodes = useMemo(
291→		() => getNodesForMode(nodesToConsider, selectedNodes, hasSurfacePosition),
292→		[nodesToConsider, selectedNodes, hasSurfacePosition]
293→	);
294→
295→	const rows: NodeRowData[] = useMemo(() => {
296→		return nodes.map(node => computeRowData(
297→			node, nodePositions, nodeVelocities, zodiacSignPositions,
298→			fixedStarPositions, houseCuspPositions, houseAngularities, aspects,
299→			chartRuler, dignityMode, lunarNodeMode, stationaryThreshold,
300→			useFixedStars, fixedStarMaxDistance, useExtendedDignities,
301→			triplicityMode, faceMode, boundsMode, hasSurfacePosition,
302→		));
303→	}, [
304→		nodes, nodePositions, nodeVelocities, zodiacSignPositions,
305→		fixedStarPositions, houseCuspPositions, houseAngularities, aspects,
306→		chartRuler, dignityMode, lunarNodeMode, stationaryThreshold,
307→		useFixedStars, fixedStarMaxDistance, useExtendedDignities,
308→		triplicityMode, faceMode, boundsMode, hasSurfacePosition,
309→	]);
310→
311→	// ── Rendering helpers ──
312→
313→	const cellClass = "flex items-center justify-center overflow-hidden";
314→
315→	const renderInapplicableCell = (width: number) => (
316→		<div className={cellClass} style={{ width, height: ROW_H }}>
317→			<span className="text-theme-text opacity-20 text-xs">—</span>
318→		</div>
319→	);
320→
321→	const renderCell = (
322→		content: React.ReactNode,
323→		width: number,
324→		applicability: CellApplicability = 'applicable',
