					highlightedAspect={highlightedAspect}
					highlightedNode={highlightedNode}
					setHighlightedNode={setHighlightedNode}
				/>
				<PlanetTable
					nodePositions={nodePositions}
					nodeVelocities={nodeVelocities}
					zodiacSignPositions={zodiacSignPositions}
