141→		if (!nodes.includes(Node.MIDHEAVEN)) nodes.push(Node.MIDHEAVEN);
142→	}
143→
144→	// Filter out location-dependent nodes if no surface position
145→	if (!hasSurfacePosition) {
146→		nodes = nodes.filter(n => !nodeDependsOnLocation[n]);
