256→		nodes, nodePositions, nodeVelocities, zodiacSignPositions,
257→		houseCuspPositions, houseAngularities, aspects,
258→		chartRuler, dignityMode, lunarNodeMode, stationaryThreshold,
259→		useExtendedDignities, faceMode, boundsMode, hasSurfacePosition,
260→	]);
261→
262→	// ── Rendering helpers ──
263→
264→	const cellClass = "flex items-center justify-center overflow-hidden";
265→
266→	const renderInapplicableCell = (width: number) => (
267→		<div className={cellClass} style={{ width, height: ROW_H }}>
268→			<span className="text-theme-text opacity-20 text-xs">—</span>
269→		</div>
270→	);
271→
272→	const renderCell = (
273→		content: React.ReactNode,
274→		width: number,
275→		applicability: CellApplicability = 'applicable',
