287→			</div>
288→		);
289→	};
290→
291→	const HEADER_H = 48;
292→	const HEADER_ANGLE = 0; // degrees
293→	const HEADER_FORWARD_DISPL = 0; // px
294→
295→	const headerCell = (label: string, width: number) => (
296→		<div
297→			className="flex items-end justify-center overflow-visible"
