332→				{headerCell("Pos", COL.position)}
333→				{showHouse && headerCell("House", COL.house)}
334→				{headerCell("Dig", COL.dignity)}
335→				{headerCell("Speed", COL.speed)}
336→				{headerCell("#Asp", COL.aspects)}
337→				{headerCell("#Cfg", COL.configs)}
338→				{showSect && headerCell("Sect", COL.sect)}
339→				{showFace && headerCell("Face", COL.face)}
340→				{showBound && headerCell("Bnd", COL.bound)}
341→			</div>
