343→			{/* Rows */}
344→			{rows.map((row) => {
345→				const app = (col: string) => getCellApplicability(row.node, col, hasSurfacePosition);
346→
347→				const speedClass = (row.isRetrograde || row.isStationary) ? "underline" : "";
348→				const speedPrefix = row.isRetrograde ? "R " : row.isStationary ? "S " : "";
349→
350→				const angLabel = angularityLabel(row.angularity);
351→
352→				return (
353→					<div
354→						key={row.node}
355→						className={`flex border-b border-theme-border/30 hover:bg-theme-text/5 cursor-pointer ${row.isChartRuler ? "bg-theme-text/[0.04]" : ""}`}
356→						onClick={() => setHighlightedNode(row.node)}
357→					>
358→						{/* Node — right-justified with solid right border */}
359→						<div
360→							className="flex items-center justify-end pr-1.5 overflow-hidden border-r border-theme-border/50"
361→							style={{ width: COL.node, height: ROW_H }}
362→						>
363→							{renderNode(row.node, { size: 16, fontSize: 10, abbreviated: true })}
364→						</div>
365→
366→						{/* Sign */}
367→						{renderCell(
368→							renderSign(row.sign, undefined, { size: 16, fontSize: 10, abbreviated: true }),
369→							COL.sign,
370→						)}
371→
372→						{/* Position in sign */}
373→						{renderCell(
374→							renderString(formatAngle(row.positionInSign), { fontSize: 10 }),
375→							COL.position,
376→						)}
377→
378→						{/* House + angularity */}
379→						{showHouse && renderCell(
380→							row.houseNumber !== null ? (
381→								<>
382→									{renderString(String(row.houseNumber), { fontSize: 10 })}
383→									{angLabel && (
384→										<>
385→											{renderString("\u00A0·\u00A0", { fontSize: 10 })}
386→											{renderString(angLabel, { fontSize: 10 })}
387→										</>
388→									)}
389→								</>
390→							) : null,
391→							COL.house,
392→							app('house'),
393→						)}
394→
395→						{/* Dignity */}
396→						{renderCell(
397→							row.dignityLabel ? renderString(row.dignityLabel, { fontSize: 10 }) : null,
398→							COL.dignity,
399→							app('dignity'),
400→						)}
401→
402→						{/* Speed */}
403→						{renderCell(
404→							<span className={speedClass}>
405→								{renderString(`${speedPrefix}${row.speedLabel}`, { fontSize: 10 })}
406→							</span>,
407→							COL.speed,
408→						)}
409→
410→						{/* Aspects count */}
411→						{renderCell(
412→							renderString(String(row.nAspects), { fontSize: 10 }),
413→							COL.aspects,
414→						)}
415→
416→						{/* Configurations count */}
417→						{renderCell(
418→							row.nConfigurations > 0
419→								? renderString(String(row.nConfigurations), { fontSize: 10 })
420→								: <span className="opacity-30">{renderString("0", { fontSize: 10 })}</span>,
421→							COL.configs,
422→						)}
423→
424→						{/* Sect */}
425→						{showSect && renderCell(
426→							row.inSect !== null
427→								? renderString(row.inSect ? "In" : "Out", { fontSize: 10 })
428→								: null,
429→							COL.sect,
430→							app('sect'),
431→						)}
432→
433→						{/* Face lord */}
434→						{showFace && renderCell(
435→							row.faceLord ? renderNode(row.faceLord, { size: 14, fontSize: 9 }) : null,
436→							COL.face,
437→							app('face'),
438→						)}
439→
440→						{/* Bound lord */}
441→						{showBound && renderCell(
442→							row.boundLord ? renderNode(row.boundLord, { size: 14, fontSize: 9 }) : null,
443→							COL.bound,
444→							app('bound'),
445→						)}
446→					</div>
447→				);
448→			})}
449→		</div>
450→	);
451→};
452→
453→export default PlanetTable;
