	sign: ReturnType<typeof getSignOfNode>;
	positionInSign: number;
	houseNumber: number | null;
	angularity: string | null;
	dignityLabel: string | null;
	isRetrograde: boolean;
	isStationary: boolean;
	speedLabel: string;
	nAspects: number;
	nConfigurations: number;
	inSect: boolean | null;
